INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e063821c-3ee7-4aeb-b11d-06ca7dd96277', '郊居言志', '郊居言志', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["負暄衡門下，望雲歸遠山。","但要尊中物，餘事豈相關。","交無是非責，且得任疎頑。","日夕臨清澗，逍遙思慮閑。","出去唯空屋，弊簀委窗間。","何異林棲鳥，戀此復來還。","世榮斯獨已，頹志亦何攀。","唯當歲豐熟，閭里一歡顏。"]', '["負暄衡门下，望云归远山。","但要尊中物，餘事豈相关。","交無是非責，且得任疎頑。","日夕臨清澗，逍遙思慮闲。","出去唯空屋，弊簀委窗间。","何異林棲鸟，戀此复来還。","世榮斯独已，頹志亦何攀。","唯當歲豐熟，閭里一歡顏。"]', '诗', 'shi', '', NULL, '郊居言志 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb73d925-bf57-4697-9fd3-86cbb24e3da9', '夏景端居即事', '夏景端居即事', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["北齋有涼氣，嘉樹對層城。","重門永日掩，清池夏雲生。","遇此庭訟簡，始聞蟬初鳴。","逾懷故園愴，默默以緘情。"]', '["北斋有涼氣，嘉樹对層城。","重门永日掩，清池夏云生。","遇此庭訟簡，始闻蟬初鳴。","逾懷故园愴，默默以緘情。"]', '诗', 'shi', '', NULL, '夏景端居即事 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25b3c434-d88b-4b82-8700-b23c20d062ee', '始至郡', '始至郡', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["湓城古雄郡，橫江千里馳。","高樹上迢遞，峻堞繞欹危。","井邑煙火晚，郊原草樹滋。","洪流蕩北阯，崇嶺鬱南圻。","斯民本樂生，逃逝竟何爲。","旱歲屬荒歉，舊逋積如坻。","到郡方逾月，終朝理亂絲。","賓朋未及讌，簡牘已云疲。","昔賢播高風，得守愧無施。","豈待干戈戢，且願撫惸嫠。"]', '["湓城古雄郡，橫江千里驰。","高樹上迢遞，峻堞繞欹危。","井邑煙火晚，郊原草樹滋。","洪流蕩北阯，崇嶺鬱南圻。","斯民本乐生，逃逝竟何爲。","旱歲屬荒歉，旧逋積如坻。","到郡方逾月，終朝理亂絲。","賓朋未及讌，簡牘已云疲。","昔賢播高风，得守愧無施。","豈待干戈戢，且願撫惸嫠。"]', '诗', 'shi', '', NULL, '始至郡 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cabb29e-c387-4968-8062-7e1a9b363cf6', '郡中西齋', '郡中西斋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["似與塵境絕，蕭條齋舍秋。","寒花獨經雨，山禽時到州。","清觴養真氣，玉書示道流。","豈將符守戀，幸已棲心幽。"]', '["似與塵境絕，蕭條斋舍秋。","寒花独經雨，山禽时到州。","清觴養真氣，玉书示道流。","豈將符守戀，幸已棲心幽。"]', '诗', 'shi', '', NULL, '郡中西齋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50958d41-0e54-47f7-a739-3d04c7e0badd', '新理西齋', '新理西斋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["方將甿訟理，久翳西齋居。","草木無行次，閑暇一芟除。","春陽土脉起，膏澤發生初。","養條刊朽枿，護藥鋤穢蕪。","稍稍覺林聳，歷歷忻竹疎。","始見庭宇曠，頓令煩抱舒。","茲焉即可愛，何必是吾廬。"]', '["方將甿訟理，久翳西斋居。","草木無行次，闲暇一芟除。","春陽土脉起，膏澤發生初。","養條刊朽枿，護藥鋤穢蕪。","稍稍覺林聳，歷歷忻竹疎。","始见庭宇曠，頓令煩抱舒。","茲焉即可愛，何必是吾廬。"]', '诗', 'shi', '', NULL, '新理西齋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49f30a36-14b1-4321-8ccc-67966a670d38', '曉坐西齋', '晓坐西斋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["鼕鼕城鼓動，稍稍林鵶去。","柳意不勝春，巖光已知曙。","寢齋有單祶，靈藥爲朝茹。","盥漱忻景清，焚香澄神慮。","公門自常事，道心寧易處。"]', '["鼕鼕城鼓动，稍稍林鵶去。","柳意不勝春，巖光已知曙。","寢斋有單祶，靈藥爲朝茹。","盥漱忻景清，焚香澄神慮。","公门自常事，道心寧易处。"]', '诗', 'shi', '', NULL, '曉坐西齋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcd6b747-8c65-4538-b55a-68365c12c5b1', '郡齋臥疾絕句', '郡斋臥疾絕句', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["香爐宿火滅，蘭燈宵影微。","秋齋獨臥病，誰與覆寒衣。"]', '["香爐宿火滅，蘭灯宵影微。","秋斋独臥病，誰與覆寒衣。"]', '诗', 'shi', '', NULL, '郡齋臥疾絕句 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92a8c771-a237-4c5c-98fb-967493203d8c', '寓居永定精舍', '寓居永定精舍', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["政拙忻罷守，閑居初理生。","家貧何由往，夢想在京城。","野寺霜露月，農興羈旅情。","聊租二頃田，方課子弟耕。","眼暗文字廢，身閑道心精。","即與人羣遠，豈謂是非嬰。"]', '["政拙忻罷守，闲居初理生。","家貧何由往，梦想在京城。","野寺霜露月，農兴羈旅情。","聊租二頃田，方課子弟耕。","眼暗文字廢，身闲道心精。","即與人羣远，豈謂是非嬰。"]', '诗', 'shi', '', NULL, '寓居永定精舍 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a357da09-a6e3-4dd0-aa52-e4226e1e263a', '永定寺喜辟強夜至', '永定寺喜辟強夜至', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["子有新歲慶，獨此苦寒歸。","夜叩竹林寺，山行雪滿衣。","深爐正燃火，空齋共掩扉。","還將一尊對，無言百事違。"]', '["子有新歲慶，独此苦寒归。","夜叩竹林寺，山行雪满衣。","深爐正燃火，空斋共掩扉。","還將一尊对，無言百事違。"]', '诗', 'shi', '', NULL, '永定寺喜辟強夜至 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30baebaf-f18c-403f-93c1-225270bc30a4', '野居', '野居', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["結髮屢辭秩，立身本疎慢。","今得罷守歸，幸無世欲患。","棲止且偏僻，嬉遊無早晏。","逐兔上坡岡，捕魚緣赤澗。","高歌意氣在，貰酒貧居慣。","時啓北窗扉，豈將文墨間。"]', '["結髮屢辞秩，立身本疎慢。","今得罷守归，幸無世欲患。","棲止且偏僻，嬉游無早晏。","逐兔上坡岡，捕鱼緣赤澗。","高歌意氣在，貰酒貧居慣。","时啓北窗扉，豈將文墨间。"]', '诗', 'shi', '', NULL, '野居 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7edbb6e-06a3-431b-91e5-5961bfb76ac4', '同襃子秋齋獨宿', '同襃子秋斋独宿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["山月皎如燭，風霜時動竹。","夜半鳥驚栖，窗間人獨宿。"]', '["山月皎如燭，风霜时动竹。","夜半鸟驚栖，窗间人独宿。"]', '诗', 'shi', '', NULL, '同襃子秋齋獨宿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c0858f4-ce2a-4b15-bbe3-409613818c98', '餌黃精', '餌黄精', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["靈藥出西山，服食採其根。","九蒸換凡骨，經著上世言。","候火起中夜，馨香滿南軒。","齋居感衆靈，藥術啓妙門。","自懷物外心，豈與俗士論。","終期脫印綬，永與天壤存。"]', '["靈藥出西山，服食採其根。","九蒸換凡骨，經著上世言。","候火起中夜，馨香满南軒。","斋居感衆靈，藥術啓妙门。","自懷物外心，豈與俗士論。","終期脫印綬，永與天壤存。"]', '诗', 'shi', '', NULL, '餌黃精 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a295e311-8d1a-42c7-ab13-e4a0528c14a1', '昭國里第聽元老師彈琴', '昭国里第听元老師彈琴', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["竹林高宇霜露清，朱絲玉徽多故情。","暗識啼烏與別鶴，秪緣中有斷腸聲。"]', '["竹林高宇霜露清，朱絲玉徽多故情。","暗識啼烏與別鹤，秪緣中有斷腸声。"]', '诗', 'shi', '', NULL, '昭國里第聽元老師彈琴 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d40a304-5843-4354-b487-bc3b59546be4', '野次聽元昌奏橫吹', '野次听元昌奏橫吹', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["立馬蓮塘吹橫笛，微風動柳生水波。","北人聽罷淚將落，南朝曲中怨更多。"]', '["立马蓮塘吹橫笛，微风动柳生水波。","北人听罷泪將落，南朝曲中怨更多。"]', '诗', 'shi', '', NULL, '野次聽元昌奏橫吹 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05984348-1969-42a8-9bbd-d6290dcd3faa', '樓中閱清管', '楼中閱清管', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["山陽遺韻在，林端橫吹驚。","響迥憑高閣，曲怨繞秋城。","淅瀝危葉振，蕭瑟涼氣生。","始遇茲管賞，已懷故園情。"]', '["山陽遺韻在，林端橫吹驚。","响迥憑高閣，曲怨繞秋城。","淅瀝危葉振，蕭瑟涼氣生。","始遇茲管賞，已懷故园情。"]', '诗', 'shi', '', NULL, '樓中閱清管 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deb47270-36fd-46b0-a155-9575a6e6cbef', '寒食', '寒食', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["晴明寒食好，春園百卉開。","綵繩拂花去，輕毬度閣來。","長歌送落日，緩吹逐殘杯。","非關無燭罷，良爲羈思催。"]', '["晴明寒食好，春园百卉开。","綵繩拂花去，轻毬度閣来。","长歌送落日，緩吹逐殘杯。","非关無燭罷，良爲羈思催。"]', '诗', 'shi', '', NULL, '寒食 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c406f7c-f09f-4904-b008-ab635a437edc', '七夕', '七夕', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["人世拘形跡，別去間山川。","豈意靈仙偶，相望亦彌年。","夕衣清露濕，晨駕秋風前。","臨歡定不住，當爲何所牽。"]', '["人世拘形跡，別去间山川。","豈意靈仙偶，相望亦彌年。","夕衣清露濕，晨駕秋风前。","臨歡定不住，當爲何所牽。"]', '诗', 'shi', '', NULL, '七夕 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e08720d2-988a-410f-8bb1-517c5d45ba8e', '九日', '九日', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["今朝把酒復惆悵，憶在杜陵田舍時。","明年九日知何處，世難還家未有期。"]', '["今朝把酒复惆悵，憶在杜陵田舍时。","明年九日知何处，世难還家未有期。"]', '诗', 'shi', '', NULL, '九日 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('126db7d2-e538-4d47-8598-e4ba1846a5e7', '秋夜', '秋夜', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["暗窗涼葉動，秋天寢席單。","憂人半夜起，明月在林端。","一與清景遇，每憶平生歡。","如何方惻愴，披衣露更寒。"]', '["暗窗涼葉动，秋天寢席單。","憂人半夜起，明月在林端。","一與清景遇，每憶平生歡。","如何方惻愴，披衣露更寒。"]', '诗', 'shi', '', NULL, '秋夜 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e727d000-c6e9-4958-83cf-d00f5b5d007f', '秋夜一絕', '秋夜一絕', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["高閣漸凝露，涼葉稍飄闈。","憶在南宮直，夜長鐘漏稀。"]', '["高閣漸凝露，涼葉稍飄闈。","憶在南宮直，夜长鐘漏稀。"]', '诗', 'shi', '', NULL, '秋夜一絕 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70fb7b8b-138f-4840-8d35-ea1c51de8661', '滁城對雪', '滁城对雪', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["晨起滿闈雪，憶朝閶闔時。","玉座分曙早，金爐上煙遲。","飄散雲臺下，凌亂桂樹姿。","廁跡鴛鷺末，蹈舞豐年期。","今朝覆山郡，寂寥復何爲。"]', '["晨起满闈雪，憶朝閶闔时。","玉座分曙早，金爐上煙遲。","飄散云台下，凌亂桂樹姿。","廁跡鴛鷺末，蹈舞豐年期。","今朝覆山郡，寂寥复何爲。"]', '诗', 'shi', '', NULL, '滁城對雪 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b06600c-dbed-4c17-8c33-4d1311fc18e5', '雪中', '雪中', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["空堂歲已晏，密室獨安眠。","厭篠夜偏積，覆閣曉逾妍。","連山暗古郡，驚風散一川。","此時騎馬出，忽省京華年。"]', '["空堂歲已晏，密室独安眠。","厭篠夜偏積，覆閣晓逾妍。","連山暗古郡，驚风散一川。","此时騎马出，忽省京华年。"]', '诗', 'shi', '', NULL, '雪中 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce495d54-3376-4a50-8bdc-fcdb1ddf7ff3', '詠春雪', '詠春雪', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["裴回輕雪意，似惜豔陽時。","不悟風花冷，翻令梅柳遲。"]', '["裴回轻雪意，似惜豔陽时。","不悟风花冷，翻令梅柳遲。"]', '诗', 'shi', '', NULL, '詠春雪 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6214b9e-aaff-4901-8e33-9ffabe1d18c9', '對春雪', '对春雪', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["蕭屑杉松聲，寂寥寒夜慮。","州貧人吏稀，雪滿山城曙。","春塘看幽谷，栖禽愁未去。","開闈正亂流，寧辨花枝處。"]', '["蕭屑杉松声，寂寥寒夜慮。","州貧人吏稀，雪满山城曙。","春塘看幽谷，栖禽愁未去。","开闈正亂流，寧辨花枝处。"]', '诗', 'shi', '', NULL, '對春雪 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63a73bbf-80a8-4f7d-8a31-374cabf68739', '對殘燈', '对殘灯', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["獨照碧窗久，欲隨寒燼滅。","幽人將遽眠，解帶翻成結。"]', '["独照碧窗久，欲隨寒燼滅。","幽人將遽眠，解带翻成結。"]', '诗', 'shi', '', NULL, '對殘燈 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0f1ddfc-486d-4bdd-8348-abf7def5f66b', '對芳尊', '对芳尊', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["對芳尊，醉來百事何足論。","遙見青山始一醒，欲著接[䍦]還復昏。"]', '["对芳尊，醉来百事何足論。","遙见青山始一醒，欲著接[䍦]還复昏。"]', '诗', 'shi', '', NULL, '對芳尊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b85cc556-4a81-4703-b084-0e165c508679', '夜對流螢作', '夜对流螢作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["月暗竹亭幽，螢光拂席流。","還思故園夜，更度一年秋。","自愜觀書興，何慙秉燭遊。","府中徒冉冉，明發好歸休。"]', '["月暗竹亭幽，螢光拂席流。","還思故园夜，更度一年秋。","自愜观书兴，何慙秉燭游。","府中徒冉冉，明發好归休。"]', '诗', 'shi', '', NULL, '夜對流螢作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df7f8307-25e1-4af1-ab07-30304bec7c89', '對新篁', '对新篁', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["新綠苞初解，嫩氣筍猶香。","含露漸舒葉，抽叢稍自長。","清晨止亭下，獨愛此幽篁。"]', '["新綠苞初解，嫩氣筍猶香。","含露漸舒葉，抽叢稍自长。","清晨止亭下，独愛此幽篁。"]', '诗', 'shi', '', NULL, '對新篁 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aec5dce-dcbc-453e-8a75-cf99e538e220', '夏花明', '夏花明', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["夏條綠已密，朱蕚綴明鮮。","炎炎日正午，灼灼火俱燃。","翻風適自亂，照水復成妍。","歸視窗間字，熒煌滿眼前。"]', '["夏條綠已密，朱蕚綴明鲜。","炎炎日正午，灼灼火俱燃。","翻风適自亂，照水复成妍。","归視窗间字，熒煌满眼前。"]', '诗', 'shi', '', NULL, '夏花明 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25829246-2d17-47b3-a5d9-d65c2229e9b7', '對萱草', '对萱草', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["何人樹萱草，對此郡齋幽。","本是忘憂物，今夕重生憂。","叢疎露始滴，芳餘蝶尚留。","還思杜陵圃，離披風雨秋。"]', '["何人樹萱草，对此郡斋幽。","本是忘憂物，今夕重生憂。","叢疎露始滴，芳餘蝶尚留。","還思杜陵圃，離披风雨秋。"]', '诗', 'shi', '', NULL, '對萱草 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ffd597-66f5-4b0a-ad5f-8c0c78fd3b90', '見紫荆花', '见紫荆花', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["雜英紛已積，含芳獨暮春。","還如故園樹，忽憶故園人。"]', '["杂英紛已積，含芳独暮春。","還如故园樹，忽憶故园人。"]', '诗', 'shi', '', NULL, '見紫荆花 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a407b18e-4101-475c-9c5b-1bb11966de48', '翫螢火', '翫螢火', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["時節變衰草，物色近新秋。","度月影纔斂，繞竹光復流。"]', '["时節变衰草，物色近新秋。","度月影纔斂，繞竹光复流。"]', '诗', 'shi', '', NULL, '翫螢火 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a96176eb-6c69-48b0-a89f-afc99b4d7f27', '對雜花', '对杂花', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["朝紅爭景新，夕素含露翻。","妍姿如有意，流芳復滿園。","單棲守遠郡，永日掩重門。","不與花爲偶，終遣與誰言。"]', '["朝紅爭景新，夕素含露翻。","妍姿如有意，流芳复满园。","單棲守远郡，永日掩重门。","不與花爲偶，終遣與誰言。"]', '诗', 'shi', '', NULL, '對雜花 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a79604-a632-4896-9e5c-02d7ca200b03', '種藥', '種藥', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["好讀神農書，多識藥草名。","持縑購山客，移蒔羅衆英。","不改幽澗色，宛如此地生。","汲井既蒙澤，插楥亦扶傾。","陰穎夕房斂，陽條夏花明。","悅翫從茲始，日夕繞庭行。","州民自寡訟，養閑非政成。"]', '["好读神農书，多識藥草名。","持縑購山客，移蒔羅衆英。","不改幽澗色，宛如此地生。","汲井既蒙澤，插楥亦扶傾。","陰穎夕房斂，陽條夏花明。","悅翫從茲始，日夕繞庭行。","州民自寡訟，養闲非政成。"]', '诗', 'shi', '', NULL, '種藥 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ed61bf-cd93-4c2c-85b2-0f279429e616', '西澗種柳', '西澗種柳', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["宰邑乖所願，僶俛愧昔人。","聊將休暇日，種柳西澗濱。","置鍤息微倦，臨流睇歸雲。","封壤自人力，生條在陽春。","成陰豈自取，爲茂屬佗辰。","延詠留佳賞，山水變夕曛。"]', '["宰邑乖所願，僶俛愧昔人。","聊將休暇日，種柳西澗濱。","置鍤息微倦，臨流睇归云。","封壤自人力，生條在陽春。","成陰豈自取，爲茂屬佗辰。","延詠留佳賞，山水变夕曛。"]', '诗', 'shi', '', NULL, '西澗種柳 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87551cc4-0323-44a0-a659-830299c47265', '種瓜', '種瓜', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["率性方鹵莽，理生尤自疎。","今年學種瓜，園圃多荒蕪。","衆草同雨露，新苗獨翳如。","直以春窘迫，過時不得鋤。","田家笑枉費，日夕轉空虛。","信非吾儕事，且讀古人書。"]', '["率性方鹵莽，理生尤自疎。","今年学種瓜，园圃多荒蕪。","衆草同雨露，新苗独翳如。","直以春窘迫，過时不得鋤。","田家笑枉費，日夕轉空虛。","信非吾儕事，且读古人书。"]', '诗', 'shi', '', NULL, '種瓜 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccb95bc6-fe19-4fa6-a604-fd880a5ebab8', '喜園中茶生', '喜园中茶生', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["潔性不可汙，爲飲滌塵煩。","此物信靈味，本自出山原。","聊因理郡餘，率爾植荒園。","喜隨衆草長，得與幽人言。"]', '["潔性不可汙，爲饮滌塵煩。","此物信靈味，本自出山原。","聊因理郡餘，率爾植荒园。","喜隨衆草长，得與幽人言。"]', '诗', 'shi', '', NULL, '喜園中茶生 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c780ea99-ebfe-492b-b8ea-7fc3cff4a8f1', '移海榴', '移海榴', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["葉有苦寒色，山中霜霰多。","雖此蒙陽景，移根意如何。"]', '["葉有苦寒色，山中霜霰多。","雖此蒙陽景，移根意如何。"]', '诗', 'shi', '', NULL, '移海榴 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a02bab3f-dba5-4886-9eec-158c2f4942c0', '郡齋移杉', '郡斋移杉', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["[擢]幹方數尺，幽姿已蒼然。","結根西山寺，來植郡齋前。","新含野露氣，稍靜高窗眠。","雖爲賞心遇，豈有巖中緣。"]', '["[擢]幹方數尺，幽姿已蒼然。","結根西山寺，来植郡斋前。","新含野露氣，稍静高窗眠。","雖爲賞心遇，豈有巖中緣。"]', '诗', 'shi', '', NULL, '郡齋移杉 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd1ada14-4196-4abe-b782-f0184f090fa7', '花徑', '花徑', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["山花夾徑幽，古甃生苔澀。","胡牀理事餘，玉琴承露濕。","朝與詩人賞，夜攜禪客入。","自是塵外蹤，無令吏趨急。"]', '["山花夾徑幽，古甃生苔澀。","胡牀理事餘，玉琴承露濕。","朝與诗人賞，夜携禪客入。","自是塵外蹤，無令吏趨急。"]', '诗', 'shi', '', NULL, '花徑 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df16b03f-209f-4e52-a3b4-894f05198158', '慈恩寺南池秋荷詠', '慈恩寺南池秋荷詠', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["對殿含涼氣，裁規覆清沼。","衰紅受露多，餘馥依人少。","蕭蕭遠塵跡，颯颯凌秋曉。","節謝客來稀，迴塘方獨遶。"]', '["对殿含涼氣，裁規覆清沼。","衰紅受露多，餘馥依人少。","蕭蕭远塵跡，颯颯凌秋晓。","節謝客来稀，迴塘方独遶。"]', '诗', 'shi', '', NULL, '慈恩寺南池秋荷詠 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d501bb4-f56d-487c-8fa3-e3d4177f8ad1', '題桐葉', '題桐葉', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["參差剪綠綺，瀟灑覆瓊柯。","憶在灃東寺，偏書此葉多。"]', '["參差剪綠綺，瀟灑覆瓊柯。","憶在灃东寺，偏书此葉多。"]', '诗', 'shi', '', NULL, '題桐葉 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd917e9c-a0d8-4159-b1f4-8487f79e5258', '題石橋', '題石橋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["遠學臨海嶠，橫此莓苔石。","郡齋三四峰，如有靈仙跡。","方愁暮雲滑，始照寒池碧。","自與幽人期，逍遙竟朝夕。"]', '["远学臨海嶠，橫此莓苔石。","郡斋三四峰，如有靈仙跡。","方愁暮云滑，始照寒池碧。","自與幽人期，逍遙竟朝夕。"]', '诗', 'shi', '', NULL, '題石橋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42a7a1c7-ec22-425d-b373-8205a06a4c9d', '池上', '池上', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["郡中臥病久，池上一來賒。","榆柳飄枯葉，風雨倒橫查。"]', '["郡中臥病久，池上一来賒。","榆柳飄枯葉，风雨倒橫查。"]', '诗', 'shi', '', NULL, '池上 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ae0e3bd-a32e-481f-9719-b283da2da964', '滁州西澗', '滁州西澗', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["獨憐幽草澗邊生，上有黃鸝深樹鳴。","春潮帶雨晚來急，野渡無人舟自橫。"]', '["独怜幽草澗邊生，上有黄鸝深樹鳴。","春潮带雨晚来急，野渡無人舟自橫。"]', '诗', 'shi', '', NULL, '滁州西澗 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('087b899d-85a7-4b25-9821-23734600e2bd', '西塞山', '西塞山', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["勢從千里奔，直入江中斷。","嵐橫秋塞雄，地束驚流滿。"]', '["勢從千里奔，直入江中斷。","嵐橫秋塞雄，地束驚流满。"]', '诗', 'shi', '', NULL, '西塞山 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22fdd1b1-e517-4ac6-8e9e-1853be5d94ab', '山耕叟', '山耕叟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["蕭蕭垂白髮，默默詎知情。","獨放寒林燒，多尋虎跡行。","暮歸何處宿？來此空山耕。"]', '["蕭蕭垂白髮，默默詎知情。","独放寒林燒，多尋虎跡行。","暮归何处宿？来此空山耕。"]', '诗', 'shi', '', NULL, '山耕叟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1669cfc7-496d-4dac-b9a8-06d2398d9184', '上方僧', '上方僧', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["見月出東山，上方高處禪。","空林無宿火，獨夜汲寒泉。","不下藍溪寺，今年三十年。"]', '["见月出东山，上方高处禪。","空林無宿火，独夜汲寒泉。","不下藍溪寺，今年三十年。"]', '诗', 'shi', '', NULL, '上方僧 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeb20f84-e730-44d4-93a6-8dd8c137e2c7', '煙際鐘', '煙際鐘', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["隱隱起何處，迢迢送落暉。","蒼茫隨思遠，蕭散逐煙微。","秋野寂云晦，望山僧獨歸。"]', '["隐隐起何处，迢迢送落暉。","蒼茫隨思远，蕭散逐煙微。","秋野寂云晦，望山僧独归。"]', '诗', 'shi', '', NULL, '煙際鐘 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7d7eb34-aa54-485c-8555-d9841b6ada06', '始聞夏蟬', '始闻夏蟬', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["徂夏暑未晏，蟬鳴景已曛。","一聽知何處，高樹但侵雲。","響悲遇衰齒，節謝屬離羣。","還憶郊園日，獨向澗中聞。"]', '["徂夏暑未晏，蟬鳴景已曛。","一听知何处，高樹但侵云。","响悲遇衰齒，節謝屬離羣。","還憶郊园日，独向澗中闻。"]', '诗', 'shi', '', NULL, '始聞夏蟬 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4efc6b54-f7ba-4c18-8fbd-b02ebb9d85cf', '射雉', '射雉', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["走馬上東岡，朝日照野田。","野田雙雉起，翻射斗迴鞭。","雖無百發中，聊取一笑妍。","羽分繡臆碎，頭弛錦鞘懸。","方將悅羈旅，非關學少年。","弢弓一長嘯，憶在灞城阡。"]', '["走马上东岡，朝日照野田。","野田雙雉起，翻射斗迴鞭。","雖無百發中，聊取一笑妍。","羽分繡臆碎，头弛錦鞘懸。","方將悅羈旅，非关学少年。","弢弓一长嘯，憶在灞城阡。"]', '诗', 'shi', '', NULL, '射雉 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4a377b0-921e-4314-a0c3-9aec9f2a0087', '夜聞獨鳥啼', '夜闻独鸟啼', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["失侶度山覓，投林舍北啼。","今將獨夜意，偏知對影栖。"]', '["失侶度山覓，投林舍北啼。","今將独夜意，偏知对影栖。"]', '诗', 'shi', '', NULL, '夜聞獨鳥啼 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd9cee3d-3e21-4a4a-af21-a3d5fc329e34', '述園鹿', '述园鹿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["野性本難畜，翫習亦逾年。","麑班始力直，麚角已蒼然。","仰首嚼園柳，俯身飲清泉。","見人若閑暇，蹶起忽低騫。","茲獸有高貌，凡類寧比肩。","不得遊山澤，跼促誠可憐。"]', '["野性本难畜，翫習亦逾年。","麑班始力直，麚角已蒼然。","仰首嚼园柳，俯身饮清泉。","见人若闲暇，蹶起忽低騫。","茲獸有高貌，凡類寧比肩。","不得游山澤，跼促誠可怜。"]', '诗', 'shi', '', NULL, '述園鹿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6020c5b9-5845-4210-bfcc-9bedda58bc46', '聞鴈', '闻鴈', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["故園眇何處，歸思方悠哉。","淮南秋雨夜，高齋聞鴈來。"]', '["故园眇何处，归思方悠哉。","淮南秋雨夜，高斋闻鴈来。"]', '诗', 'shi', '', NULL, '聞鴈 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79e39705-ed7f-4afa-8c9b-0c02a5487d48', '子規啼', '子規啼', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["高林滴露夏夜清，南山子規啼一聲。","鄰家孀婦抱兒泣，我獨展轉何時明。"]', '["高林滴露夏夜清，南山子規啼一声。","鄰家孀婦抱兒泣，我独展轉何时明。"]', '诗', 'shi', '', NULL, '子規啼 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8f429fc-5a2d-4878-b1cf-055c7e106960', '始建射侯', '始建射侯', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["男子本懸弧，有志在四方。","虎竹忝明命，熊侯始張皇。","賓登時事畢，諸將備戎裝。","星飛的屢破，鼓譟武更揚。","曾習鄒魯學，亦陪鴛鷺翔。","一朝願投筆，世難激中腸。"]', '["男子本懸弧，有志在四方。","虎竹忝明命，熊侯始張皇。","賓登时事畢，諸將備戎裝。","星飞的屢破，鼓譟武更揚。","曾習鄒魯学，亦陪鴛鷺翔。","一朝願投笔，世难激中腸。"]', '诗', 'shi', '', NULL, '始建射侯 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbb74454-abe1-4097-81a9-c47833e2374b', '仙人祠', '仙人祠', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["蒼岑古仙子，清廟閟華容。","千載去寥廓，白雲遺舊蹤。","歸來灞陵上，猶見最高峰。"]', '["蒼岑古仙子，清廟閟华容。","千載去寥廓，白云遺旧蹤。","归来灞陵上，猶见最高峰。"]', '诗', 'shi', '', NULL, '仙人祠 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b62b3e31-6ada-4039-8a3a-ddd7ccce210e', '鷓鴣啼', '鷓鴣啼', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["可憐鷓鴣飛，飛向樹南枝。","南枝日照暖，北枝霜露滋。","露滋不堪栖，使我夜常啼。","願逢雲中鶴，銜我向寥廓。","願作城上烏，一年生九雛。","何不舊巢住，枝弱不得去。","何意道苦辛，客子常畏人。"]', '["可怜鷓鴣飞，飞向樹南枝。","南枝日照暖，北枝霜露滋。","露滋不堪栖，使我夜常啼。","願逢云中鹤，銜我向寥廓。","願作城上烏，一年生九雛。","何不旧巢住，枝弱不得去。","何意道苦辛，客子常畏人。"]', '诗', 'shi', '', NULL, '鷓鴣啼 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c773ccd-f0a2-4a99-ad24-1e989012e084', '長安道', '长安道', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["漢家宮殿含雲煙，兩宮十里相連延。","晨霞出沒弄丹闕，春雨依微自甘泉。","春雨依微春尚早，長安貴遊愛芳草。","寶馬橫來下建章，香車却轉避馳道。","貴遊誰最貴，衛霍世難比。","何能蒙主恩，幸遇邊塵起。","歸來甲第拱皇居，朱門峨峨臨九衢。","中有流蘇合歡之寶帳，一百二十鳳凰羅列含明珠。","下有錦鋪翠被之粲爛，博山吐香五雲散。","麗人綺閣情飄颻，頭上鴛釵雙翠翹。","低鬟曳袖迴春雪，聚黛一聲愁碧霄。","山珍海錯棄藩籬，烹犢炰羔如折葵。","既請列侯封部曲，還將金印授廬兒。","歡榮若此何所苦，但苦白日西南馳。"]', '["漢家宮殿含云煙，兩宮十里相連延。","晨霞出沒弄丹闕，春雨依微自甘泉。","春雨依微春尚早，长安貴游愛芳草。","寶马橫来下建章，香车却轉避驰道。","貴游誰最貴，衛霍世难比。","何能蒙主恩，幸遇邊塵起。","归来甲第拱皇居，朱门峨峨臨九衢。","中有流蘇合歡之寶帳，一百二十鳳凰羅列含明珠。","下有錦鋪翠被之粲爛，博山吐香五云散。","丽人綺閣情飄颻，头上鴛釵雙翠翹。","低鬟曳袖迴春雪，聚黛一声愁碧霄。","山珍海錯棄藩籬，烹犢炰羔如折葵。","既請列侯封部曲，還將金印授廬兒。","歡榮若此何所苦，但苦白日西南驰。"]', '诗', 'shi', '', NULL, '長安道 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8113bae4-1323-4460-82ed-6191665933c0', '行路難', '行路难', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["荆山之白玉兮，良工琱琢雙環連，月蝕中央鏡心穿。","故人贈妾初相結，恩在環中尋不絕。","人情厚薄苦須臾，昔似連環今似玦。","連環可碎不可離，如何物在人自移。","上客勿遽歡，聽妾歌路難。","旁人見環環可憐，不知中有長恨端。"]', '["荆山之白玉兮，良工琱琢雙环連，月蝕中央镜心穿。","故人贈妾初相結，恩在环中尋不絕。","人情厚薄苦須臾，昔似連环今似玦。","連环可碎不可離，如何物在人自移。","上客勿遽歡，听妾歌路难。","旁人见环环可怜，不知中有长恨端。"]', '诗', 'shi', '', NULL, '行路難 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('192eac98-eebf-4e96-accf-b411ae927ab9', '橫塘行', '橫塘行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["妾家住橫塘，夫壻郗家郎。","玉盤的歷雙白魚，寶簟玲瓏透象牀。","象牀可寢魚可食，不知郎意何南北。","岸上種蓮豈得生，池中種槿豈得成。","丈夫一去花落樹，妾獨夜長心未平。"]', '["妾家住橫塘，夫壻郗家郎。","玉盤的歷雙白鱼，寶簟玲瓏透象牀。","象牀可寢鱼可食，不知郎意何南北。","岸上種蓮豈得生，池中種槿豈得成。","丈夫一去花落樹，妾独夜长心未平。"]', '诗', 'shi', '', NULL, '橫塘行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90cd8dbb-6261-4fea-8106-3f419ea2d176', '貴遊行', '貴游行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["漢帝外家子，恩澤少封侯。","垂楊拂白馬，曉日上青樓。","上有顏如玉，高情世無儔。","輕裾含碧煙，窈窕似雲浮。","良時無還景，促節爲我謳。","忽聞豔陽曲，四坐亦已柔。","賓友仰稱歎，一生何所求。","平明擊鍾食，入夜樂未休。","風雨愆歲候，兵戎橫九州。","焉知坐上客，草草心所憂。"]', '["漢帝外家子，恩澤少封侯。","垂楊拂白马，晓日上青楼。","上有顏如玉，高情世無儔。","轻裾含碧煙，窈窕似云浮。","良时無還景，促節爲我謳。","忽闻豔陽曲，四坐亦已柔。","賓友仰稱歎，一生何所求。","平明擊鍾食，入夜乐未休。","风雨愆歲候，兵戎橫九州。","焉知坐上客，草草心所憂。"]', '诗', 'shi', '', NULL, '貴遊行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b3b6833-a9f9-44ec-a726-53f7d18fa4c5', '酒肆行', '酒肆行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["豪家沽酒長安陌，一旦起樓高百尺。","碧疏玲瓏含春風，銀題彩幟邀上客。","迴瞻丹鳳闕，直視樂遊苑。","四方稱賞名已高，五陵車馬無近遠。","晴景悠揚三月天，桃花飄俎柳垂筵。","繁絲急管一時合，他壚鄰肆何寂然。","主人無厭且專利，百斛須臾一壺費。","初醲後薄爲大偷，飲者知名不知味。","深門潛醞客來稀，終歲醇醲味不移。","長安酒徒空擾擾，路傍過去那得知。"]', '["豪家沽酒长安陌，一旦起楼高百尺。","碧疏玲瓏含春风，銀題彩幟邀上客。","迴瞻丹鳳闕，直視乐游苑。","四方稱賞名已高，五陵车马無近远。","晴景悠揚三月天，桃花飄俎柳垂筵。","繁絲急管一时合，他壚鄰肆何寂然。","主人無厭且專利，百斛須臾一壺費。","初醲後薄爲大偷，饮者知名不知味。","深门潛醞客来稀，終歲醇醲味不移。","长安酒徒空擾擾，路傍過去那得知。"]', '诗', 'shi', '', NULL, '酒肆行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bff86ed-d336-4e6f-8015-5708452e8e05', '相逢行', '相逢行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["二十登漢朝，英聲邁今古。","適從東方來，又欲謁明主。","猶酣新豐酒，尚帶灞陵雨。","邂逅兩相逢，別來問寒暑。","寧知白日晚，暫向花間語。","忽聞長樂鐘，走馬東西去。"]', '["二十登漢朝，英声邁今古。","適從东方来，又欲謁明主。","猶酣新豐酒，尚带灞陵雨。","邂逅兩相逢，別来问寒暑。","寧知白日晚，暫向花间語。","忽闻长乐鐘，走马东西去。"]', '诗', 'shi', '', NULL, '相逢行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('469ea255-c1b9-4513-912f-2bc355d80a5c', '烏引雛', '烏引雛', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["日出照東城，春烏鵶鵶雛和鳴。","雛和鳴，羽猶短，巢在深林春正寒，引飛欲集東城暖。","羣雛䙰褷睥睨高，舉翅不及墜蓬蒿。","雄雌來去飛又引，音聲上下懼鷹隼。","引雛烏，爾心急將何如，何得比日搜索雀卵噉爾雛。"]', '["日出照东城，春烏鵶鵶雛和鳴。","雛和鳴，羽猶短，巢在深林春正寒，引飞欲集东城暖。","羣雛䙰褷睥睨高，舉翅不及墜蓬蒿。","雄雌来去飞又引，音声上下懼鷹隼。","引雛烏，爾心急將何如，何得比日搜索雀卵噉爾雛。"]', '诗', 'shi', '', NULL, '烏引雛 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f720b24e-5184-41cf-82ce-ec0332116604', '鳶奪巢', '鳶奪巢', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["野鵲野鵲巢林梢，鴟鳶恃力奪鵲巢。","吞鵲之肝啄鵲腦，竊食偷居還自保。","鳳凰五色百鳥尊，知鳶爲害何不言？","霜鸇野鷂得殘肉，同啄羶腥不肯逐。","可憐百鳥紛縱橫，雖有深林何處宿。"]', '["野鵲野鵲巢林梢，鴟鳶恃力奪鵲巢。","吞鵲之肝啄鵲腦，竊食偷居還自保。","鳳凰五色百鸟尊，知鳶爲害何不言？","霜鸇野鷂得殘肉，同啄羶腥不肯逐。","可怜百鸟紛縱橫，雖有深林何处宿。"]', '诗', 'shi', '', NULL, '鳶奪巢 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('534e29b1-8ad8-4805-98d3-557c8a119798', '燕啣泥', '燕啣泥', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["啣泥燕，聲嘍嘍。","尾涎涎，秋去何所歸。","春來復相見，豈不解決絕高飛碧雲裏。","何爲地上啣泥滓，銜泥雖賤意有營。","杏梁朝日巢欲成，不見百鳥畏人林野宿。","翻遭網羅俎其肉，未若銜泥入華屋。","燕銜泥，百鳥之智莫與齊。"]', '["啣泥燕，声嘍嘍。","尾涎涎，秋去何所归。","春来复相见，豈不解決絕高飞碧云裏。","何爲地上啣泥滓，銜泥雖賤意有營。","杏梁朝日巢欲成，不见百鸟畏人林野宿。","翻遭網羅俎其肉，未若銜泥入华屋。","燕銜泥，百鸟之智莫與齊。"]', '诗', 'shi', '', NULL, '燕啣泥 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('929fca67-0dce-4856-b8fc-3e54cd684c75', '鼙鼓行', '鼙鼓行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["淮海生雲暮慘澹，廣陵城頭顰鼓暗。","寒聲坎坎風動邊，忽似孤城萬里絕，四望無人煙。","又如虜騎截遼水，胡馬不食仰朔天。","座中亦有燕趙士，聞顰不語客心死。","何況鰥孤火絕無晨炊，獨婦夜泣官有期。"]', '["淮海生云暮慘澹，廣陵城头顰鼓暗。","寒声坎坎风动邊，忽似孤城万里絕，四望無人煙。","又如虜騎截遼水，胡马不食仰朔天。","座中亦有燕趙士，闻顰不語客心死。","何況鰥孤火絕無晨炊，独婦夜泣官有期。"]', '诗', 'shi', '', NULL, '鼙鼓行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4525113-a4f7-4a15-a6d0-2b86eea66bca', '古劍行', '古劍行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["千年土中兩刃鐵，土蝕不入金星滅。","沈沈青脊鱗甲滿，蛟龍無足蛇尾斷。","忽欲飛動中有靈，豪士得之敵國寶。","仇家舉意半夜鳴，小兒女子不可近。","龍蛇變化此中隱，夏雲奔走雷闐闐，恐成霹靂飛上天。"]', '["千年土中兩刃鐵，土蝕不入金星滅。","沈沈青脊鱗甲满，蛟龙無足蛇尾斷。","忽欲飞动中有靈，豪士得之敵国寶。","仇家舉意半夜鳴，小兒女子不可近。","龙蛇变化此中隐，夏云奔走雷闐闐，恐成霹靂飞上天。"]', '诗', 'shi', '', NULL, '古劍行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2688eb3-6879-420a-ac30-40e174d85346', '金谷園歌', '金谷园歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["石氏滅，金谷園中水流絕。","當時豪右爭驕侈，錦爲步障四十里。","東風吹花雪滿川，紫氣凝閣朝景妍。","洛陽陌上人迴首，絲竹飄颻入青天。","晉武平吳恣歡燕，餘風靡靡朝廷變。","嗣世衰微誰肯憂，二十四友日日空追遊。","追遊詎可足，共惜年華促。","禍端一發埋恨長，百草無情春自綠。"]', '["石氏滅，金谷园中水流絕。","當时豪右爭驕侈，錦爲步障四十里。","东风吹花雪满川，紫氣凝閣朝景妍。","洛陽陌上人迴首，絲竹飄颻入青天。","晉武平吳恣歡燕，餘风靡靡朝廷变。","嗣世衰微誰肯憂，二十四友日日空追游。","追游詎可足，共惜年华促。","禍端一發埋恨长，百草無情春自綠。"]', '诗', 'shi', '', NULL, '金谷園歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42a7ccb7-50b2-485d-8d11-c660de93bdd2', '溫泉行', '溫泉行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["出身天寶今年幾，頑鈍如鎚命如紙。","作官不了却來歸，還是杜陵一男子。","北風慘慘投溫泉，忽憶先皇遊幸年。","身騎廐馬引天仗，直入華清列御前。","玉林瑤雪滿寒山，上昇玄閣遊絳煙。","平明羽衛朝萬國，車馬合沓溢四鄽。","蒙恩每浴華池水，扈獵不蹂渭北田。","朝廷無事共歡燕，美人絲管從九天。","一朝鑄鼎降龍馭，小臣髯絕不得去。","今來蕭瑟萬井空，唯見蒼山起煙霧。","可憐蹭蹬失風波，仰天大呌無奈何。","弊裘羸馬凍欲死，賴遇主人杯酒多。"]', '["出身天寶今年幾，頑鈍如鎚命如紙。","作官不了却来归，還是杜陵一男子。","北风慘慘投溫泉，忽憶先皇游幸年。","身騎廐马引天仗，直入华清列御前。","玉林瑤雪满寒山，上昇玄閣游絳煙。","平明羽衛朝万国，车马合沓溢四鄽。","蒙恩每浴华池水，扈獵不蹂渭北田。","朝廷無事共歡燕，美人絲管從九天。","一朝鑄鼎降龙馭，小臣髯絕不得去。","今来蕭瑟万井空，唯见蒼山起煙霧。","可怜蹭蹬失风波，仰天大呌無奈何。","弊裘羸马凍欲死，賴遇主人杯酒多。"]', '诗', 'shi', '', NULL, '溫泉行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41b5ff73-9671-418e-9e25-33281e711d80', '學仙二首 一', '学仙二首 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["昔有道士求神仙，靈真下試心確然。","千[鈞]巨石一髮懸，臥之石下十三年。","存道忘身一試過，名奏玉皇乃升天。","雲氣冉冉漸不見，留語弟子但精堅。"]', '["昔有道士求神仙，靈真下試心確然。","千[鈞]巨石一髮懸，臥之石下十三年。","存道忘身一試過，名奏玉皇乃升天。","云氣冉冉漸不见，留語弟子但精堅。"]', '诗', 'shi', '', NULL, '學仙二首 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf0af819-4f06-47cd-b4fc-de8192c8e7d0', '學仙二首 二', '学仙二首 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["石上鑿井欲到水，惰心一起中路止。","豈不見古來三人俱弟兄，結茅深山讀仙經。","上有青冥倚天之絕壁，下有颼飀萬壑之松聲。","仙人變化爲白鹿，二弟翫之兄誦讀。","讀多七過可乞言，爲子心精得神仙。","可憐二弟仰天泣，一失毫釐千萬年。"]', '["石上鑿井欲到水，惰心一起中路止。","豈不见古来三人俱弟兄，結茅深山读仙經。","上有青冥倚天之絕壁，下有颼飀万壑之松声。","仙人变化爲白鹿，二弟翫之兄誦读。","读多七過可乞言，爲子心精得神仙。","可怜二弟仰天泣，一失毫釐千万年。"]', '诗', 'shi', '', NULL, '學仙二首 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24e9b6ac-a1d7-4377-b3e0-3d4046815763', '廣陵行', '廣陵行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["雄藩鎮楚郊，地勢鬱岧嶢。","雙旌擁萬戟，中有霍嫖姚。","海雲助兵氣，寶貨益軍饒。","嚴城動寒角，晚騎踏霜橋。","翕習英豪集，振奪士卒驍。","列郡何足數，趨拜等卑寮。","日宴方云罷，人逸馬蕭蕭。","忽如京洛間，遊子風塵飄。","歸來視寶劍，功名豈一朝。"]', '["雄藩鎮楚郊，地勢鬱岧嶢。","雙旌擁万戟，中有霍嫖姚。","海云助兵氣，寶貨益軍饒。","嚴城动寒角，晚騎踏霜橋。","翕習英豪集，振奪士卒驍。","列郡何足數，趨拜等卑寮。","日宴方云罷，人逸马蕭蕭。","忽如京洛间，游子风塵飄。","归来視寶劍，功名豈一朝。"]', '诗', 'shi', '', NULL, '廣陵行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c129a80-f0f2-48fe-aefc-bd834d041d27', '萼綠華歌', '萼綠华歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["有一人兮昇紫霞，書名玉牒兮蕚綠華。","仙容矯矯兮雜瑤珮，輕衣重重兮蒙絳紗。","雲雨愁思兮望淮海，鼓吹蕭條兮駕龍車。","世淫濁兮不可降，胡不來兮玉斧家。"]', '["有一人兮昇紫霞，书名玉牒兮蕚綠华。","仙容矯矯兮杂瑤珮，轻衣重重兮蒙絳紗。","云雨愁思兮望淮海，鼓吹蕭條兮駕龙车。","世淫濁兮不可降，胡不来兮玉斧家。"]', '诗', 'shi', '', NULL, '萼綠華歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dc10d77-a040-400a-ad15-159ede44b808', '王母歌', '王母歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["衆仙翼神母，羽蓋隨雲起。","上遊玄極杳冥中，下看東海一盃水。","海畔種桃經幾時，千年開花千年子。","玉顏眇眇何處尋，世上茫茫人自死。"]', '["衆仙翼神母，羽蓋隨云起。","上游玄極杳冥中，下看东海一盃水。","海畔種桃經幾时，千年开花千年子。","玉顏眇眇何处尋，世上茫茫人自死。"]', '诗', 'shi', '', NULL, '王母歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bebeb2f-fd6c-4d6f-aabc-b7bf6fd8c31e', '馬明生遇神女歌', '马明生遇神女歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["學仙貴功亦貴精，神女變化感馬生。","石壁千尋啓雙檢，中有玉堂鋪玉簟。","立之一隅不與言，玉體安隱三日眠。","馬生一立心轉堅，知其丹白蒙哀憐。","安期先生來起居，請示金鐺玉佩天皇書。","神女呵責不合見，仙子謝過手足戰。","大瓜玄棗冷如冰，海上摘來朝霞凝。","賜仙復坐對食訖，頷之使去隨煙升。","乃言馬生合不死，少姑教勅令付爾。","安期再拜將生出，一授素書天地畢。"]', '["学仙貴功亦貴精，神女变化感马生。","石壁千尋啓雙檢，中有玉堂鋪玉簟。","立之一隅不與言，玉體安隐三日眠。","马生一立心轉堅，知其丹白蒙哀怜。","安期先生来起居，請示金鐺玉佩天皇书。","神女呵責不合见，仙子謝過手足戰。","大瓜玄棗冷如冰，海上摘来朝霞凝。","賜仙复坐对食訖，頷之使去隨煙升。","乃言马生合不死，少姑教勅令付爾。","安期再拜將生出，一授素书天地畢。"]', '诗', 'shi', '', NULL, '馬明生遇神女歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb75e135-e11d-4e5d-97a3-856632ab2a78', '石鼓歌', '石鼓歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["周宣大獵兮岐之陽，刻石表功兮煒煌煌。","石如鼓形數止十，風雨缺訛苔蘚澀。","今人濡紙脫其文，既擊既埽白黑分。","忽開滿卷不可識，驚潛動蟄走云云。","喘逶迤，相糾錯，乃是宣王之臣史籀作。","一書遺此天地間，精意長存世冥寞。","秦家祖龍還刻石，碣石之罘李斯跡。","世人好古猶共傳，持來比此殊懸隔。"]', '["周宣大獵兮岐之陽，刻石表功兮煒煌煌。","石如鼓形數止十，风雨缺訛苔蘚澀。","今人濡紙脫其文，既擊既埽白黑分。","忽开满卷不可識，驚潛动蟄走云云。","喘逶迤，相糾錯，乃是宣王之臣史籀作。","一书遺此天地间，精意长存世冥寞。","秦家祖龙還刻石，碣石之罘李斯跡。","世人好古猶共傳，持来比此殊懸隔。"]', '诗', 'shi', '', NULL, '石鼓歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34524caf-3aa9-4e98-b10e-3290b1c88ce2', '寶觀主白鸜鵒歌', '寶观主白鸜鵒歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["鸜鵒鸜鵒，衆皆如漆，爾獨如玉。","鸜之鵒之，衆皆蓬蒿下。","爾自三山來，三山處子下人間。","綽約不妝冰雪顏，仙鳥隨飛來掌上。","來掌上，時拂拭。","人心鳥意自無猜，玉指霜毛本同色。","有時一去凌蒼蒼，朝遊汗漫暮玉堂。","巫峽雨中飛暫濕，杏花林裏過來香。","日夕依仁全羽翼，空欲銜環非報德。","豈不及阿母之家青鳥兒，漢宮來往傳消息。"]', '["鸜鵒鸜鵒，衆皆如漆，爾独如玉。","鸜之鵒之，衆皆蓬蒿下。","爾自三山来，三山处子下人间。","綽約不妝冰雪顏，仙鸟隨飞来掌上。","来掌上，时拂拭。","人心鸟意自無猜，玉指霜毛本同色。","有时一去凌蒼蒼，朝游汗漫暮玉堂。","巫峽雨中飞暫濕，杏花林裏過来香。","日夕依仁全羽翼，空欲銜环非報德。","豈不及阿母之家青鸟兒，漢宮来往傳消息。"]', '诗', 'shi', '', NULL, '寶觀主白鸜鵒歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ebc1dc2-353e-40f8-b184-a0ebb82651f1', '彈棊歌', '彈棊歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["圓天方地局，二十四氣子。","劉生絕藝難對曹，客爲歌其能。","請從中央起，中央轉鬬破欲闌。","零落勢背誰能彈，此中舉一得六七。","旋風忽散霹靂疾，履機乘變安可當。","置之死地翻取強，不見短兵反掌收已盡。","唯有猛士守四方，四方又何難。","橫擊且緣邊，豈如昆明與碣石。","一箭飛中隔遠天，神安志愜動十全，滿堂驚視誰得然。"]', '["圓天方地局，二十四氣子。","劉生絕藝难对曹，客爲歌其能。","請從中央起，中央轉鬬破欲闌。","零落勢背誰能彈，此中舉一得六七。","旋风忽散霹靂疾，履機乘变安可當。","置之死地翻取強，不见短兵反掌收已尽。","唯有猛士守四方，四方又何难。","橫擊且緣邊，豈如昆明與碣石。","一箭飞中隔远天，神安志愜动十全，满堂驚視誰得然。"]', '诗', 'shi', '', NULL, '彈棊歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daabbb07-d867-42c4-8907-e18ad56c4a60', '聽鶯曲', '听鶯曲', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["東方欲曙花冥冥，啼鶯相喚亦可聽。","乍去乍來時近遠，纔聞南陌又東城。","忽似上林翻下苑，綿綿蠻蠻如有情。","欲囀不囀意自嬌，羌兒弄笛曲未調。","前聲後聲不相及，秦女學箏指猶澀。","須臾風暖朝日暾，流音變作百鳥喧。","誰家懶婦驚殘夢，何處愁人憶故園？","伯勞飛過聲跼促，戴勝下時桑田綠。","不及流鶯日日啼花間，能使萬家春意閑。","有時斷續聽不了，飛去花枝猶裊裊。","還栖碧樹鎖千門，春漏方殘一聲曉。"]', '["东方欲曙花冥冥，啼鶯相喚亦可听。","乍去乍来时近远，纔闻南陌又东城。","忽似上林翻下苑，綿綿蠻蠻如有情。","欲囀不囀意自嬌，羌兒弄笛曲未調。","前声後声不相及，秦女学箏指猶澀。","須臾风暖朝日暾，流音变作百鸟喧。","誰家懶婦驚殘梦，何处愁人憶故园？","伯勞飞過声跼促，戴勝下时桑田綠。","不及流鶯日日啼花间，能使万家春意闲。","有时斷續听不了，飞去花枝猶裊裊。","還栖碧樹鎖千门，春漏方殘一声晓。"]', '诗', 'shi', '', NULL, '聽鶯曲 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ea64e1a-3207-47ba-8508-f1a8e72cf3f0', '白沙亭逢吳叟歌', '白沙亭逢吳叟歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["龍池宮裏上皇時，羅衫寶帶香風吹。","滿朝豪士今已盡，欲話舊遊人不知。","白沙亭上逢吳叟，愛客脫衣且沽酒。","問之執戟亦先朝，零落艱難却負樵。","親觀文物蒙雨露，見我昔年侍丹霄。","冬狩春祠無一事，歡遊洽宴多頒賜。","嘗陪月夕竹宮齋，每返溫泉灞陵醉。","星歲再周十二辰，爾來不語今爲君。","盛時忽去良可恨，一生坎壈何足云。"]', '["龙池宮裏上皇时，羅衫寶带香风吹。","满朝豪士今已尽，欲話旧游人不知。","白沙亭上逢吳叟，愛客脫衣且沽酒。","问之執戟亦先朝，零落艱难却負樵。","親观文物蒙雨露，见我昔年侍丹霄。","冬狩春祠無一事，歡游洽宴多頒賜。","嘗陪月夕竹宮斋，每返溫泉灞陵醉。","星歲再周十二辰，爾来不語今爲君。","盛时忽去良可恨，一生坎壈何足云。"]', '诗', 'shi', '', NULL, '白沙亭逢吳叟歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9754faca-c7b1-456a-8077-01d741ab5c8d', '送褚校書歸舊山歌', '送褚校书归旧山歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["握珠不返泉，匣玉不歸山。","明皇重士亦如此，忽怪褚生何得還。","方稱羽獵賦，未拜蘭臺職。","漢篋亡書已暗傳，嵩丘遺簡還能識。","朝朝待詔青鏁闈，中有萬年之樹蓬萊池。","世人仰望棲此地，生獨徘徊意何爲。","故山可往薇可採，一自人間星歲改。","藏書壁中苔半侵，洗藥泉中月還在。","春風飲餞灞陵原，莫厭歸來朝市喧。","不見東方朔，避世從容金馬門。"]', '["握珠不返泉，匣玉不归山。","明皇重士亦如此，忽怪褚生何得還。","方稱羽獵賦，未拜蘭台職。","漢篋亡书已暗傳，嵩丘遺簡還能識。","朝朝待詔青鏁闈，中有万年之樹蓬萊池。","世人仰望棲此地，生独徘徊意何爲。","故山可往薇可採，一自人间星歲改。","藏书壁中苔半侵，洗藥泉中月還在。","春风饮餞灞陵原，莫厭归来朝市喧。","不见东方朔，避世從容金马门。"]', '诗', 'shi', '', NULL, '送褚校書歸舊山歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77eede30-2ace-4640-a038-740e60a9b0e6', '五弦行', '五弦行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["美人爲我彈五弦，塵埃忽靜心悄然。","古刀幽磬初相觸，千珠貫斷落寒玉。","中曲又不喧，徘徊夜長月當軒。","如伴風流縈豔雪，更逐落花飄御園。","獨鳳寥寥有時隱，碧霄來下聽還近。","燕姬有恨楚客愁，言之不盡聲能盡。","末曲感我情，解幽釋結和樂生。","壯士有仇未得報，拔劍欲去憤已平。","夜寒酒多愁遽明。"]', '["美人爲我彈五弦，塵埃忽静心悄然。","古刀幽磬初相觸，千珠貫斷落寒玉。","中曲又不喧，徘徊夜长月當軒。","如伴风流縈豔雪，更逐落花飄御园。","独鳳寥寥有时隐，碧霄来下听還近。","燕姬有恨楚客愁，言之不尽声能尽。","末曲感我情，解幽釋結和乐生。","壯士有仇未得報，拔劍欲去憤已平。","夜寒酒多愁遽明。"]', '诗', 'shi', '', NULL, '五弦行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c254bbb4-a234-4959-9830-fbb58b9679c5', '驪山行', '驪山行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["君不見開元至化垂衣裳，厭坐明堂朝萬方。","訪道靈山降聖祖，沐浴華池集百祥。","千乘萬騎被原野，雲霞草木相輝光。","禁仗圍山曉霜切，離宮積翠夜漏長。","玉堦寂歷朝無事，碧樹萎蕤寒更芳。","三清小鳥傳仙語，九華真人奉瓊漿。","下元昧爽漏恆秩，登山朝禮玄元室。","翠華稍隱天半雲，丹閣光明海中日。","羽旗旄節憩瑤臺，清絲妙管從空來。","萬井九衢皆仰望，彩雲白鶴方徘徊。","憑高覽古嗟寰宇，造化茫茫思悠哉。","秦川八水長繚繞，漢氏五陵空崔嵬。","乃言聖祖奉丹經，以年爲日億萬齡。","蒼生咸壽陰陽泰，高謝前王出塵外。","英豪共理天下晏，戎夷讋伏兵無戰。","時豐賦斂未告勞，海闊珍奇亦來獻。","干戈一起文武乖，歡娛已極人事變。","聖皇弓劍墜幽泉，古木蒼山閉宮殿。","纘承鴻業聖明君，威震六合驅妖氛。","太平遊幸今可待，湯泉嵐嶺還氛氳。"]', '["君不见开元至化垂衣裳，厭坐明堂朝万方。","訪道靈山降聖祖，沐浴华池集百祥。","千乘万騎被原野，云霞草木相輝光。","禁仗圍山晓霜切，離宮積翠夜漏长。","玉堦寂歷朝無事，碧樹萎蕤寒更芳。","三清小鸟傳仙語，九华真人奉瓊漿。","下元昧爽漏恆秩，登山朝禮玄元室。","翠华稍隐天半云，丹閣光明海中日。","羽旗旄節憩瑤台，清絲妙管從空来。","万井九衢皆仰望，彩云白鹤方徘徊。","憑高覽古嗟寰宇，造化茫茫思悠哉。","秦川八水长繚繞，漢氏五陵空崔嵬。","乃言聖祖奉丹經，以年爲日億万齡。","蒼生咸壽陰陽泰，高謝前王出塵外。","英豪共理天下晏，戎夷讋伏兵無戰。","时豐賦斂未告勞，海闊珍奇亦来獻。","干戈一起文武乖，歡娛已極人事变。","聖皇弓劍墜幽泉，古木蒼山閉宮殿。","纘承鴻業聖明君，威震六合驱妖氛。","太平游幸今可待，湯泉嵐嶺還氛氳。"]', '诗', 'shi', '', NULL, '驪山行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0c3a566-1b2f-4819-9cef-4bb861f80b97', '漢武帝雜歌三首 一', '漢武帝杂歌三首 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["漢武好神仙，黃金作臺與天近。","王母摘桃海上還，感之西過聊問訊。","欲來不來夜未央，殿前青鳥先迴翔。","綠鬢縈雲裾曳霧，雙節飄颻下仙步。","白日分明到世間，碧空何處來時路。","玉盤捧桃將獻君，踟躕未去留彩雲。","海水桑田幾翻覆，中間此桃四五熟。","可憐穆滿瑤池燕，正值花開不得薦。","花開子熟安可期，邂逅能當漢武時。","顏如芳華潔如玉，心念我皇多嗜欲。","雖留桃核桃有靈，人間糞土種不生。","由來在道豈在藥，徒勞方士海上行。","掩扇一言相謝去，如煙非煙不知處。"]', '["漢武好神仙，黄金作台與天近。","王母摘桃海上還，感之西過聊问訊。","欲来不来夜未央，殿前青鸟先迴翔。","綠鬢縈云裾曳霧，雙節飄颻下仙步。","白日分明到世间，碧空何处来时路。","玉盤捧桃將獻君，踟躕未去留彩云。","海水桑田幾翻覆，中间此桃四五熟。","可怜穆满瑤池燕，正值花开不得薦。","花开子熟安可期，邂逅能當漢武时。","顏如芳华潔如玉，心念我皇多嗜欲。","雖留桃核桃有靈，人间糞土種不生。","由来在道豈在藥，徒勞方士海上行。","掩扇一言相謝去，如煙非煙不知处。"]', '诗', 'shi', '', NULL, '漢武帝雜歌三首 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('243a1044-6bbc-41c3-91d9-df2a60fb9b8f', '漢武帝雜歌三首 二', '漢武帝杂歌三首 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["金莖孤峙兮凌紫煙，漢宮美人望杳然。","通天臺上月初出，承露盤中珠正圓。","珠可飲，壽可永，武皇南面曙欲分。","從空下來玉杯冷，世間綵翠亦作囊。","八月一日仙人方，仙方稱上藥。","靜者服之常綽約，柏梁沈飲自傷神，猶聞駐顏七十春。","乃知甘醲皆是腐腸物，獨有淡泊之水能益人。","千載金盤竟何處，當時鑄金恐不固。","蔓草生來春復秋，碧天何言空墜露。"]', '["金莖孤峙兮凌紫煙，漢宮美人望杳然。","通天台上月初出，承露盤中珠正圓。","珠可饮，壽可永，武皇南面曙欲分。","從空下来玉杯冷，世间綵翠亦作囊。","八月一日仙人方，仙方稱上藥。","静者服之常綽約，柏梁沈饮自傷神，猶闻駐顏七十春。","乃知甘醲皆是腐腸物，独有淡泊之水能益人。","千載金盤竟何处，當时鑄金恐不固。","蔓草生来春复秋，碧天何言空墜露。"]', '诗', 'shi', '', NULL, '漢武帝雜歌三首 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff024b4f-8993-4796-b9f1-2ef66bec9e80', '漢武帝雜歌三首 三', '漢武帝杂歌三首 三', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["漢天子，觀風自南國。","浮舟大江屹不前，蛟龍索鬬風波黑。","春秋方壯雄武才，彎弧叱浪連山開。","愕然觀者千萬衆，舉麾齊呼一矢中。","死蛟浮出不復靈，舳艫千里江水清。","鼓顰餘響數日在，天吳深入魚鼈驚。","左有佽飛落霜翮，右有孤兒貫犀革。","何爲臨深親射蛟，示威以奪諸侯魄。","威可畏，皇可尊，平田校獵書猶陳。","此日從臣何不言，獨有威聲振千古，君不見後嗣尊爲武。"]', '["漢天子，观风自南国。","浮舟大江屹不前，蛟龙索鬬风波黑。","春秋方壯雄武才，彎弧叱浪連山开。","愕然观者千万衆，舉麾齊呼一矢中。","死蛟浮出不复靈，舳艫千里江水清。","鼓顰餘响數日在，天吳深入鱼鼈驚。","左有佽飞落霜翮，右有孤兒貫犀革。","何爲臨深親射蛟，示威以奪諸侯魄。","威可畏，皇可尊，平田校獵书猶陳。","此日從臣何不言，独有威声振千古，君不见後嗣尊爲武。"]', '诗', 'shi', '', NULL, '漢武帝雜歌三首 三 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56277ac5-db9b-4349-af50-9b01cba24df2', '椶櫚蠅拂歌', '椶櫚蠅拂歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["椶櫚爲拂登君席，青蠅掩亂飛四壁。","文如輕羅散如髮，馬尾氂牛不能絜。","柄出湘江之竹碧玉寒，上有纖羅縈縷尋未絕。","左揮右灑繁暑清，孤松一枝風有聲。","麗人紈素可憐色，安能點白還爲黑。"]', '["椶櫚爲拂登君席，青蠅掩亂飞四壁。","文如轻羅散如髮，马尾氂牛不能絜。","柄出湘江之竹碧玉寒，上有纖羅縈縷尋未絕。","左揮右灑繁暑清，孤松一枝风有声。","丽人紈素可怜色，安能点白還爲黑。"]', '诗', 'shi', '', NULL, '椶櫚蠅拂歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e05a9b1a-c0f9-405f-9604-d1dd129da3bd', '信州錄事參軍常曾古鼎歌', '信州錄事參軍常曾古鼎歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["三年糾一郡，獨飲寒泉井。","江南鑄器多鑄銀，罷官無物唯古鼎。","雕螭刻篆相錯盤，地中歲久青苔寒。","左對蒼山右流水，云有古來葛仙子。","葛仙埋之何不還，耕者鎗然得其間。","持示世人不知寶，勸君鍊丹永壽考。"]', '["三年糾一郡，独饮寒泉井。","江南鑄器多鑄銀，罷官無物唯古鼎。","雕螭刻篆相錯盤，地中歲久青苔寒。","左对蒼山右流水，云有古来葛仙子。","葛仙埋之何不還，耕者鎗然得其间。","持示世人不知寶，勸君鍊丹永壽考。"]', '诗', 'shi', '', NULL, '信州錄事參軍常曾古鼎歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9d43686-4b30-4010-976e-5a7ceb94e168', '夏冰歌', '夏冰歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["出自玄泉杳杳之深井，汲在朱明赫赫之炎辰。","九天含露未銷鑠，閶闔初開賜貴人。","碎如墜瓊方截璐，粉壁生寒象筵布。","玉壺紈扇亦玲瓏，座有麗人色俱素。","咫尺炎涼變四時，出門焦灼君詎知。","肥羊甘醴心悶悶，飲此瑩然何所思。","當念闌干鑿者苦，臘月深井汗如雨。"]', '["出自玄泉杳杳之深井，汲在朱明赫赫之炎辰。","九天含露未銷鑠，閶闔初开賜貴人。","碎如墜瓊方截璐，粉壁生寒象筵布。","玉壺紈扇亦玲瓏，座有丽人色俱素。","咫尺炎涼变四时，出门焦灼君詎知。","肥羊甘醴心悶悶，饮此瑩然何所思。","當念闌干鑿者苦，臘月深井汗如雨。"]', '诗', 'shi', '', NULL, '夏冰歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('602a348a-64ac-453a-a85f-d5761aa4961c', '黿頭山神女歌', '黿头山神女歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["黿頭之山，直上洞庭連青天。","蒼蒼煙樹閉古廟，中有蛾眉成水仙。","水府沈沈行路絕，蛟龍出沒無時節。","魂同魍魎潛太陰，身與空山長不滅。","東晉永和今幾代，雲髮素顏猶盼睞。","陰深靈氣靜凝美，的礫龍綃雜瓊珮。","山精木魅不敢親，昏明想像如有人。","蕙蘭瓊芳積煙露，碧窗松月無冬春。","舟客經過奠椒醑，巫女南音歌激楚。","碧水冥空惟鳥飛，長天何處雲隨雨。","紅渠綠蘋芳意多，玉靈蕩漾凌清波。","孤峰絕島儼相向，鬼嘯猿啼垂女蘿。","皓雪瓊枝殊異色，北方絕代徒傾國。","雲沒煙銷不可期，明堂翡翠無人得。","精靈變態狀無方，游龍宛轉驚鴻翔。","湘妃獨立九疑暮，漢女菱歌春日長。","始知仙事無不有，可惜吳宮空白首。"]', '["黿头之山，直上洞庭連青天。","蒼蒼煙樹閉古廟，中有蛾眉成水仙。","水府沈沈行路絕，蛟龙出沒無时節。","魂同魍魎潛太陰，身與空山长不滅。","东晉永和今幾代，云髮素顏猶盼睞。","陰深靈氣静凝美，的礫龙綃杂瓊珮。","山精木魅不敢親，昏明想像如有人。","蕙蘭瓊芳積煙露，碧窗松月無冬春。","舟客經過奠椒醑，巫女南音歌激楚。","碧水冥空惟鸟飞，长天何处云隨雨。","紅渠綠蘋芳意多，玉靈蕩漾凌清波。","孤峰絕島儼相向，鬼嘯猿啼垂女蘿。","皓雪瓊枝殊異色，北方絕代徒傾国。","云沒煙銷不可期，明堂翡翠無人得。","精靈变態狀無方，游龙宛轉驚鴻翔。","湘妃独立九疑暮，漢女菱歌春日长。","始知仙事無不有，可惜吳宮空白首。"]', '诗', 'shi', '', NULL, '黿頭山神女歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99afd192-5306-4638-8fdc-0aaae349ca2d', '寇季膺古刀歌', '寇季膺古刀歌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["古刀寒鋒青槭槭，少年交結平陵客。","求之時代不可知，千痕萬穴如星離。","重疊泥沙更剝落，縱橫鱗甲相參差。","古物有靈知所適，貂裘拂之橫廣席。","陰森白日掩雲虹，錯落池光動金碧。","知君寶此誇絕代，求之不得心常愛。","厭見今時繞指柔，片鋒折刃猶堪佩。","高山成谷蒼海填，英豪埋沒誰所捐。","吳鉤斷馬不知處，幾度煙塵今獨全。","夜光投人人不畏，知君獨識精靈器。","酬恩結思心自知，死生好惡不相棄。","白虎司秋金氣清，高天寥落雲崢嶸。","月肅風淒古堂淨，精芒切切如有聲。","何不跨蓬萊，斬長鯨？","世人所好殊遼闊，千金買鉛徒一割。"]', '["古刀寒鋒青槭槭，少年交結平陵客。","求之时代不可知，千痕万穴如星離。","重叠泥沙更剝落，縱橫鱗甲相參差。","古物有靈知所適，貂裘拂之橫廣席。","陰森白日掩云虹，錯落池光动金碧。","知君寶此誇絕代，求之不得心常愛。","厭见今时繞指柔，片鋒折刃猶堪佩。","高山成谷蒼海填，英豪埋沒誰所捐。","吳鉤斷马不知处，幾度煙塵今独全。","夜光投人人不畏，知君独識精靈器。","酬恩結思心自知，死生好惡不相棄。","白虎司秋金氣清，高天寥落云崢嶸。","月肅风淒古堂淨，精芒切切如有声。","何不跨蓬萊，斬长鯨？","世人所好殊遼闊，千金買鉛徒一割。"]', '诗', 'shi', '', NULL, '寇季膺古刀歌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebed5508-9ff3-45ad-9cc0-6405873f96ba', '凌霧行', '凌霧行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["秋城海霧重，職事凌晨出。","浩浩合元天，溶溶迷朗日。","纔看含鬢白，稍視霑衣密。","道騎全不分，郊樹都如失。","霏微誤噓吸，膚腠生寒慄。","歸當飲一杯，庶用蠲斯疾。"]', '["秋城海霧重，職事凌晨出。","浩浩合元天，溶溶迷朗日。","纔看含鬢白，稍視霑衣密。","道騎全不分，郊樹都如失。","霏微誤噓吸，膚腠生寒慄。","归當饮一杯，庶用蠲斯疾。"]', '诗', 'shi', '', NULL, '凌霧行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aa80b4e-7e90-46bd-8c3b-e052518ae727', '樂燕行', '乐燕行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["良辰且燕樂，樂往不再來。","趙瑟正高張，音響清塵埃。","一彈和妙謳，吹去繞瑤臺。","豔雲凌空散，舞羅起徘徊。","輝輝發衆顏，灼灼歎令才。","當喧既無寂，中飲亦停杯。","華燈何遽升，馳景忽西頹。","高節亦云立，安能滯不迴。"]', '["良辰且燕乐，乐往不再来。","趙瑟正高張，音响清塵埃。","一彈和妙謳，吹去繞瑤台。","豔云凌空散，舞羅起徘徊。","輝輝發衆顏，灼灼歎令才。","當喧既無寂，中饮亦停杯。","华灯何遽升，驰景忽西頹。","高節亦云立，安能滯不迴。"]', '诗', 'shi', '', NULL, '樂燕行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('854d1f98-08a0-4427-a203-084859da79c9', '采玉行', '采玉行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["官府徵白丁，言采藍谿玉。","絕嶺夜無家，深榛雨中宿。","獨婦餉糧還，哀哀舍南哭。"]', '["官府徵白丁，言采藍谿玉。","絕嶺夜無家，深榛雨中宿。","独婦餉糧還，哀哀舍南哭。"]', '诗', 'shi', '', NULL, '采玉行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41dac3f9-ad09-4995-91f2-54da1531657e', '難言', '难言', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["掬土移山望山盡，投石填海望海滿。","持索捕風幾時得，將刀斫水幾時斷。","未若不相知，中心萬仞何由款。"]', '["掬土移山望山尽，投石填海望海满。","持索捕风幾时得，將刀斫水幾时斷。","未若不相知，中心万仞何由款。"]', '诗', 'shi', '', NULL, '難言 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21916b99-d0e3-4113-a735-94b01d9b72f1', '易言', '易言', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["洪爐熾炭燎一毛，大鼎炊湯沃殘雪。","疾影隨形不覺至，千鈞引縷不知絕。","未若同心言，一言和同解千結。"]', '["洪爐熾炭燎一毛，大鼎炊湯沃殘雪。","疾影隨形不覺至，千鈞引縷不知絕。","未若同心言，一言和同解千結。"]', '诗', 'shi', '', NULL, '易言 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64f66003-29a2-473f-9448-f16c88ecea95', '三臺二首 一', '三台二首 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["一年一年老去，明日後日花開。","未報長安平定，萬國豈得銜杯。"]', '["一年一年老去，明日後日花开。","未報长安平定，万国豈得銜杯。"]', '诗', 'shi', '', NULL, '三臺二首 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e490c35-1187-4e2b-b8c8-fdf051ac64c6', '三臺二首 二', '三台二首 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["冰泮寒塘始綠，雨餘百草皆生。","朝來門閤無事，晚下高齋有情。"]', '["冰泮寒塘始綠，雨餘百草皆生。","朝来门閤無事，晚下高斋有情。"]', '诗', 'shi', '', NULL, '三臺二首 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6682456-fbbf-4d0c-8247-718faa3d238f', '上皇三臺', '上皇三台', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["不寐倦長更，披衣出戶行。","月寒秋竹冷，風切夜窗聲。"]', '["不寐倦长更，披衣出戶行。","月寒秋竹冷，风切夜窗声。"]', '诗', 'shi', '', NULL, '上皇三臺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea1773af-78f4-4b65-be08-701d0ccc5e3a', '荅暢參軍', '荅暢參軍', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["秉筆振芳步，少年且吏遊。","官閑高興生，夜直河漢秋。","念與清賞遇，方抱沈疾憂。","嘉言忽見贈，良藥同所瘳。","高樹起栖鴉，晨鐘滿皇州。","淒清露華動，曠朗景氣浮。","偶宦心非累，處喧道自幽。","空虛爲世薄，子獨意綢繆。"]', '["秉笔振芳步，少年且吏游。","官闲高兴生，夜直河漢秋。","念與清賞遇，方抱沈疾憂。","嘉言忽见贈，良藥同所瘳。","高樹起栖鴉，晨鐘满皇州。","淒清露华动，曠朗景氣浮。","偶宦心非累，处喧道自幽。","空虛爲世薄，子独意綢繆。"]', '诗', 'shi', '', NULL, '荅暢參軍 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da435a7-fbdf-40dc-8525-8ff575881363', '南池宴錢子辛賦得科斗', '南池宴錢子辛賦得科斗', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["臨池見科斗，美爾樂有餘。","不憂網與鉤，幸得免爲魚。","且願充文字，登君尺素書。"]', '["臨池见科斗，美爾乐有餘。","不憂網與鉤，幸得免爲鱼。","且願充文字，登君尺素书。"]', '诗', 'shi', '', NULL, '南池宴錢子辛賦得科斗 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a4c1134-9483-4f4a-99e4-c1fd82a3c933', '詠徐正字畫青蠅', '詠徐正字畫青蠅', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["誤點能成物，迷真許一時。","筆端來已久，座上去何遲。","顧白曾無變，聽雞不復疑。","詎勞才子賞，爲入國人詩。"]', '["誤点能成物，迷真許一时。","笔端来已久，座上去何遲。","顧白曾無变，听雞不复疑。","詎勞才子賞，爲入国人诗。"]', '诗', 'shi', '', NULL, '詠徐正字畫青蠅 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17d5250-4117-49cf-916c-857102803f2d', '虞獲子鹿', '虞獲子鹿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["虞獲子鹿，畜之城陬。","園有美草，池有清流。","但見蹶蹶，亦聞呦呦。","誰知其思，巖谷云游。"]', '["虞獲子鹿，畜之城陬。","园有美草，池有清流。","但见蹶蹶，亦闻呦呦。","誰知其思，巖谷云游。"]', '诗', 'shi', '', NULL, '虞獲子鹿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69b44b0f-a238-4d0c-890c-dac1ca608b27', '陪王郎中尋孔徵君', '陪王郎中尋孔徵君', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["俗吏閑居少，同人會面難。","偶隨香署客，來訪竹林歡。","暮館花微落，春城雨暫寒。","甕間聊共酌，莫使宦情闌。"]', '["俗吏闲居少，同人會面难。","偶隨香署客，来訪竹林歡。","暮館花微落，春城雨暫寒。","甕间聊共酌，莫使宦情闌。"]', '诗', 'shi', '', NULL, '陪王郎中尋孔徵君 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78c80a77-9253-478b-bac1-3af5d5b982f6', '送宮人入道', '送宮人入道', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["捨寵求仙畏色衰，辭天素面立天墀。","金丹擬駐千年貌，寶鏡休勻八字眉。","公主與收珠翠後，君王看戴角冠時。","從來宮女皆相妒，說著瑤臺總淚垂。"]', '["捨寵求仙畏色衰，辞天素面立天墀。","金丹擬駐千年貌，寶镜休勻八字眉。","公主與收珠翠後，君王看戴角冠时。","從来宮女皆相妒，说著瑤台總泪垂。"]', '诗', 'shi', '', NULL, '送宮人入道 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b67ddf05-43fb-4859-a1a9-34f95d45aabf', '和晉陵陸丞早春遊望', '和晉陵陸丞早春游望', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["獨有宦遊人，偏驚物候新。","雲霞出海曙，梅柳渡江春。","淑氣催黃鳥，晴光照綠蘋。","忽聞歌苦調，歸思欲霑巾。"]', '["独有宦游人，偏驚物候新。","云霞出海曙，梅柳渡江春。","淑氣催黄鸟，晴光照綠蘋。","忽闻歌苦調，归思欲霑巾。"]', '诗', 'shi', '', NULL, '和晉陵陸丞早春遊望 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abcb9031-9112-4abe-8499-d996a5d38ab0', '九日', '九日', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["一爲吳郡守，不覺菊花開。","始有故園思，且喜衆賓來。"]', '["一爲吳郡守，不覺菊花开。","始有故园思，且喜衆賓来。"]', '诗', 'shi', '', NULL, '九日 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef512eca-b9b4-40d4-9bd1-41396376e80e', '元次山居武昌之樊山新春大雪以詩問之', '元次山居武昌之樊山新春大雪以诗问之', '8d395624-b2a6-4806-a39e-7ff9bc5d5d23', '唐', '["江山十日雪，雪深江霧濃。","起來望樊山，但見羣玉峰。","林鶯却不語，野獸翻有蹤。","山中應大寒，短褐何以完。","皓氣凝書帳，清著釣魚竿。","懷君欲進謁，谿滑渡舟難。"]', '["江山十日雪，雪深江霧濃。","起来望樊山，但见羣玉峰。","林鶯却不語，野獸翻有蹤。","山中應大寒，短褐何以完。","皓氣凝书帳，清著釣鱼竿。","懷君欲進謁，谿滑渡舟难。"]', '诗', 'shi', '', NULL, '元次山居武昌之樊山新春大雪以詩問之 孟彥深 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fa8f206-ddb6-40f9-9d5a-cc5e174284ca', '出塞曲', '出塞曲', '8e0af786-72b1-48e8-b5f1-e5d57a048850', '唐', '["將軍在重圍，音信絕不通。","羽書如流星，飛入甘泉宮。","倚是幷州兒，少年心膽雄。","一朝隨召募，百戰爭王公。","去年桑乾北，今年桑乾東。","死是征人死，功是將軍功。","汗馬牧秋月，疲卒臥霜風。","仍聞左賢王，更將圍雲中。"]', '["將軍在重圍，音信絕不通。","羽书如流星，飞入甘泉宮。","倚是幷州兒，少年心膽雄。","一朝隨召募，百戰爭王公。","去年桑乾北，今年桑乾东。","死是征人死，功是將軍功。","汗马牧秋月，疲卒臥霜风。","仍闻左賢王，更將圍云中。"]', '诗', 'shi', '', NULL, '出塞曲 劉灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f8dd04e-98d0-44c6-ab36-03677e8e16b3', '雲南曲', '云南曲', '8e0af786-72b1-48e8-b5f1-e5d57a048850', '唐', '["百蠻亂南方，羣盜如蝟起。","騷然疲中原，征戰從此始。","白門太和城，來往一萬里。","去者無全生，十人九人死。","岱馬臥陽山，燕兵哭瀘水。","妻行求死夫，父行求死子。","蒼天滿愁雲，白骨積空壘。","哀哀雲南行，十萬同已矣。"]', '["百蠻亂南方，羣盜如蝟起。","騷然疲中原，征戰從此始。","白门太和城，来往一万里。","去者無全生，十人九人死。","岱马臥陽山，燕兵哭瀘水。","妻行求死夫，父行求死子。","蒼天满愁云，白骨積空壘。","哀哀云南行，十万同已矣。"]', '诗', 'shi', '', NULL, '雲南曲 劉灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3813dedc-c18a-44c8-84e4-c51b607610ba', '李陵別蘇武', '李陵別蘇武', '8e0af786-72b1-48e8-b5f1-e5d57a048850', '唐', '["漢武愛邊功，李陵提步卒。","轉戰單于庭，身隨漢軍沒。","李陵不愛死，心存歸漢闕。","誓欲還國恩，不爲匈奴屈。","身辱家已無，長居虎狼窟。","胡天無春風，虜地多積雪。","窮陰愁殺人，況與蘇武別。","發聲天地哀，執手肺腸絕。","白日爲我愁，陰雲爲我結。","生爲漢宮臣，死爲胡地骨。","萬里長相思，終身望南月。"]', '["漢武愛邊功，李陵提步卒。","轉戰單于庭，身隨漢軍沒。","李陵不愛死，心存归漢闕。","誓欲還国恩，不爲匈奴屈。","身辱家已無，长居虎狼窟。","胡天無春风，虜地多積雪。","窮陰愁殺人，況與蘇武別。","發声天地哀，執手肺腸絕。","白日爲我愁，陰云爲我結。","生爲漢宮臣，死爲胡地骨。","万里长相思，終身望南月。"]', '诗', 'shi', '', NULL, '李陵別蘇武 劉灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0087ac2-4096-4fb9-8342-3776b9677768', '虹縣嚴孝子墓', '虹縣嚴孝子墓', '8e0af786-72b1-48e8-b5f1-e5d57a048850', '唐', '["至性教不及，因心天所資。","禮聞三年喪，爾獨終身期。","下由骨肉恩，上報父母慈。","禮聞哭有卒，汝獨哀無時。","前有松柏林，荆蓁結朦朧。","墓門白日閉，泣血黃泉中。","草服蔽枯骨，垢容戴飛蓬。","舉聲哭蒼天，萬木皆悲風。"]', '["至性教不及，因心天所資。","禮闻三年喪，爾独終身期。","下由骨肉恩，上報父母慈。","禮闻哭有卒，汝独哀無时。","前有松柏林，荆蓁結朦朧。","墓门白日閉，泣血黄泉中。","草服蔽枯骨，垢容戴飞蓬。","舉声哭蒼天，万木皆悲风。"]', '诗', 'shi', '', NULL, '虹縣嚴孝子墓 劉灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e56279e-18ff-4da4-926a-bbb2ab10abb1', '對雨愁悶寄錢大郎中', '对雨愁悶寄錢大郎中', '8e0af786-72b1-48e8-b5f1-e5d57a048850', '唐', '["積雨細紛紛，飢寒命不分。","攬衣愁見肘，窺鏡覓從文。","九陌成泥海，千山盡濕雲。","龍鍾驅欵段，到處倍思君。"]', '["積雨細紛紛，飢寒命不分。","攬衣愁见肘，窺镜覓從文。","九陌成泥海，千山尽濕云。","龙鍾驱欵段，到处倍思君。"]', '诗', 'shi', '', NULL, '對雨愁悶寄錢大郎中 劉灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('696256d1-68da-4821-8a42-372916db0244', '即席賦露中菊', '即席賦露中菊', '8e0af786-72b1-48e8-b5f1-e5d57a048850', '唐', '["衆芳春競發，寒菊露偏滋。","受氣何曾異，開花獨自遲。","晚成猶有分，欲採未過時。","勿棄東籬下，看隨秋草衰。"]', '["衆芳春競發，寒菊露偏滋。","受氣何曾異，开花独自遲。","晚成猶有分，欲採未過时。","勿棄东籬下，看隨秋草衰。"]', '诗', 'shi', '', NULL, '即席賦露中菊 劉灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f699d2a4-bc4b-4f9d-8b62-5abab4c283a3', '遇旅鶴', '遇旅鹤', 'd2b6d847-7bb1-45a5-96c0-54e46e36ed4a', '唐', '["靈鶴產絕境，昂昂無與儔。","羣飛滄海曙，一叫雲山秋。","野性方自得，人寰何所求。","時因戲祥風，偶爾來中州。","中州帝王宅，園沼深且幽。","希君惠稻粱，欲幷離丹丘。","不然奮飛去，將適汗漫游。","肯作池上鶩，年年空沈浮。"]', '["靈鹤產絕境，昂昂無與儔。","羣飞滄海曙，一叫云山秋。","野性方自得，人寰何所求。","时因戲祥风，偶爾来中州。","中州帝王宅，园沼深且幽。","希君惠稻粱，欲幷離丹丘。","不然奮飞去，將適汗漫游。","肯作池上鶩，年年空沈浮。"]', '诗', 'shi', '', NULL, '遇旅鶴 孫昌胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd1d6bdc-40d7-4fc8-ac2d-814f0eb5da43', '清明', '清明', 'd2b6d847-7bb1-45a5-96c0-54e46e36ed4a', '唐', '["清明暮春裏，悵望北山陲。","燧火開新焰，桐花發故枝。","沈冥慙歲物，歡宴阻朋知。","不及林間鳥，遷喬並羽儀。"]', '["清明暮春裏，悵望北山陲。","燧火开新焰，桐花發故枝。","沈冥慙歲物，歡宴阻朋知。","不及林间鸟，遷喬並羽儀。"]', '诗', 'shi', '', NULL, '清明 孫昌胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b82553b-521d-4ced-a2da-2cf6b5d61764', '和司空曙劉眘虛九日送人', '和司空曙劉眘虛九日送人', 'd2b6d847-7bb1-45a5-96c0-54e46e36ed4a', '唐', '["京邑歎離羣，江樓喜遇君。","開筵當九日，汎菊外浮雲。","朗詠山川霽，酣歌物色新。","君看酒中意，未肯喪斯文。"]', '["京邑歎離羣，江楼喜遇君。","开筵當九日，汎菊外浮云。","朗詠山川霽，酣歌物色新。","君看酒中意，未肯喪斯文。"]', '诗', 'shi', '', NULL, '和司空曙劉眘虛九日送人 孫昌胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6725b27b-58a5-48bf-bc23-0d93108ba140', '越裳獻白翟', '越裳獻白翟', 'd2b6d847-7bb1-45a5-96c0-54e46e36ed4a', '唐', '["聖哲符休運，伊臯列上台。","覃恩丹徼遠，入貢素翬來。","北闕欣初見，南枝顧未迴。","斂容殘雪淨，矯翼片雲開。","馴擾將無懼，翻飛幸莫猜。","甘從上苑裏，飲啄自裴回。"]', '["聖哲符休運，伊臯列上台。","覃恩丹徼远，入貢素翬来。","北闕欣初见，南枝顧未迴。","斂容殘雪淨，矯翼片云开。","馴擾將無懼，翻飞幸莫猜。","甘從上苑裏，饮啄自裴回。"]', '诗', 'shi', '', NULL, '越裳獻白翟 孫昌胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31e70583-ad36-4d3b-80df-84383a27f226', '綿州越王樓即事', '綿州越王楼即事', '0e9710df-0310-4650-b440-23f911189c45', '唐', '["三蜀澄清郡政閑，登樓攜酌日躋攀。","頓覺胷懷無俗事，迴看掌握是人寰。","灘聲曲折涪州水，雲影低銜富樂山。","行雁南飛似鄉信，忽然西笑向秦關。"]', '["三蜀澄清郡政闲，登楼携酌日躋攀。","頓覺胷懷無俗事，迴看掌握是人寰。","灘声曲折涪州水，云影低銜富乐山。","行雁南飞似乡信，忽然西笑向秦关。"]', '诗', 'shi', '', NULL, '綿州越王樓即事 喬琳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9119857e-a741-49af-a746-33429a2815fd', '牡丹', '牡丹', '3821012f-bb18-458e-b9f2-144c435351be', '唐', '["近來無奈牡丹何，數十千錢買一顆。","今朝始得分明見，也共戎葵不校多。"]', '["近来無奈牡丹何，數十千錢買一顆。","今朝始得分明见，也共戎葵不校多。"]', '诗', 'shi', '', NULL, '牡丹 柳渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad33b0a5-c7b0-4377-ab30-6c1a27e5d5d8', '讀後漢逸人傳二首 一', '读後漢逸人傳二首 一', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["子陵沒已久，讀史思其賢。","誰謂潁陽人，千秋如比肩。","嘗聞漢皇帝，曾是曠周旋。","名位苟無心，對君猶可眠。","東過富春渚，樂此佳山川。","夜臥松下月，朝看江上煙。","釣時如有待，釣罷應忘筌。","生事在林壑，悠悠經暮年。","于今七里瀨，遺迹尚依然。","高臺竟寂寞，流水空潺湲。"]', '["子陵沒已久，读史思其賢。","誰謂潁陽人，千秋如比肩。","嘗闻漢皇帝，曾是曠周旋。","名位苟無心，对君猶可眠。","东過富春渚，乐此佳山川。","夜臥松下月，朝看江上煙。","釣时如有待，釣罷應忘筌。","生事在林壑，悠悠經暮年。","于今七里瀨，遺迹尚依然。","高台竟寂寞，流水空潺湲。"]', '诗', 'shi', '', NULL, '讀後漢逸人傳二首 一 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd2e3b6-ed49-426d-9129-ce8e1ed04a83', '讀後漢逸人傳二首 二', '读後漢逸人傳二首 二', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["龐公南郡人，家在襄陽里。","何處偏來往，襄陽東陂是。","誓將業田種，終得保妻子。","何言二千石，乃欲勸吾仕。","鸛鵲巢茂林，黿鼉穴深水。","萬物從所欲，吾心亦如此。","不見鹿門山，朝朝白雲起。","采藥復采樵，優游終暮齒。"]', '["龐公南郡人，家在襄陽里。","何处偏来往，襄陽东陂是。","誓將業田種，終得保妻子。","何言二千石，乃欲勸吾仕。","鸛鵲巢茂林，黿鼉穴深水。","万物從所欲，吾心亦如此。","不见鹿门山，朝朝白云起。","采藥复采樵，優游終暮齒。"]', '诗', 'shi', '', NULL, '讀後漢逸人傳二首 二 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdd8924d-da5d-4665-8a13-91b52379f3d8', '同孫構免官後登薊樓', '同孫構免官後登薊楼', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["昔在五陵時，年少心亦壯。","嘗矜有奇骨，必是封侯相。","東走到營州，投身似邊將。","一朝去鄉國，十載履亭障。","部曲皆武夫，功成不相讓。","猶希虜塵動，更取林胡帳。","去年大將軍，忽負樂生謗。","北別傷士卒，南遷死炎瘴。","濩落悲無成，行登薊丘上。","長安三千里，日夕西南望。","寒沙榆塞沒，秋水灤河漲。","策馬從此辭，雲山保閑放。"]', '["昔在五陵时，年少心亦壯。","嘗矜有奇骨，必是封侯相。","东走到營州，投身似邊將。","一朝去乡国，十載履亭障。","部曲皆武夫，功成不相讓。","猶希虜塵动，更取林胡帳。","去年大將軍，忽負乐生謗。","北別傷士卒，南遷死炎瘴。","濩落悲無成，行登薊丘上。","长安三千里，日夕西南望。","寒沙榆塞沒，秋水灤河漲。","策马從此辞，云山保闲放。"]', '诗', 'shi', '', NULL, '同孫構免官後登薊樓 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50e3f3b1-bdf4-4af6-82b3-1b31b2c6a2e0', '代北州老翁荅', '代北州老翁荅', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["負薪老翁往北州，北望鄉關生客愁。","自言老翁有三子，兩人已向黃沙死。","如今小兒新長成，明年聞道又徵兵。","定知此別必零落，不及相隨同死生。","盡將田宅借鄰伍，且復伶俜去鄉士。","在生本求多子孫，及有誰知更辛苦。","近傳天子尊武臣，強兵直欲靜胡塵。","安邊自合有長策，何必流離中國人。"]', '["負薪老翁往北州，北望乡关生客愁。","自言老翁有三子，兩人已向黄沙死。","如今小兒新长成，明年闻道又徵兵。","定知此別必零落，不及相隨同死生。","尽將田宅借鄰伍，且复伶俜去乡士。","在生本求多子孫，及有誰知更辛苦。","近傳天子尊武臣，強兵直欲静胡塵。","安邊自合有长策，何必流離中国人。"]', '诗', 'shi', '', NULL, '代北州老翁荅 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('474cca5c-e923-468b-92bd-8210ab38457e', '湖上對酒行', '湖上对酒行', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["夜坐不厭湖上月，晝行不厭湖上山。","眼前一尊又長滿，心中萬事如等閑。","主人有黍百餘石，濁醪數斗應不惜。","即今相對不盡歡，別後相思復何益。","茱萸灣頭歸路賒，願君且宿黃公家。","風光若此人不醉，參差辜負東園花。"]', '["夜坐不厭湖上月，晝行不厭湖上山。","眼前一尊又长满，心中万事如等闲。","主人有黍百餘石，濁醪數斗應不惜。","即今相对不尽歡，別後相思复何益。","茱萸灣头归路賒，願君且宿黄公家。","风光若此人不醉，參差辜負东园花。"]', '诗', 'shi', '', NULL, '湖上對酒行 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e45d98-0ebd-4cdd-b326-f1326548d8ef', '贈喬琳', '贈喬琳', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["去年上策不見收，今年寄食仍淹留。","羨君有酒能便醉，羨君無錢能不憂。","如今五侯不愛客，羨君不問五侯宅。","如今七貴方自尊，羨君不過七貴門。","丈夫會應有知己，世上悠悠何足論。"]', '["去年上策不见收，今年寄食仍淹留。","羨君有酒能便醉，羨君無錢能不憂。","如今五侯不愛客，羨君不问五侯宅。","如今七貴方自尊，羨君不過七貴门。","丈夫會應有知己，世上悠悠何足論。"]', '诗', 'shi', '', NULL, '贈喬琳 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c155807-0def-4fd4-9df9-fc34d0bb012f', '邵陵作', '邵陵作', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["嘗聞虞帝苦憂人，祗爲蒼生不爲身。","已道一朝辭北闕，何須五月更南巡。","昔時文武皆銷鑠，今日精靈常寂寞。","斑竹年來笋自生，白蘋春盡花空落。","遙望零陵見舊丘，蒼梧雲起至今愁。","惟餘帝子千行淚，添作瀟湘萬里流。"]', '["嘗闻虞帝苦憂人，祗爲蒼生不爲身。","已道一朝辞北闕，何須五月更南巡。","昔时文武皆銷鑠，今日精靈常寂寞。","斑竹年来笋自生，白蘋春尽花空落。","遙望零陵见旧丘，蒼梧云起至今愁。","惟餘帝子千行泪，添作瀟湘万里流。"]', '诗', 'shi', '', NULL, '邵陵作 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f243b3bd-afa2-47a6-be17-8b8caba05c69', '寄李侍御', '寄李侍御', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["柱下聞周史，書中慰越吟。","近看三歲字，遙見百年心。","價以吹噓長，恩從顧盼深。"]', '["柱下闻周史，书中慰越吟。","近看三歲字，遙见百年心。","價以吹噓长，恩從顧盼深。"]', '诗', 'shi', '', NULL, '寄李侍御 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb3f5948-c01e-43b7-aa99-048cdcbc451e', '寄崔灃州', '寄崔灃州', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["共襆臺郎被，俱褰郡守帷。","罰金殊往日，鳴玉幸同時。","五馬來何晚，雙魚贈已遲。","江頭望鄉月，無夜不相思。"]', '["共襆台郎被，俱褰郡守帷。","罰金殊往日，鳴玉幸同时。","五马来何晚，雙鱼贈已遲。","江头望乡月，無夜不相思。"]', '诗', 'shi', '', NULL, '寄崔灃州 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09242aca-4cbb-40d2-bb3f-8a189a4495db', '送裴侍御歸上都', '送裴侍御归上都', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["楚地勞行役，秦城罷鼓鼙。","舟移洞庭岸，路出武陵谿。","江月隨人影，山花趁馬蹄。","離魂將別夢，先已到關西。"]', '["楚地勞行役，秦城罷鼓鼙。","舟移洞庭岸，路出武陵谿。","江月隨人影，山花趁马蹄。","離魂將別梦，先已到关西。"]', '诗', 'shi', '', NULL, '送裴侍御歸上都 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2b498aa-228d-444e-b9e6-b663796ff42e', '送青龍一公', '送青龙一公', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["事佛輕金印，勤王度玉關。","不知從樹下，還肯到人間。","楚水青蓮淨，吳門白日閑。","聖朝須助理，絕莫愛東山。"]', '["事佛轻金印，勤王度玉关。","不知從樹下，還肯到人间。","楚水青蓮淨，吳门白日闲。","聖朝須助理，絕莫愛东山。"]', '诗', 'shi', '', NULL, '送青龍一公 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a913e4-f3e8-4110-83b1-5706048ec2c6', '送韋侍御赴上都', '送韋侍御赴上都', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["天朝辟書下，風憲取才難。","更謁麒麟殿，重簪獬豸冠。","月明湘水夜，霜重桂林寒。","別後頭堪白，時時鏡裏看。"]', '["天朝辟书下，风憲取才难。","更謁麒麟殿，重簪獬豸冠。","月明湘水夜，霜重桂林寒。","別後头堪白，时时镜裏看。"]', '诗', 'shi', '', NULL, '送韋侍御赴上都 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2e40dec-928a-4504-82a2-e611b052bf76', '餞田尚書還兗州', '餞田尚书還兗州', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["忠義三朝許，威名四海聞。","更乘歸魯詔，猶憶破胡勳。","別路逢霜雨，行營對雪雲。","明朝郭門外，長揖大將軍。"]', '["忠義三朝許，威名四海闻。","更乘归魯詔，猶憶破胡勳。","別路逢霜雨，行營对雪云。","明朝郭门外，长揖大將軍。"]', '诗', 'shi', '', NULL, '餞田尚書還兗州 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('726e30df-7002-4b27-8c2d-054dfee858a5', '送杜侍御赴上都', '送杜侍御赴上都', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["避馬臺中貴，登車嶺外遙。","還因貢賦禮，來謁大明朝。","地入商山路，鄉連渭水橋。","承恩返南越，尊酒重相邀。"]', '["避马台中貴，登车嶺外遙。","還因貢賦禮，来謁大明朝。","地入商山路，乡連渭水橋。","承恩返南越，尊酒重相邀。"]', '诗', 'shi', '', NULL, '送杜侍御赴上都 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad833649-16f9-416a-980f-22f31f373775', '道林寺送莫侍御', '道林寺送莫侍御', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["何處堪留客，香林隔翠微。","薜蘿通驛騎，山竹挂朝衣。","霜引臺烏集，風驚塔鴈飛。","飲茶勝飲酒，聊以送將歸。"]', '["何处堪留客，香林隔翠微。","薜蘿通驛騎，山竹挂朝衣。","霜引台烏集，风驚塔鴈飞。","饮茶勝饮酒，聊以送將归。"]', '诗', 'shi', '', NULL, '道林寺送莫侍御 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33719a7f-eaec-48ab-8fd3-99f035c54968', '別睢陽故人', '別睢陽故人', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["少小客遊梁，依然似故鄉。","城池經戰陣，人物恨存亡。","夏雨桑條綠，秋風麥穗黃。","有書無寄處，相送一霑裳。"]', '["少小客游梁，依然似故乡。","城池經戰陣，人物恨存亡。","夏雨桑條綠，秋风麦穗黄。","有书無寄处，相送一霑裳。"]', '诗', 'shi', '', NULL, '別睢陽故人 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7060551-6241-4ac7-8e7b-affb30c61e88', '郡南亭子宴', '郡南亭子宴', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["亭子春城外，朱門向綠林。","柳枝經雨重，松色帶烟深。","漉酒迎山客，穿池集水禽。","白雲常在眼，聊足慰人心。"]', '["亭子春城外，朱门向綠林。","柳枝經雨重，松色带烟深。","漉酒迎山客，穿池集水禽。","白云常在眼，聊足慰人心。"]', '诗', 'shi', '', NULL, '郡南亭子宴 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58510152-6736-42b3-a285-890a9b46a75f', '早春陪崔中丞浣花溪宴得暄字', '早春陪崔中丞浣花溪宴得暄字', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["旌節臨溪口，寒郊斗覺暄。","紅亭移酒席，畫鷁逗江村。","雲帶歌聲颺，風飄舞袖翻。","花間催秉燭，川上欲黃昏。"]', '["旌節臨溪口，寒郊斗覺暄。","紅亭移酒席，畫鷁逗江村。","云带歌声颺，风飄舞袖翻。","花间催秉燭，川上欲黄昏。"]', '诗', 'shi', '', NULL, '早春陪崔中丞浣花溪宴得暄字 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49273c42-b969-4f81-915d-9d1e8422f3d9', '讌鄭伯璵宅', '讌鄭伯璵宅', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["正月風光好，逢君上客稀。","曉風催鳥囀，春雪帶花飛。","堂上吹金管，庭前試舞衣。","俸錢供酒債，行子未須歸。"]', '["正月风光好，逢君上客稀。","晓风催鸟囀，春雪带花飞。","堂上吹金管，庭前試舞衣。","俸錢供酒債，行子未須归。"]', '诗', 'shi', '', NULL, '讌鄭伯璵宅 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1cd5d9a-6b52-4f98-a761-f754635e2ab1', '夜同宴用人字', '夜同宴用人字', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["北斗回新歲，東園值早春。","竹風能醒酒，花月解留人。","邑宰陶元亮，山家鄭子真。","平生頗同道，相見日相親。"]', '["北斗回新歲，东园值早春。","竹风能醒酒，花月解留人。","邑宰陶元亮，山家鄭子真。","平生頗同道，相见日相親。"]', '诗', 'shi', '', NULL, '夜同宴用人字 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa083f14-5488-41b7-af8b-9855f2571276', '過從弟制疑官舍竹齋', '過從弟制疑官舍竹斋', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["羨爾方爲吏，衡門獨[晏]如。","野猨偷紙筆，山鳥污圖書。","竹裏藏公事，花間隱使車。","不妨垂釣坐，時膾小江魚。"]', '["羨爾方爲吏，衡门独[晏]如。","野猨偷紙笔，山鸟污圖书。","竹裏藏公事，花间隐使车。","不妨垂釣坐，时膾小江鱼。"]', '诗', 'shi', '', NULL, '過從弟制疑官舍竹齋 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f67c0a6a-f81d-4458-a6b7-b14df3f06146', '揚州雨中張十七宅觀妓', '揚州雨中張十七宅观妓', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["夜色帶寒煙，燈花拂更然。","殘妝添石黛，豔舞落金鈿。","掩笑須欹扇，迎歌乍動弦。","不知巫峽雨，何事海西邊。"]', '["夜色带寒煙，灯花拂更然。","殘妝添石黛，豔舞落金鈿。","掩笑須欹扇，迎歌乍动弦。","不知巫峽雨，何事海西邊。"]', '诗', 'shi', '', NULL, '揚州雨中張十七宅觀妓 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('887d8ba9-bf18-4923-86cb-b175ef7530e4', '登金陵臨江驛樓', '登金陵臨江驛楼', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["古戍依重險，高樓見五梁。","山根盤驛道，河水浸城牆。","庭樹巢鸚鵡，園花隱麝香。","忽然江浦上，憶作捕魚郎。"]', '["古戍依重險，高楼见五梁。","山根盤驛道，河水浸城牆。","庭樹巢鸚鵡，园花隐麝香。","忽然江浦上，憶作捕鱼郎。"]', '诗', 'shi', '', NULL, '登金陵臨江驛樓 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec6c90eb-0349-4206-ad18-52204a036b60', '同王徵君湘中有懷', '同王徵君湘中有懷', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["八月洞庭秋，瀟湘水北流。","還家萬里夢，爲客五更愁。","不用開書帙，偏宜上酒樓。","故人京洛滿，何日復同遊。"]', '["八月洞庭秋，瀟湘水北流。","還家万里梦，爲客五更愁。","不用开书帙，偏宜上酒楼。","故人京洛满，何日复同游。"]', '诗', 'shi', '', NULL, '同王徵君湘中有懷 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('631932b3-98a4-4939-bea2-f73f808f57f0', '官舍早梅', '官舍早梅', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["堦下雙梅樹，春來畫不成。","晚時花未落，陰處葉難生。","摘子防人到，攀枝畏鳥驚。","風光先占得，桃李莫相輕。"]', '["堦下雙梅樹，春来畫不成。","晚时花未落，陰处葉难生。","摘子防人到，攀枝畏鸟驚。","风光先占得，桃李莫相轻。"]', '诗', 'shi', '', NULL, '官舍早梅 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12cab6c3-4e6c-49b6-831d-fff96cf48e36', '玉清公主挽歌', '玉清公主挽歌', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["學鳳年猶小，乘龍日尚賒。","初封千戶邑，忽駕五雲車。","地接金人岸，山通玉女家。","秋風何太早，吹落禁園花。"]', '["学鳳年猶小，乘龙日尚賒。","初封千戶邑，忽駕五云车。","地接金人岸，山通玉女家。","秋风何太早，吹落禁园花。"]', '诗', 'shi', '', NULL, '玉清公主挽歌 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('753e44dc-4ea6-416e-b967-5e1ab7a9acf9', '別韋郎中', '別韋郎中', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["星軺計日赴岷峨，雲樹連天阻笑歌。","南入洞庭隨鴈去，西過巫峽聽猨多。","崢嶸洲上飛黃蝶，灩澦堆邊起白波。","不醉郎中桑落酒，教人無奈別離何。"]', '["星軺計日赴岷峨，云樹連天阻笑歌。","南入洞庭隨鴈去，西過巫峽听猨多。","崢嶸洲上飞黄蝶，灩澦堆邊起白波。","不醉郎中桑落酒，教人無奈別離何。"]', '诗', 'shi', '', NULL, '別韋郎中 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4233265-dd8f-414c-b0d7-0a691d9924dd', '送皇甫齡宰交河', '送皇甫齡宰交河', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["將軍帳下來從客，小邑彈琴不易逢。","樓上胡笳傳別怨，尊中臘酒爲誰濃。","行人醉出雙門道，少婦愁看七里烽。","今日相如輕武騎，多應朝暮客臨卭。"]', '["將軍帳下来從客，小邑彈琴不易逢。","楼上胡笳傳別怨，尊中臘酒爲誰濃。","行人醉出雙门道，少婦愁看七里烽。","今日相如轻武騎，多應朝暮客臨卭。"]', '诗', 'shi', '', NULL, '送皇甫齡宰交河 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da49282-f103-418e-bfd6-d9f79aaabcb1', '杜侍御送貢物戲贈', '杜侍御送貢物戲贈', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["銅柱朱崖道路難，伏波橫海舊登壇。","越人自貢珊瑚樹，漢使何勞獬豸冠。","疲馬山中愁日晚，孤舟江上畏春寒。","由來此貨稱難得，多恐君王不忍看。"]', '["銅柱朱崖道路难，伏波橫海旧登壇。","越人自貢珊瑚樹，漢使何勞獬豸冠。","疲马山中愁日晚，孤舟江上畏春寒。","由来此貨稱难得，多恐君王不忍看。"]', '诗', 'shi', '', NULL, '杜侍御送貢物戲贈 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c87dc6f-4f7f-4205-badb-8d2eca6d6c08', '春園家宴', '春园家宴', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["南園春色正相宜，大婦同行少婦隨。","竹裏登樓人不見，花間覓路鳥先知。","櫻桃解結垂簷子，楊柳能低入戶枝。","山簡醉來歌一曲，參差笑殺郢中兒。"]', '["南园春色正相宜，大婦同行少婦隨。","竹裏登楼人不见，花间覓路鸟先知。","櫻桃解結垂簷子，楊柳能低入戶枝。","山簡醉来歌一曲，參差笑殺郢中兒。"]', '诗', 'shi', '', NULL, '春園家宴 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27d32896-4fcb-4800-b7ed-46df2d8dfe9d', '西亭子言懷', '西亭子言懷', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["數叢芳草在堂陰，幾處閑花映竹林。","攀樹玄猨呼郡吏，傍谿白鳥應家禽。","青山看景知高下，流水聞聲覺淺深。","官屬不令拘禮數，時時緩步一相尋。"]', '["數叢芳草在堂陰，幾处闲花映竹林。","攀樹玄猨呼郡吏，傍谿白鸟應家禽。","青山看景知高下，流水闻声覺淺深。","官屬不令拘禮數，时时緩步一相尋。"]', '诗', 'shi', '', NULL, '西亭子言懷 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f8a119a-fd44-47e9-8803-a04f0f1c4e77', '辰陽即事', '辰陽即事', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["青楓落葉正堪悲，黃菊殘花欲待誰。","水近偏逢寒氣早，山深常見日光遲。","愁中卜命看周易，病裏招魂讀楚詞。","自恨不如湘浦鴈，春來即是北歸時。"]', '["青楓落葉正堪悲，黄菊殘花欲待誰。","水近偏逢寒氣早，山深常见日光遲。","愁中卜命看周易，病裏招魂读楚词。","自恨不如湘浦鴈，春来即是北归时。"]', '诗', 'shi', '', NULL, '辰陽即事 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19433bd7-61c2-4618-892a-ddd7b71c082f', '送僧', '送僧', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["童子學修道，誦經求出家。","手持貝多葉，心念優曇花。","得度北州近，隨緣東路賒。","一身求清淨，百毳納袈裟。","鍾嶺更飛錫，爐峰期結跏。","深心大海水，廣願恆河沙。","此去不堪別，彼行安可涯。","殷勤結香火，來世上牛車。"]', '["童子学修道，誦經求出家。","手持貝多葉，心念優曇花。","得度北州近，隨緣东路賒。","一身求清淨，百毳納袈裟。","鍾嶺更飞錫，爐峰期結跏。","深心大海水，廣願恆河沙。","此去不堪別，彼行安可涯。","殷勤結香火，来世上牛车。"]', '诗', 'shi', '', NULL, '送僧 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a169d7cc-0e41-4b7d-9c77-6ffc3bafc48a', '同諸公遊雲公禪寺', '同諸公游云公禪寺', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["共許尋雞足，誰能惜馬蹄。","長空淨雲雨，斜日半虹霓。","簷下千峰轉，窗前萬木低。","看花尋徑遠，聽鳥入林迷。","地與喧聞隔，人將物我齊。","不知樵客意，何事武陵谿。"]', '["共許尋雞足，誰能惜马蹄。","长空淨云雨，斜日半虹霓。","簷下千峰轉，窗前万木低。","看花尋徑远，听鸟入林迷。","地與喧闻隔，人將物我齊。","不知樵客意，何事武陵谿。"]', '诗', 'shi', '', NULL, '同諸公遊雲公禪寺 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5ff1ab1-139e-47c0-8239-aeaf72f76813', '哭護國上人', '哭護国上人', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["昔喜三身淨，今悲萬劫長。","不應歸北斗，應是向西方。","舍利衆生得，袈裟弟子將。","鼠行殘藥椀，蟲網舊繩牀。","別起千花塔，空留一草堂。","支公何處在，神理竟茫茫。"]', '["昔喜三身淨，今悲万劫长。","不應归北斗，應是向西方。","舍利衆生得，袈裟弟子將。","鼠行殘藥椀，蟲網旧繩牀。","別起千花塔，空留一草堂。","支公何处在，神理竟茫茫。"]', '诗', 'shi', '', NULL, '哭護國上人 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1956bb6-2c19-43b2-8bb5-114aa240a2ce', '送盧舉使河源', '送盧舉使河源', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["故人行役向邊州，匹馬今朝不少留。","長路關山何日盡，滿堂絲竹爲君愁。"]', '["故人行役向邊州，匹马今朝不少留。","长路关山何日尽，满堂絲竹爲君愁。"]', '诗', 'shi', '', NULL, '送盧舉使河源 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30a060f1-a54f-4c16-b417-c853d5f58a61', '題長安壁主人', '題长安壁主人', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["世人結交須黃金，黃金不多交不深。","縱令然諾暫相許，終是悠悠行路心。"]', '["世人結交須黄金，黄金不多交不深。","縱令然諾暫相許，終是悠悠行路心。"]', '诗', 'shi', '', NULL, '題長安壁主人 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('169b4f35-be20-4383-a122-6a013526aca2', '長安失火後戲題蓮花寺', '长安失火後戲題蓮花寺', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["金園寶剎半長沙，燒劫旁延一萬家。","樓殿縱隨煙焰去，火中何處出蓮花。"]', '["金园寶剎半长沙，燒劫旁延一万家。","楼殿縱隨煙焰去，火中何处出蓮花。"]', '诗', 'shi', '', NULL, '長安失火後戲題蓮花寺 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26b9926a-007c-446d-b544-89d3be0c721e', '早梅', '早梅', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["一樹寒梅白玉條，逈臨林村傍谿橋。","不知近水花先發，疑是經春雪未銷。"]', '["一樹寒梅白玉條，逈臨林村傍谿橋。","不知近水花先發，疑是經春雪未銷。"]', '诗', 'shi', '', NULL, '早梅 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c3bf7b9-afa8-47dd-afe4-7ff4cba4a1c4', '贈趙使君美人', '贈趙使君美人', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["紅粉青蛾映楚雲，桃花馬上石榴裙。","羅敷獨向東方去，漫學他家作使君。"]', '["紅粉青蛾映楚云，桃花马上石榴裙。","羅敷独向东方去，漫学他家作使君。"]', '诗', 'shi', '', NULL, '贈趙使君美人 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e6cf7b0-a4ab-47aa-9374-fb7e8545cd16', '句', '句', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["[稽]山賀老麤知名，吳郡張顛曾不易。","奔蛇走虺勢入坐，驟雨旋風聲滿堂。"]', '["[稽]山賀老麤知名，吳郡張顛曾不易。","奔蛇走虺勢入坐，驟雨旋风声满堂。"]', '诗', 'shi', '', NULL, '句 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80e5e243-1539-4787-af87-ea299c03f4ae', '北庭西郊候封大夫受降回軍獻上', '北庭西郊候封大夫受降回軍獻上', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["胡地苜蓿美，輪臺征馬肥。","大夫討匈奴，前月西出師。","甲兵未得戰，降虜來如歸。","橐駞何連連，穹帳亦纍纍。","陰山烽火滅，劒水羽書稀。","却笑霍嫖姚，區區徒爾爲。","西郊候中軍，平沙懸落暉。","驛馬從西來，雙節夾路馳。","喜鵲捧金印，蛟龍盤畫旗。","如公未四十，富貴能及時。","直上排青雲，傍看疾若飛。","前年斬樓蘭，去歲平月支。","天子日殊寵，朝廷方見推。","何幸一書生，忽蒙國士知。","側身佐戎幕，斂袵事邊陲。","自逐定遠侯，亦著短後衣。","近來能走馬，不弱幷州兒。"]', '["胡地苜蓿美，輪台征马肥。","大夫討匈奴，前月西出師。","甲兵未得戰，降虜来如归。","橐駞何連連，穹帳亦纍纍。","陰山烽火滅，劒水羽书稀。","却笑霍嫖姚，區區徒爾爲。","西郊候中軍，平沙懸落暉。","驛马從西来，雙節夾路驰。","喜鵲捧金印，蛟龙盤畫旗。","如公未四十，富貴能及时。","直上排青云，傍看疾若飞。","前年斬楼蘭，去歲平月支。","天子日殊寵，朝廷方见推。","何幸一书生，忽蒙国士知。","側身佐戎幕，斂袵事邊陲。","自逐定远侯，亦著短後衣。","近来能走马，不弱幷州兒。"]', '诗', 'shi', '', NULL, '北庭西郊候封大夫受降回軍獻上 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1be7622-2154-4000-8e72-fddd66ccd05a', '初至西虢官舍南池呈左右省及南宮諸故人', '初至西虢官舍南池呈左右省及南宮諸故人', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["黜官自西掖，待罪臨下陽。","空積犬馬戀，豈思鵷鷺行。","素多江湖意，偶佐山水鄉。","滿院池月靜，捲簾溪雨涼。","軒窓竹翠濕，案牘荷花香。","白鳥上衣桁，青苔生筆牀。","數公不可見，一別盡相忘。","敢恨青瑣客，無情華省郎。","早年迷進退，晚節悟行藏。","他日能相訪，嵩南舊草堂。"]', '["黜官自西掖，待罪臨下陽。","空積犬马戀，豈思鵷鷺行。","素多江湖意，偶佐山水乡。","满院池月静，捲簾溪雨涼。","軒窓竹翠濕，案牘荷花香。","白鸟上衣桁，青苔生笔牀。","數公不可见，一別尽相忘。","敢恨青瑣客，無情华省郎。","早年迷進退，晚節悟行藏。","他日能相訪，嵩南旧草堂。"]', '诗', 'shi', '', NULL, '初至西虢官舍南池呈左右省及南宮諸故人 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f30f719-46f0-4afa-a81a-b46e457655f8', '過梁州奉贈張尚書大夫公', '過梁州奉贈張尚书大夫公', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["漢中二良將，今昔各一時。","韓信此登壇，尚書復來斯。","手把銅虎符，身總丈人師。","錯落北斗星，照耀黑水湄。","英雄若神授，大材濟時危。","頃歲遇雷雲，精神感靈祇。","勳業振青史，恩德繼鴻私。","羌虜昔未平，華陽積僵屍。","人煙絕墟落，鬼火依城池。","巴漢空水流，襃斜惟鳥飛。","自公布德政，此地生光輝。","百堵創里閭，千家恤惸嫠。","層城重鼓角，甲士如熊羆。","坐嘯風自調，行春雨仍隨。","芃芃麥苗長，藹藹桑葉肥。","浮客相與來，羣盜不敢窺。","何幸承嘉惠，小年即相知。","富貴情易疎，相逢心不移。","置酒宴高館，嬌歌雜青絲。","錦席繡拂廬，玉盤金屈巵。","春景透高戟，江雲篲長麾。","櫪馬嘶柳陰，美人映花枝。","門傳大夫印，世擁上將旗。","承家令名揚，許國苦節施。","戎幕寧久駐，台階不應遲。","別有彈冠士，希君無見遺。"]', '["漢中二良將，今昔各一时。","韓信此登壇，尚书复来斯。","手把銅虎符，身總丈人師。","錯落北斗星，照耀黑水湄。","英雄若神授，大材濟时危。","頃歲遇雷云，精神感靈祇。","勳業振青史，恩德繼鴻私。","羌虜昔未平，华陽積僵屍。","人煙絕墟落，鬼火依城池。","巴漢空水流，襃斜惟鸟飞。","自公布德政，此地生光輝。","百堵創里閭，千家恤惸嫠。","層城重鼓角，甲士如熊羆。","坐嘯风自調，行春雨仍隨。","芃芃麦苗长，藹藹桑葉肥。","浮客相與来，羣盜不敢窺。","何幸承嘉惠，小年即相知。","富貴情易疎，相逢心不移。","置酒宴高館，嬌歌杂青絲。","錦席繡拂廬，玉盤金屈巵。","春景透高戟，江云篲长麾。","櫪马嘶柳陰，美人映花枝。","门傳大夫印，世擁上將旗。","承家令名揚，許国苦節施。","戎幕寧久駐，台階不應遲。","別有彈冠士，希君無见遺。"]', '诗', 'shi', '', NULL, '過梁州奉贈張尚書大夫公 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc4df0e9-5056-4457-9d2d-2699416cb6c8', '登北庭北樓呈幕中諸公', '登北庭北楼呈幕中諸公', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["嘗讀西域傳，漢家得輪臺。","古塞千年空，陰山獨崔嵬。","二庭近西海，六月秋風來。","日暮上北樓，殺氣凝不開。","大荒無鳥飛，但見白龍塠。","舊國眇天末，歸心日悠哉。","上將新破胡，西郊絕煙埃。","邊城寂無事，撫劒空徘徊。","幸得趨幕中，託身廁羣才。","早知安邊計，未盡平生懷。"]', '["嘗读西域傳，漢家得輪台。","古塞千年空，陰山独崔嵬。","二庭近西海，六月秋风来。","日暮上北楼，殺氣凝不开。","大荒無鸟飞，但见白龙塠。","旧国眇天末，归心日悠哉。","上將新破胡，西郊絕煙埃。","邊城寂無事，撫劒空徘徊。","幸得趨幕中，託身廁羣才。","早知安邊計，未尽平生懷。"]', '诗', 'shi', '', NULL, '登北庭北樓呈幕中諸公 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d1e9d7-b42a-460c-a2c7-8c7f7c8abc0c', '初過隴山途中呈宇文判官', '初過隴山途中呈宇文判官', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["一驛過一驛，驛騎如星流。","平明發咸陽，暮及隴山頭。","隴水不可聽，嗚咽令人愁。","沙塵撲馬汗，霧露凝貂裘。","西來誰家子，自道新封侯。","前月發安西，路上無停留。","都護猶未到，來時在西州。","十日過沙磧，終朝風不休。","馬走碎石中，四蹄皆血流。","萬里奉王事，一身無所求。","也知塞垣苦，豈爲妻子謀。","山口月欲出，先照關城樓。","谿流與松風，靜夜相颼飀。","別家賴歸夢，山塞多離憂。","與子且攜手，不愁前路脩。"]', '["一驛過一驛，驛騎如星流。","平明發咸陽，暮及隴山头。","隴水不可听，嗚咽令人愁。","沙塵撲马汗，霧露凝貂裘。","西来誰家子，自道新封侯。","前月發安西，路上無停留。","都護猶未到，来时在西州。","十日過沙磧，終朝风不休。","马走碎石中，四蹄皆血流。","万里奉王事，一身無所求。","也知塞垣苦，豈爲妻子謀。","山口月欲出，先照关城楼。","谿流與松风，静夜相颼飀。","別家賴归梦，山塞多離憂。","與子且携手，不愁前路脩。"]', '诗', 'shi', '', NULL, '初過隴山途中呈宇文判官 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7721ae6-c4b9-4a81-9fb5-7e8572d16b19', '陪狄員外早秋登府西樓因呈院中諸公', '陪狄員外早秋登府西楼因呈院中諸公', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["常愛張儀樓，西山正相當。","千峰帶積雪，百里臨城牆。","煙氛掃晴空，草樹映朝光。","車馬隘百井，里閈盤二江。","亞相自登壇，時危安此方。","威聲振蠻貊，惠化鍾華陽。","旌節羅廣庭，戈鋌凜秋霜。","階下貔虎士，幕中鵷鷺行。","今我忽登臨，顧恩不望鄉。","知己猶未報，鬢毛颯已蒼。","時命難自知，功業豈暫忘。","蟬鳴秋城夕，鳥去江天長。","兵馬休戰爭，風塵尚蒼茫。","誰當共攜手，賴有冬官郎。"]', '["常愛張儀楼，西山正相當。","千峰带積雪，百里臨城牆。","煙氛掃晴空，草樹映朝光。","车马隘百井，里閈盤二江。","亞相自登壇，时危安此方。","威声振蠻貊，惠化鍾华陽。","旌節羅廣庭，戈鋌凜秋霜。","階下貔虎士，幕中鵷鷺行。","今我忽登臨，顧恩不望乡。","知己猶未報，鬢毛颯已蒼。","时命难自知，功業豈暫忘。","蟬鳴秋城夕，鸟去江天长。","兵马休戰爭，风塵尚蒼茫。","誰當共携手，賴有冬官郎。"]', '诗', 'shi', '', NULL, '陪狄員外早秋登府西樓因呈院中諸公 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8c17b80-741c-4b1e-a113-59663326839e', '冬夜宿仙遊寺南涼堂呈謙道人', '冬夜宿仙游寺南涼堂呈謙道人', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["太乙連太白，兩山知幾重。","路盤石門窄，匹馬行才通。","日西倒山寺，林下逢支公。","昨夜山北時，星星聞此鐘。","秦女去已久，仙臺在中峰。","簫聲不可聞，此地留遺蹤。","石潭積黛色，每歲投金龍。","亂流爭迅湍，噴薄如雷風。","夜來聞清磬，月出蒼山空。","空山滿清光，水樹相玲瓏。","迴廊映密竹，秋殿隱深松。","燈影落前谿，夜宿水聲中。","愛茲林巒好，結宇向谿東。","相識唯山僧，鄰家一釣翁。","林晚栗初拆，枝寒梨已紅。","物幽興易愜，事勝趣彌濃。","願謝區中緣，永依金人宮。","寄報乘輦客，簪裾爾何容。"]', '["太乙連太白，兩山知幾重。","路盤石门窄，匹马行才通。","日西倒山寺，林下逢支公。","昨夜山北时，星星闻此鐘。","秦女去已久，仙台在中峰。","簫声不可闻，此地留遺蹤。","石潭積黛色，每歲投金龙。","亂流爭迅湍，噴薄如雷风。","夜来闻清磬，月出蒼山空。","空山满清光，水樹相玲瓏。","迴廊映密竹，秋殿隐深松。","灯影落前谿，夜宿水声中。","愛茲林巒好，結宇向谿东。","相識唯山僧，鄰家一釣翁。","林晚栗初拆，枝寒梨已紅。","物幽兴易愜，事勝趣彌濃。","願謝區中緣，永依金人宮。","寄報乘輦客，簪裾爾何容。"]', '诗', 'shi', '', NULL, '冬夜宿仙遊寺南涼堂呈謙道人 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a419c9e-d1ad-4f57-b636-672095a86f3b', '潼關鎮國軍句覆使院早春寄王同州', '潼关鎮国軍句覆使院早春寄王同州', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["胡寇尚未盡，大軍鎮關門。","旌旗遍草木，兵馬如雲屯。","聖朝正用武，諸將皆承恩。","不見征戰功，但聞歌吹喧。","儒生有長策，閉口不敢言。","昨從關東來，思與故人論。","何爲廊廟器，至今居外藩。","黃霸寧淹留，蒼生望騰鶱。","卷簾見西岳，仙掌明朝暾。","昨夜聞春風，戴勝過後園。","各自限官守，何由敘涼溫。","離憂不可忘，襟背思樹萱。"]', '["胡寇尚未尽，大軍鎮关门。","旌旗遍草木，兵马如云屯。","聖朝正用武，諸將皆承恩。","不见征戰功，但闻歌吹喧。","儒生有长策，閉口不敢言。","昨從关东来，思與故人論。","何爲廊廟器，至今居外藩。","黄霸寧淹留，蒼生望腾鶱。","卷簾见西岳，仙掌明朝暾。","昨夜闻春风，戴勝過後园。","各自限官守，何由敘涼溫。","離憂不可忘，襟背思樹萱。"]', '诗', 'shi', '', NULL, '潼關鎮國軍句覆使院早春寄王同州 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b28661ed-66ab-4aae-a48d-43d551d0d933', '青山峽口泊舟懷狄侍御', '青山峽口泊舟懷狄侍御', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["峽口秋水壯，沙邊且停橈。","奔濤振石壁，峰勢如動搖。","九月蘆花新，彌令客心焦。","誰念在江島，故人滿天朝。","無處豁心胸，憂來醉能銷。","往來巴山道，三見秋草彫。","狄生新相知，才調凌雲霄。","賦詩析造化，入幕生風飆。","把筆判甲兵，戰士不敢驕。","皆云梁公後，遇鼎還能調。","離別倏經時，音塵殊寂寥。","何當見夫子，不歎鄉關遙。"]', '["峽口秋水壯，沙邊且停橈。","奔濤振石壁，峰勢如动搖。","九月蘆花新，彌令客心焦。","誰念在江島，故人满天朝。","無处豁心胸，憂来醉能銷。","往来巴山道，三见秋草彫。","狄生新相知，才調凌云霄。","賦诗析造化，入幕生风飆。","把笔判甲兵，戰士不敢驕。","皆云梁公後，遇鼎還能調。","離別倏經时，音塵殊寂寥。","何當见夫子，不歎乡关遙。"]', '诗', 'shi', '', NULL, '青山峽口泊舟懷狄侍御 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f25d4cb7-db31-40c4-9cd7-920435bef9ce', '寄青城龍谿奐道人', '寄青城龙谿奐道人', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["五嶽之丈人，西望青瞢瞢。","雲開露崖嶠，百里見石稜。","龍谿盤中峰，上有蓮華僧。","絕頂小蘭若，四時嵐氣凝。","身同雲虛無，心與谿清澄。","誦戒龍每聽，賦詩人則稱。","杉風吹袈裟，石壁懸孤燈。","久欲謝微祿，誓將歸大乘。","願聞開士說，庶以心相應。"]', '["五嶽之丈人，西望青瞢瞢。","云开露崖嶠，百里见石稜。","龙谿盤中峰，上有蓮华僧。","絕頂小蘭若，四时嵐氣凝。","身同云虛無，心與谿清澄。","誦戒龙每听，賦诗人則稱。","杉风吹袈裟，石壁懸孤灯。","久欲謝微祿，誓將归大乘。","願闻开士说，庶以心相應。"]', '诗', 'shi', '', NULL, '寄青城龍谿奐道人 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5351c2c-243c-4630-a4f6-c6bd98dc6860', '梁州對雨懷麴二秀才便呈麴大判官時疾贈余新詩', '梁州对雨懷麴二秀才便呈麴大判官时疾贈余新诗', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["江上雲氣黑，𡷛山昨夜雷。","水惡平明飛，雨從嶓冢來。","濛濛隨風過，蕭颯鳴庭槐。","隔簾濕衣巾，當暑涼幽齋。","麴生住相近，言語阻且乖。","臥疾不見人，午時門始開。","終日看本草，藥苗滿前堦。","兄弟早有名，甲科皆秀才。","二人事慈母，不弱古老萊。","昨歎攜手遲，未盡平生懷。","愛君有佳句，一日吟幾迴。"]', '["江上云氣黑，𡷛山昨夜雷。","水惡平明飞，雨從嶓冢来。","濛濛隨风過，蕭颯鳴庭槐。","隔簾濕衣巾，當暑涼幽斋。","麴生住相近，言語阻且乖。","臥疾不见人，午时门始开。","終日看本草，藥苗满前堦。","兄弟早有名，甲科皆秀才。","二人事慈母，不弱古老萊。","昨歎携手遲，未尽平生懷。","愛君有佳句，一日吟幾迴。"]', '诗', 'shi', '', NULL, '梁州對雨懷麴二秀才便呈麴大判官時疾贈余新詩 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('093a4462-a81f-40b5-b2eb-a02f1682271c', '潼關使院懷王七季友', '潼关使院懷王七季友', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["王生今才子，時輩咸所仰。","何當見顏色，終日勞夢想。","驅車到關下，欲往阻河廣。","滿日徒春華，思君罷心賞。","開門見太華，朝日映高掌。","忽覺蓮花峰，別來更如長。","無心顧微祿，有意在獨往。","不負林中期，終當出塵網。"]', '["王生今才子，时輩咸所仰。","何當见顏色，終日勞梦想。","驱车到关下，欲往阻河廣。","满日徒春华，思君罷心賞。","开门见太华，朝日映高掌。","忽覺蓮花峰，別来更如长。","無心顧微祿，有意在独往。","不負林中期，終當出塵網。"]', '诗', 'shi', '', NULL, '潼關使院懷王七季友 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b0019bd-e3e0-437c-bdf2-e5a819c3b314', '至大梁却寄匡城主人', '至大梁却寄匡城主人', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["一從棄魚釣，十載干明王。","無由謁天階，却欲歸滄浪。","仲秋至東郡，遂見天雨霜。","昨日夢故山，蕙草色已黃。","平明辭鐵丘，薄暮遊大梁。","仲秋蕭條景，拔刺飛鵝鶬。","四郊陰氣閉，萬里無晶光。","長風吹白茅，野火燒枯桑。","故人南燕吏，籍籍名更香。","聊以玉壺贈，置之君子堂。"]', '["一從棄鱼釣，十載干明王。","無由謁天階，却欲归滄浪。","仲秋至东郡，遂见天雨霜。","昨日梦故山，蕙草色已黄。","平明辞鐵丘，薄暮游大梁。","仲秋蕭條景，拔刺飞鵝鶬。","四郊陰氣閉，万里無晶光。","长风吹白茅，野火燒枯桑。","故人南燕吏，籍籍名更香。","聊以玉壺贈，置之君子堂。"]', '诗', 'shi', '', NULL, '至大梁却寄匡城主人 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52ce2e8b-37ae-4dc2-b1f5-bf257ffbe51d', '宿華陰東郭客舍憶閻防', '宿华陰东郭客舍憶閻防', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["次舍山郭近，解鞍鳴鐘時。","主人炊新粒，行子充夜飢。","關月生首陽，照見華陰祠。","蒼茫秋山晦，蕭瑟寒松悲。","久從園廬別，遂與朋知辭。","舊壑蘭杜晚，歸軒今已遲。"]', '["次舍山郭近，解鞍鳴鐘时。","主人炊新粒，行子充夜飢。","关月生首陽，照见华陰祠。","蒼茫秋山晦，蕭瑟寒松悲。","久從园廬別，遂與朋知辞。","旧壑蘭杜晚，归軒今已遲。"]', '诗', 'shi', '', NULL, '宿華陰東郭客舍憶閻防 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0a108f5-821c-42c2-bbcc-1369e9e30764', '宿東谿王屋李隱者', '宿东谿王屋李隐者', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["山店不鑿井，百家同一泉。","晚來南村黑，雨色和人煙。","霜畦吐寒菜，沙鴈噪河田。","隱者不可見，天壇飛鳥邊。"]', '["山店不鑿井，百家同一泉。","晚来南村黑，雨色和人煙。","霜畦吐寒菜，沙鴈噪河田。","隐者不可见，天壇飞鸟邊。"]', '诗', 'shi', '', NULL, '宿東谿王屋李隱者 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a09ccee7-816d-49a2-998e-c25782c69cb1', '郊行寄杜位', '郊行寄杜位', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["崷崪空城煙，淒清寒山景。","秋風引歸夢，昨夜到汝潁。","近寺聞鐘聲，映陂見樹影。","所思何由見，東北徒引領。"]', '["崷崪空城煙，淒清寒山景。","秋风引归梦，昨夜到汝潁。","近寺闻鐘声，映陂见樹影。","所思何由见，东北徒引領。"]', '诗', 'shi', '', NULL, '郊行寄杜位 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('916ae70b-5bcd-42b2-9d84-d1000dd6a07f', '懷葉縣關操姚曠韓涉李叔齊', '懷葉縣关操姚曠韓涉李叔齊', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["數子皆故人，一時吏宛葉。","經年總不見，書札徒滿篋。","斜日半空庭，旋風走梨葉。","去君千里地，言笑何時接。"]', '["數子皆故人，一时吏宛葉。","經年總不见，书札徒满篋。","斜日半空庭，旋风走梨葉。","去君千里地，言笑何时接。"]', '诗', 'shi', '', NULL, '懷葉縣關操姚曠韓涉李叔齊 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af598c7-93ad-448c-bb5b-19ed6bbbce58', '西蜀旅舍春歎寄朝中故人呈狄評事', '西蜀旅舍春歎寄朝中故人呈狄評事', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["春與人相乖，柳青頭轉白。","生平未得意，覽鏡私自惜。","四海猶未安，一身無所適。","自從兵戈動，遂覺天地窄。","功業悲後時，光陰歎虛擲。","却爲文章累，幸有開濟策。","何負當途人，無心矜窘厄。","回瞻後來者，皆欲肆轥轢。","起草思南宮，寄言憶西掖。","時危任舒卷，身退知損益。","窮巷草轉深，閑門日將夕。","橋西暮雨黑，籬外春江碧。","昨者初識君，相看俱是客。","聲華同道術，世業通往昔。","早須歸天階，不得安孔席。","吾先稅歸鞅，舊國如咫尺。"]', '["春與人相乖，柳青头轉白。","生平未得意，覽镜私自惜。","四海猶未安，一身無所適。","自從兵戈动，遂覺天地窄。","功業悲後时，光陰歎虛擲。","却爲文章累，幸有开濟策。","何負當途人，無心矜窘厄。","回瞻後来者，皆欲肆轥轢。","起草思南宮，寄言憶西掖。","时危任舒卷，身退知損益。","窮巷草轉深，闲门日將夕。","橋西暮雨黑，籬外春江碧。","昨者初識君，相看俱是客。","声华同道術，世業通往昔。","早須归天階，不得安孔席。","吾先稅归鞅，旧国如咫尺。"]', '诗', 'shi', '', NULL, '西蜀旅舍春歎寄朝中故人呈狄評事 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64c3300d-73dd-4024-9e2b-0bab33293496', '太白東溪張老舍即事寄舍弟姪等', '太白东溪張老舍即事寄舍弟姪等', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["渭上秋雨過，北風何騷騷。","天晴諸山出，太白峰最高。","主人東溪老，兩耳生長毫。","遠近知百歲，子孫皆二毛。","中庭井蘭上，一架獮猴桃。","石泉飯香粳，酒甕開新槽。","愛茲田中趣，始悟世上勞。","我行有勝事，書此寄爾曹。"]', '["渭上秋雨過，北风何騷騷。","天晴諸山出，太白峰最高。","主人东溪老，兩耳生长毫。","远近知百歲，子孫皆二毛。","中庭井蘭上，一架獮猴桃。","石泉飯香粳，酒甕开新槽。","愛茲田中趣，始悟世上勞。","我行有勝事，书此寄爾曹。"]', '诗', 'shi', '', NULL, '太白東溪張老舍即事寄舍弟姪等 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0b43182-da20-43f9-9f94-83e45d4c4050', '上嘉州青衣山中峰題惠淨上人幽居寄兵部楊郎中', '上嘉州青衣山中峰題惠淨上人幽居寄兵部楊郎中', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["青衣誰開鑿，獨在水中央。","浮舟一躋攀，側逕緣穹蒼。","絕頂詣老僧，豁然登上方。","諸嶺一何小，三江奔茫茫。","蘭若向西開，峨眉正相當。","猿鳥樂鐘磬，松蘿泛天香。","江雲入袈裟，山月吐繩牀。","早知清淨理，久乃機心忘。","尚以名宦拘，聿來夷獠鄉。","吾友不可見，鬱爲尚書郎。","早歲愛丹經，留心向青囊。","渺渺雲智遠，幽幽海懷長。","勝賞欲與俱，引領遙相望。","爲政媿無術，分憂幸時康。","君子滿天朝，老夫憶滄浪。","況值廬山遠，抽簪歸法王。"]', '["青衣誰开鑿，独在水中央。","浮舟一躋攀，側逕緣穹蒼。","絕頂詣老僧，豁然登上方。","諸嶺一何小，三江奔茫茫。","蘭若向西开，峨眉正相當。","猿鸟乐鐘磬，松蘿泛天香。","江云入袈裟，山月吐繩牀。","早知清淨理，久乃機心忘。","尚以名宦拘，聿来夷獠乡。","吾友不可见，鬱爲尚书郎。","早歲愛丹經，留心向青囊。","渺渺云智远，幽幽海懷长。","勝賞欲與俱，引領遙相望。","爲政媿無術，分憂幸时康。","君子满天朝，老夫憶滄浪。","況值廬山远，抽簪归法王。"]', '诗', 'shi', '', NULL, '上嘉州青衣山中峰題惠淨上人幽居寄兵部楊郎中 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bad4e4c-2743-4e74-898f-686a36ef8989', '入劒門作寄杜楊二郎中時二公並爲杜元帥判官', '入劒门作寄杜楊二郎中时二公並爲杜元帥判官', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["不知造化初，此山誰開坼。","雙崖倚天立，萬仞從地劈。","雲飛不到頂，鳥去難過壁。","速駕畏巖傾，單行愁路窄。","平明地仍黑，停午日暫赤。","凜凜三伏寒，巉巉五丁迹。","與時忽開閉，作固或順逆。","磅礴跨岷峨，巍蟠限蠻貊。","星當觜參分，地處西南僻。","陡覺煙景殊，杳將華夏隔。","劉氏昔顛覆，公孫曾敗績。","始知德不脩，恃此險何益。","相公總師旅，遠近罷金革。","杜母來何遲，蜀人應更惜。","暫回丹青慮，少用開濟策。","二友華省郎，俱爲幕中客。","良籌佐戎律，精理皆碩畫。","高文出詩騷，奧學窮討賾。","聖朝無外戶，寰宇被德澤。","四海今一家，徒然劒門石。"]', '["不知造化初，此山誰开坼。","雙崖倚天立，万仞從地劈。","云飞不到頂，鸟去难過壁。","速駕畏巖傾，單行愁路窄。","平明地仍黑，停午日暫赤。","凜凜三伏寒，巉巉五丁迹。","與时忽开閉，作固或順逆。","磅礴跨岷峨，巍蟠限蠻貊。","星當觜參分，地处西南僻。","陡覺煙景殊，杳將华夏隔。","劉氏昔顛覆，公孫曾敗績。","始知德不脩，恃此險何益。","相公總師旅，远近罷金革。","杜母来何遲，蜀人應更惜。","暫回丹青慮，少用开濟策。","二友华省郎，俱爲幕中客。","良籌佐戎律，精理皆碩畫。","高文出诗騷，奧学窮討賾。","聖朝無外戶，寰宇被德澤。","四海今一家，徒然劒门石。"]', '诗', 'shi', '', NULL, '入劒門作寄杜楊二郎中時二公並爲杜元帥判官 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('472882fa-ac49-477b-a7f9-61337a5f436f', '鞏北秋興寄崔明允', '鞏北秋兴寄崔明允', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["白露披梧桐，玄蟬晝夜號。","秋風萬里動，日暮黃雲高。","君子佐休明，小人事蓬蒿。","所適在魚鳥，焉能徇錐刀。","孤舟向廣武，一鳥歸成臯。","勝概日相與，思君心鬱陶。"]', '["白露披梧桐，玄蟬晝夜號。","秋风万里动，日暮黄云高。","君子佐休明，小人事蓬蒿。","所適在鱼鸟，焉能徇錐刀。","孤舟向廣武，一鸟归成臯。","勝概日相與，思君心鬱陶。"]', '诗', 'shi', '', NULL, '鞏北秋興寄崔明允 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fe04a44-cbf9-497a-9e90-9f1b877e4398', '春遇南使貽趙知音', '春遇南使貽趙知音', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["端居春心醉，襟背思樹萱。","美人在南州，爲爾歌北門。","北風吹煙物，戴勝鳴中園。","枯楊長新條，芳草滋舊根。","網絲結寶琴，塵埃被空樽。","適遇江海信，聊與南客論。"]', '["端居春心醉，襟背思樹萱。","美人在南州，爲爾歌北门。","北风吹煙物，戴勝鳴中园。","枯楊长新條，芳草滋旧根。","網絲結寶琴，塵埃被空樽。","適遇江海信，聊與南客論。"]', '诗', 'shi', '', NULL, '春遇南使貽趙知音 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bccdfe82-5844-42f7-87a4-ed22c385f72c', '冀州客舍酒酣貽王綺寄題南樓', '冀州客舍酒酣貽王綺寄題南楼', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["夫子傲常調，詔書下徵求。","知君欲謁帝，秣馬趨西周。","逸足何駸駸，美聲實風流。","學富贍清詞，下筆不能休。","君家一何盛，赫奕難爲儔。","伯父四五人，同時爲諸侯。","憶昨始相值，值君客貝丘。","相看復乘興，攜手到冀州。","前日在南縣，與君上北樓。","野曠不見山，白日落草頭。","客舍梨花繁，深花隱鳴鳩。","南鄰新酒熟，有女彈箜篌。","醉後或狂歌，酒醒滿離憂。","主人不相識，此地難淹留。","吾廬終南下，堪與王孫遊。","何當肯相尋，澧上一孤舟。"]', '["夫子傲常調，詔书下徵求。","知君欲謁帝，秣马趨西周。","逸足何駸駸，美声實风流。","学富贍清词，下笔不能休。","君家一何盛，赫奕难爲儔。","伯父四五人，同时爲諸侯。","憶昨始相值，值君客貝丘。","相看复乘兴，携手到冀州。","前日在南縣，與君上北楼。","野曠不见山，白日落草头。","客舍梨花繁，深花隐鳴鳩。","南鄰新酒熟，有女彈箜篌。","醉後或狂歌，酒醒满離憂。","主人不相識，此地难淹留。","吾廬終南下，堪與王孫游。","何當肯相尋，澧上一孤舟。"]', '诗', 'shi', '', NULL, '冀州客舍酒酣貽王綺寄題南樓 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bbc6eab-07e3-4735-a4f5-02553e20c5c2', '終南雲際精舍尋法澄上人不遇歸高冠東潭石淙望秦嶺微雨作貽友人', '終南云際精舍尋法澄上人不遇归高冠东潭石淙望秦嶺微雨作貽友人', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["昨夜雲際宿，旦從西峰回。","不見林中僧，微雨潭上來。","諸峰皆青翠，秦嶺獨不開。","石鼓有時鳴，秦王安在哉。","東南雲開處，突兀獮猴臺。","崖口懸瀑流，半空白皚皚。","噴壁四時雨，傍村終日雷。","北瞻長安道，日夕生塵埃。","若訪張仲蔚，衡門滿蒿萊。"]', '["昨夜云際宿，旦從西峰回。","不见林中僧，微雨潭上来。","諸峰皆青翠，秦嶺独不开。","石鼓有时鳴，秦王安在哉。","东南云开处，突兀獮猴台。","崖口懸瀑流，半空白皚皚。","噴壁四时雨，傍村終日雷。","北瞻长安道，日夕生塵埃。","若訪張仲蔚，衡门满蒿萊。"]', '诗', 'shi', '', NULL, '終南雲際精舍尋法澄上人不遇歸高冠東潭石淙望秦嶺微雨作貽友人 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c8dbeec-c8f3-4fbe-8621-e571aa2edcb5', '敬酬杜華淇上見贈兼呈熊曜', '敬酬杜华淇上见贈兼呈熊曜', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["杜侯實才子，盛名不可及。","祗曾效一官，今已年四十。","是君同時者，已有尚書郎。","憐君獨未遇，淹泊在他鄉。","我從京師來，到此喜相見。","共論窮途事，不覺淚滿面。","憶昨癸未歲，吾兄自江東。","得君江湖詩，骨氣凌謝公。","熊生尉淇上，開館常待客。","喜我二人來，歡笑朝復夕。","縣樓壓春岸，戴勝鳴花枝。","吾徒在舟中，縱酒兼彈棊。","三月猶未還，寒愁滿春草。","賴蒙瑤華贈，諷詠慰懷抱。"]', '["杜侯實才子，盛名不可及。","祗曾效一官，今已年四十。","是君同时者，已有尚书郎。","怜君独未遇，淹泊在他乡。","我從京師来，到此喜相见。","共論窮途事，不覺泪满面。","憶昨癸未歲，吾兄自江东。","得君江湖诗，骨氣凌謝公。","熊生尉淇上，开館常待客。","喜我二人来，歡笑朝复夕。","縣楼壓春岸，戴勝鳴花枝。","吾徒在舟中，縱酒兼彈棊。","三月猶未還，寒愁满春草。","賴蒙瑤华贈，諷詠慰懷抱。"]', '诗', 'shi', '', NULL, '敬酬杜華淇上見贈兼呈熊曜 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffc4b9fb-e4d3-4834-a32b-421e7447aec7', '酬成少尹駱谷行見呈', '酬成少尹駱谷行见呈', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["聞君行路難，惆悵臨長衢。","豈不憚險艱，王程剩相拘。","憶昨蓬萊宮，新授刺史符。","明主仍賜衣，價直千萬餘。","何幸承命日，得與夫子俱。","攜手出華省，連鑣赴長途。","五馬當路嘶，按節投蜀都。","千崖信縈折，一徑何盤紆。","層冰滑征輪，密竹礙隼旟。","深林迷昏旦，棧道凌空虛。","飛雪縮馬毛，烈風擘我膚。","峰攢望天小，亭午見日初。","夜宿月近人，朝行雲滿車。","泉澆石罅坼，火入松心枯。","亞尹同心者，風流賢大夫。","榮祿上及親，之官隨板輿。","高價振臺閣，清詞出應徐。","成都春酒香，且用俸錢沽。","浮名何足道，海上堪乘桴。"]', '["闻君行路难，惆悵臨长衢。","豈不憚險艱，王程剩相拘。","憶昨蓬萊宮，新授刺史符。","明主仍賜衣，價直千万餘。","何幸承命日，得與夫子俱。","携手出华省，連鑣赴长途。","五马當路嘶，按節投蜀都。","千崖信縈折，一徑何盤紆。","層冰滑征輪，密竹礙隼旟。","深林迷昏旦，棧道凌空虛。","飞雪縮马毛，烈风擘我膚。","峰攢望天小，亭午见日初。","夜宿月近人，朝行云满车。","泉澆石罅坼，火入松心枯。","亞尹同心者，风流賢大夫。","榮祿上及親，之官隨板輿。","高價振台閣，清词出應徐。","成都春酒香，且用俸錢沽。","浮名何足道，海上堪乘桴。"]', '诗', 'shi', '', NULL, '酬成少尹駱谷行見呈 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb46a46b-7333-4bd7-a0b9-c2ae942ad5a1', '虢中酬陝西甄判官見贈', '虢中酬陝西甄判官见贈', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["微才棄散地，拙宦慙清時。","白髮徒自負，青雲難可期。","胡塵暗東洛，亞相方出師。","分陝振鼓鼙，二崤滿旌旗。","夫子廊廟器，迥然青冥姿。","閫外佐戎律，幕中吐兵奇。","前者驛使來，忽枉行軍詩。","晝吟庭花落，夜諷山月移。","昔君隱蘇門，浪跡不可羈。","詔書自徵用，令譽天下知。","別來春草長，東望轉相思。","寂寞山城暮，空聞畫角悲。"]', '["微才棄散地，拙宦慙清时。","白髮徒自負，青云难可期。","胡塵暗东洛，亞相方出師。","分陝振鼓鼙，二崤满旌旗。","夫子廊廟器，迥然青冥姿。","閫外佐戎律，幕中吐兵奇。","前者驛使来，忽枉行軍诗。","晝吟庭花落，夜諷山月移。","昔君隐蘇门，浪跡不可羈。","詔书自徵用，令譽天下知。","別来春草长，东望轉相思。","寂寞山城暮，空闻畫角悲。"]', '诗', 'shi', '', NULL, '虢中酬陝西甄判官見贈 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25849a42-a664-4d42-915d-62487e326b3c', '送許子擢第歸江寧拜親因寄王大昌齡', '送許子擢第归江寧拜親因寄王大昌齡', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["建業控京口，金陵款滄溟。","君家臨秦淮，傍對石頭城。","十年自勤學，一鼓遊上京。","青春登甲科，動地聞香名。","解榻皆五侯，結交盡羣英。","六月槐花飛，忽思蓴菜羹。","跨馬出國門，丹陽返柴荆。","楚雲引歸帆，淮水浮客程。","到家拜親時，入門有光榮。","鄉人盡來賀，置酒相邀迎。","閑眺北顧樓，醉眠湖上亭。","月從海門出，照見茅山青。","昔爲帝王州，今幸天地平。","五朝變人世，千載空江聲。","玄元告靈符，丹洞獲其銘。","皇帝受玉冊，羣臣羅天庭。","喜氣薄太陽，祥光徹窅冥。","奔走朝萬國，崩騰集百靈。","王兄尚謫宦，屢見秋雲生。","孤城帶後湖，心與湖水清。","一縣無諍辭，有時開道經。","黃鶴垂兩翅，徘徊但悲鳴。","相思不可見，空望牛女星。"]', '["建業控京口，金陵款滄溟。","君家臨秦淮，傍对石头城。","十年自勤学，一鼓游上京。","青春登甲科，动地闻香名。","解榻皆五侯，結交尽羣英。","六月槐花飞，忽思蓴菜羹。","跨马出国门，丹陽返柴荆。","楚云引归帆，淮水浮客程。","到家拜親时，入门有光榮。","乡人尽来賀，置酒相邀迎。","闲眺北顧楼，醉眠湖上亭。","月從海门出，照见茅山青。","昔爲帝王州，今幸天地平。","五朝变人世，千載空江声。","玄元告靈符，丹洞獲其銘。","皇帝受玉冊，羣臣羅天庭。","喜氣薄太陽，祥光徹窅冥。","奔走朝万国，崩腾集百靈。","王兄尚謫宦，屢见秋云生。","孤城带後湖，心與湖水清。","一縣無諍辞，有时开道經。","黄鹤垂兩翅，徘徊但悲鳴。","相思不可见，空望牛女星。"]', '诗', 'shi', '', NULL, '送許子擢第歸江寧拜親因寄王大昌齡 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85667af2-aebc-4bf5-bae4-e276799fb52e', '武威送劉單判官赴安西行營便呈高開府', '武威送劉單判官赴安西行營便呈高开府', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["熱海亙鐵門，火山赫金方。","白草磨天涯，湖沙奔茫茫。","夫子佐戎幕，其鋒利如霜。","中歲學兵符，不能守文章。","功業須及時，立身有行藏。","男兒感忠義，萬里忘越鄉。","孟夏邊候遲，胡國草木長。","馬疾過飛鳥，天窮超夕陽。","都護新出師，五月發軍裝。","甲兵二百萬，錯落黃金光。","揚旗拂崑崙，伐鼓震蒲昌。","太白引官軍，天威臨大荒。","西望雲似蛇，戎夷知喪亡。","渾驅大宛馬，繫取樓蘭王。","曾到交河城，風土斷人腸。","寒驛遠如點，邊烽互相望。","赤亭多飃風，鼓怒不可當。","有時無人行，沙石亂飄揚。","夜靜天蕭條，鬼哭夾道傍。","地上多髑髏，皆是古戰場。","置酒高館夕，邊城月蒼蒼。","軍中宰肥牛，堂上羅羽觴。","紅淚金燭盤，嬌歌豔新妝。","望君仰青冥，短翮難可翔。","蒼然西郊道，握手何慨慷。"]', '["熱海亙鐵门，火山赫金方。","白草磨天涯，湖沙奔茫茫。","夫子佐戎幕，其鋒利如霜。","中歲学兵符，不能守文章。","功業須及时，立身有行藏。","男兒感忠義，万里忘越乡。","孟夏邊候遲，胡国草木长。","马疾過飞鸟，天窮超夕陽。","都護新出師，五月發軍裝。","甲兵二百万，錯落黄金光。","揚旗拂崑崙，伐鼓震蒲昌。","太白引官軍，天威臨大荒。","西望云似蛇，戎夷知喪亡。","渾驱大宛马，繫取楼蘭王。","曾到交河城，风土斷人腸。","寒驛远如点，邊烽互相望。","赤亭多飃风，鼓怒不可當。","有时無人行，沙石亂飄揚。","夜静天蕭條，鬼哭夾道傍。","地上多髑髏，皆是古戰場。","置酒高館夕，邊城月蒼蒼。","軍中宰肥牛，堂上羅羽觴。","紅泪金燭盤，嬌歌豔新妝。","望君仰青冥，短翮难可翔。","蒼然西郊道，握手何慨慷。"]', '诗', 'shi', '', NULL, '武威送劉單判官赴安西行營便呈高開府 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f4c5101-f4f8-470c-97cc-aa67d313658c', '送王大昌齡赴江寧', '送王大昌齡赴江寧', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["對酒寂不語，悵然悲送君。","明時未得用，白首徒攻文。","澤國從一官，滄波幾千里。","羣公滿天闕，獨去過淮水。","舊家富春渚，嘗憶臥江樓。","自聞君欲行，頻望南徐州。","窮巷獨閉門，寒燈靜深屋。","北風吹微雪，抱被肯同宿。","君行到京口，正是桃花時。","舟中饒孤興，湖上多新詩。","潛虯且深蟠，黃鵠舉未晚。","惜君青雲器，努力加餐飯。"]', '["对酒寂不語，悵然悲送君。","明时未得用，白首徒攻文。","澤国從一官，滄波幾千里。","羣公满天闕，独去過淮水。","旧家富春渚，嘗憶臥江楼。","自闻君欲行，頻望南徐州。","窮巷独閉门，寒灯静深屋。","北风吹微雪，抱被肯同宿。","君行到京口，正是桃花时。","舟中饒孤兴，湖上多新诗。","潛虯且深蟠，黄鵠舉未晚。","惜君青云器，努力加餐飯。"]', '诗', 'shi', '', NULL, '送王大昌齡赴江寧 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a16ba513-8718-4ac8-9e1a-2af11487636e', '送祈樂歸河東', '送祈乐归河东', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["祁樂後來秀，挺身出河東。","往年詣驪山，獻賦溫泉宮。","天子不召見，揮鞭遂從戎。","前月還長安，囊中金已空。","有時忽乘興，畫出江上峰。","牀頭蒼梧雲，簾下天台松。","忽如高堂上，颯颯生清風。","五月火雲屯，氣燒天地紅。","鳥且不敢飛，子行如轉蓬。","少華與首陽，隔河勢爭雄。","新月河上出，清光滿關中。","置酒灞亭別，高歌披心胸。","君到故山時，爲謝五老翁。"]', '["祁乐後来秀，挺身出河东。","往年詣驪山，獻賦溫泉宮。","天子不召见，揮鞭遂從戎。","前月還长安，囊中金已空。","有时忽乘兴，畫出江上峰。","牀头蒼梧云，簾下天台松。","忽如高堂上，颯颯生清风。","五月火云屯，氣燒天地紅。","鸟且不敢飞，子行如轉蓬。","少华與首陽，隔河勢爭雄。","新月河上出，清光满关中。","置酒灞亭別，高歌披心胸。","君到故山时，爲謝五老翁。"]', '诗', 'shi', '', NULL, '送祈樂歸河東 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ea9a3b-2112-4d16-a7f7-e4bdf913a3e1', '北庭貽宗學士道別', '北庭貽宗学士道別', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["萬事不可料，歎君在軍中。","讀書破萬卷，何事來從戎。","曾逐李輕車，西征出太蒙。","荷戈月窟外，擐甲崑崙東。","兩度皆破胡，朝廷輕戰功。","十年祗一命，萬里如飄蓬。","容鬢老胡塵，衣裘脆邊風。","忽來輪臺下，相見披心胸。","飲酒對春草，彈棊聞夜鐘。","今且還龜茲，臂上懸角弓。","平沙向旅館，匹馬隨飛鴻。","孤城倚大磧，海氣迎邊空。","四月猶自寒，天山雪濛濛。","君有賢主將，何謂泣途窮。","時來整六翮，一舉凌蒼穹。"]', '["万事不可料，歎君在軍中。","读书破万卷，何事来從戎。","曾逐李轻车，西征出太蒙。","荷戈月窟外，擐甲崑崙东。","兩度皆破胡，朝廷轻戰功。","十年祗一命，万里如飄蓬。","容鬢老胡塵，衣裘脆邊风。","忽来輪台下，相见披心胸。","饮酒对春草，彈棊闻夜鐘。","今且還龟茲，臂上懸角弓。","平沙向旅館，匹马隨飞鴻。","孤城倚大磧，海氣迎邊空。","四月猶自寒，天山雪濛濛。","君有賢主將，何謂泣途窮。","时来整六翮，一舉凌蒼穹。"]', '诗', 'shi', '', NULL, '北庭貽宗學士道別 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcbc6ae9-8edb-4965-95f5-c438601feb85', '送許拾遺恩歸江寧拜親', '送許拾遺恩归江寧拜親', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["詔書下青瑣，駟馬還吳洲。","束帛仍賜衣，恩波漲滄流。","微祿將及親，向家非遠遊。","看君五斗米，不謝萬戶侯。","適出西掖垣，如到南徐州。","歸心望海日，鄉夢登江樓。","大江盤金陵，諸山橫石頭。","楓樹隱茅屋，橘林繫漁舟。","種藥疏故畦，釣魚垂舊鈎。","對月京口夕，觀濤海門秋。","天子憐諫官，論事不可休。","早來丹墀下，高駕無淹留。"]', '["詔书下青瑣，駟马還吳洲。","束帛仍賜衣，恩波漲滄流。","微祿將及親，向家非远游。","看君五斗米，不謝万戶侯。","適出西掖垣，如到南徐州。","归心望海日，乡梦登江楼。","大江盤金陵，諸山橫石头。","楓樹隐茅屋，橘林繫漁舟。","種藥疏故畦，釣鱼垂旧鈎。","对月京口夕，观濤海门秋。","天子怜諫官，論事不可休。","早来丹墀下，高駕無淹留。"]', '诗', 'shi', '', NULL, '送許拾遺恩歸江寧拜親 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ef5d9b-c0ea-4fc9-899f-941ff0c06830', '虢州郡齋南池幽興因與閻二侍御道別', '虢州郡斋南池幽兴因與閻二侍御道別', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["池色淨天碧，水涼雨淒淒。","快風從東南，荷葉翻向西。","性本愛魚鳥，未能返巖谿。","中歲徇微官，遂令心賞睽。","及茲佐山郡，不異尋幽棲。","小吏趨竹徑，訟庭侵藥畦。","胡塵暗河洛，二陝震鼓鼙。","故人佐戎軒，逸翮凌雲霓。","行軍在函谷，兩度聞鶯啼。","相看紅旗下，飲酒白日低。","聞君欲朝天，駟馬臨道嘶。","仰望浮與沈，忽如雲與泥。","夜眠驛樓月，曉發關城雞。","惆悵西郊暮，鄉書對君題。"]', '["池色淨天碧，水涼雨淒淒。","快风從东南，荷葉翻向西。","性本愛鱼鸟，未能返巖谿。","中歲徇微官，遂令心賞睽。","及茲佐山郡，不異尋幽棲。","小吏趨竹徑，訟庭侵藥畦。","胡塵暗河洛，二陝震鼓鼙。","故人佐戎軒，逸翮凌云霓。","行軍在函谷，兩度闻鶯啼。","相看紅旗下，饮酒白日低。","闻君欲朝天，駟马臨道嘶。","仰望浮與沈，忽如云與泥。","夜眠驛楼月，晓發关城雞。","惆悵西郊暮，乡书对君題。"]', '诗', 'shi', '', NULL, '虢州郡齋南池幽興因與閻二侍御道別 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36e31945-0de1-4cb6-9948-2e16fc32ecc8', '青龍招提歸一上人遠遊吳楚別詩', '青龙招提归一上人远游吳楚別诗', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["久交應真侶，最歎青龍僧。","棄官向二年，削髮歸一乘。","了然瑩心身，潔念樂空寂。","名香泛牕戶，幽磬清曉夕。","往年仗一劒，由是佐二庭。","於焉久從戎，兼復解論兵。","世人猶未知，天子願相見。","朝從青蓮宇，暮入白虎殿。","宮女擎錫杖，御筵出香爐。","說法開藏經，論邊窮陣圖。","忘機厭塵喧，浪迹向江海。","思師石可訪，惠遠峰猶在。","今旦飛錫去，何時持鉢還。","湖煙冷吳門，淮月銜楚山。","一身如浮雲，萬里過江水。","相思眇天末，南望無窮已。"]', '["久交應真侶，最歎青龙僧。","棄官向二年，削髮归一乘。","了然瑩心身，潔念乐空寂。","名香泛牕戶，幽磬清晓夕。","往年仗一劒，由是佐二庭。","於焉久從戎，兼复解論兵。","世人猶未知，天子願相见。","朝從青蓮宇，暮入白虎殿。","宮女擎錫杖，御筵出香爐。","说法开藏經，論邊窮陣圖。","忘機厭塵喧，浪迹向江海。","思師石可訪，惠远峰猶在。","今旦飞錫去，何时持鉢還。","湖煙冷吳门，淮月銜楚山。","一身如浮云，万里過江水。","相思眇天末，南望無窮已。"]', '诗', 'shi', '', NULL, '青龍招提歸一上人遠遊吳楚別詩 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad00d03e-77ae-4459-82a1-6e5430e5d3b6', '送李翥遊江外', '送李翥游江外', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["相識應十載，見君只一官。","家貧祿尚薄，霜降衣仍單。","惆悵秋草死，蕭條芳歲闌。","且尋滄洲路，遙指吳雲端。","匹馬關塞遠，孤舟江海寬。","夜眠楚煙濕，曉飯湖山寒。","砧淨紅鱠落，袖香朱橘團。","帆前見禹廟，枕底聞嚴灘。","便獲賞心趣，豈歌行路難。","青門須醉別，少爲解征鞍。"]', '["相識應十載，见君只一官。","家貧祿尚薄，霜降衣仍單。","惆悵秋草死，蕭條芳歲闌。","且尋滄洲路，遙指吳云端。","匹马关塞远，孤舟江海寬。","夜眠楚煙濕，晓飯湖山寒。","砧淨紅鱠落，袖香朱橘團。","帆前见禹廟，枕底闻嚴灘。","便獲賞心趣，豈歌行路难。","青门須醉別，少爲解征鞍。"]', '诗', 'shi', '', NULL, '送李翥遊江外 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be42f392-f4eb-4aff-b047-eea46f845f25', '送王著作赴淮西幕府', '送王著作赴淮西幕府', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["燕子與百勞，一西復一東。","天空信寥廓，翔集何時同。","知己悵難遇，良朋非易逢。","憐君心相親，與我家又通。","言笑日無度，書札凡幾封。","湛湛萬頃陂，森森千丈松。","不知有機巧，無事干心胸。","滿堂皆酒徒，豈復羨王公。","早年抱將略，累歲依幕中。","昨者從淮西，歸來奏邊功。","承恩長樂殿，醉出明光宮。","逆旅悲寒蟬，客夢驚飛鴻。","發家見春草，却去聞秋風。","月色冷楚城，淮光透霜空。","各自務功業，當須激深衷。","別後能相思，何嗟山水重。"]', '["燕子與百勞，一西复一东。","天空信寥廓，翔集何时同。","知己悵难遇，良朋非易逢。","怜君心相親，與我家又通。","言笑日無度，书札凡幾封。","湛湛万頃陂，森森千丈松。","不知有機巧，無事干心胸。","满堂皆酒徒，豈复羨王公。","早年抱將略，累歲依幕中。","昨者從淮西，归来奏邊功。","承恩长乐殿，醉出明光宮。","逆旅悲寒蟬，客梦驚飞鴻。","發家见春草，却去闻秋风。","月色冷楚城，淮光透霜空。","各自務功業，當須激深衷。","別後能相思，何嗟山水重。"]', '诗', 'shi', '', NULL, '送王著作赴淮西幕府 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('409c2864-271b-4d97-a1da-4a8baf032136', '送張秘書充劉相公通汴河判官便赴江外覲省', '送張秘书充劉相公通汴河判官便赴江外覲省', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["前年見君時，見君正泥蟠。","去年見君處，見君已風[摶]。","朝趨赤墀前，高視青雲端。","新登麒麟閣，適脫獬豸冠。","劉公領舟楫，汴水揚波瀾。","萬里江海通，九州天地寬。","昨夜動使星，今旦送征鞍。","老親在吳郡，令弟雙同官。","鱸鱠賸堪憶，蓴羹殊可餐。","既參幕中畫，復展膝下歡。","因送故人行，試歌行路難。","何處路最難，最難在長安。","長安多權貴，珂珮聲珊珊。","儒生直如弦，權貴不須干。","斗酒取一醉，孤琴爲君彈。","臨岐欲有贈，持以握中蘭。"]', '["前年见君时，见君正泥蟠。","去年见君处，见君已风[摶]。","朝趨赤墀前，高視青云端。","新登麒麟閣，適脫獬豸冠。","劉公領舟楫，汴水揚波瀾。","万里江海通，九州天地寬。","昨夜动使星，今旦送征鞍。","老親在吳郡，令弟雙同官。","鱸鱠賸堪憶，蓴羹殊可餐。","既參幕中畫，复展膝下歡。","因送故人行，試歌行路难。","何处路最难，最难在长安。","长安多權貴，珂珮声珊珊。","儒生直如弦，權貴不須干。","斗酒取一醉，孤琴爲君彈。","臨岐欲有贈，持以握中蘭。"]', '诗', 'shi', '', NULL, '送張秘書充劉相公通汴河判官便赴江外覲省 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d101f32-fe42-4d24-b83a-b00b0a23ba8c', '冬宵家會餞李郎司兵赴同州', '冬宵家會餞李郎司兵赴同州', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["急管雜青絲，玉瓶金屈巵。","寒天高堂夜，撲地飛雪時。","賀君關西掾，新綬腰下垂。","白面皇家郎，逸翮青雲姿。","明旦之官去，他辰良會稀。","惜別冬夜短，務歡盃行遲。","季女猶自小，老夫未令歸。","且看匹馬行，不得鳴鳳飛。","昔歲到馮翊，人煙接京師。","曾上月樓頭，遙見西嶽祠。","沙苑逼官舍，蓮峰壓城池。","多暇或自公，讀書復彈棊。","州縣信徒勞，雲霄亦可期。","應須力爲政，聊慰此相思。"]', '["急管杂青絲，玉瓶金屈巵。","寒天高堂夜，撲地飞雪时。","賀君关西掾，新綬腰下垂。","白面皇家郎，逸翮青云姿。","明旦之官去，他辰良會稀。","惜別冬夜短，務歡盃行遲。","季女猶自小，老夫未令归。","且看匹马行，不得鳴鳳飞。","昔歲到馮翊，人煙接京師。","曾上月楼头，遙见西嶽祠。","沙苑逼官舍，蓮峰壓城池。","多暇或自公，读书复彈棊。","州縣信徒勞，云霄亦可期。","應須力爲政，聊慰此相思。"]', '诗', 'shi', '', NULL, '冬宵家會餞李郎司兵赴同州 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f16a15a-54fd-41bc-8302-167f7d94399d', '送顏平原', '送顏平原', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["天子念黎庶，詔書換諸侯。","仙郎授剖符，華省輟分憂。","置酒會前殿，賜錢若山丘。","天章降三光，聖澤該九州。","吾兄鎮河朔，拜命宣皇猷。","駟馬辭國門，一星東北流。","夏雲照銀印，暑雨隨行輈。","赤筆仍在篋，鑪香惹衣裘。","此地鄰東溟，孤城弔滄洲。","海風掣金戟，道吏呼鳴騶。","郊原北連燕，剽劫風未休。","魚鹽隘里巷，桑柘盈田疇。","爲郡豈淹旬，政成應未秋。","易俗去猛虎，化人似馴鷗。","蒼生已望君，黃霸寧久留。"]', '["天子念黎庶，詔书換諸侯。","仙郎授剖符，华省輟分憂。","置酒會前殿，賜錢若山丘。","天章降三光，聖澤該九州。","吾兄鎮河朔，拜命宣皇猷。","駟马辞国门，一星东北流。","夏云照銀印，暑雨隨行輈。","赤笔仍在篋，鑪香惹衣裘。","此地鄰东溟，孤城弔滄洲。","海风掣金戟，道吏呼鳴騶。","郊原北連燕，剽劫风未休。","鱼鹽隘里巷，桑柘盈田疇。","爲郡豈淹旬，政成應未秋。","易俗去猛虎，化人似馴鷗。","蒼生已望君，黄霸寧久留。"]', '诗', 'shi', '', NULL, '送顏平原 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0fa8e6b-0422-4a12-9311-8c931d5657c2', '送狄員外巡按西山軍', '送狄員外巡按西山軍', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["兵馬守西山，中國非得計。","不知何代策，空使蜀人弊。","八州崖谷深，千里雲雪閉。","泉澆閣道滑，水凍繩橋脆。","戰士常苦飢，糗粮不相繼。","胡兵猶不歸，空山積年歲。","儒生識損益，言事皆審諦。","狄子幕府郎，有謀必康濟。","胸中懸明鏡，照耀無巨細。","莫辭冒險艱，可以裨節制。","相思江樓夕，愁見月澄霽。"]', '["兵马守西山，中国非得計。","不知何代策，空使蜀人弊。","八州崖谷深，千里云雪閉。","泉澆閣道滑，水凍繩橋脆。","戰士常苦飢，糗粮不相繼。","胡兵猶不归，空山積年歲。","儒生識損益，言事皆審諦。","狄子幕府郎，有謀必康濟。","胸中懸明镜，照耀無巨細。","莫辞冒險艱，可以裨節制。","相思江楼夕，愁见月澄霽。"]', '诗', 'shi', '', NULL, '送狄員外巡按西山軍 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d543fbde-e2c5-4d37-aaae-c9df0fd3df65', '虢州送鄭興宗弟歸扶風別廬', '虢州送鄭兴宗弟归扶风別廬', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["佐郡已三載，豈能長後時。","出關少親友，賴汝常相隨。","今旦忽言別，愴然俱淚垂。","平生滄洲意，獨有青山知。","州縣不敢說，雲霄誰敢期。","因懷東谿老，最憶南峰緇。","爲我多種藥，還山應未遲。"]', '["佐郡已三載，豈能长後时。","出关少親友，賴汝常相隨。","今旦忽言別，愴然俱泪垂。","平生滄洲意，独有青山知。","州縣不敢说，云霄誰敢期。","因懷东谿老，最憶南峰緇。","爲我多種藥，還山應未遲。"]', '诗', 'shi', '', NULL, '虢州送鄭興宗弟歸扶風別廬 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8b581ae-5778-4e40-8bc0-2c3fa3767944', '澧頭送蔣侯', '澧头送蔣侯', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["君住澧水北，我家澧水西。","兩村辨喬木，五里聞鳴雞。","飲酒溪雨過，彈棊山月低。","徒聞蔣生徑，爾去誰相攜。"]', '["君住澧水北，我家澧水西。","兩村辨喬木，五里闻鳴雞。","饮酒溪雨過，彈棊山月低。","徒闻蔣生徑，爾去誰相携。"]', '诗', 'shi', '', NULL, '澧頭送蔣侯 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c0909fb-47ab-48d7-81d6-1c92db828a6f', '送永壽王贊府逕歸縣', '送永壽王贊府逕归縣', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["當官接閑暇，暫得歸林泉。","百里路不宿，兩鄉山復連。","夜深露濕簟，月出風驚蟬。","且盡主人酒，爲君從醉眠。"]', '["當官接闲暇，暫得归林泉。","百里路不宿，兩乡山复連。","夜深露濕簟，月出风驚蟬。","且尽主人酒，爲君從醉眠。"]', '诗', 'shi', '', NULL, '送永壽王贊府逕歸縣 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2ffc9dd-697f-4fb4-9108-dc7772317111', '南池宴餞辛子賦得蝌斗子', '南池宴餞辛子賦得蝌斗子', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["臨池見蝌斗，羨爾樂有餘。","不憂網與釣，幸得免爲魚。","且願充文字，登君尺素書。"]', '["臨池见蝌斗，羨爾乐有餘。","不憂網與釣，幸得免爲鱼。","且願充文字，登君尺素书。"]', '诗', 'shi', '', NULL, '南池宴餞辛子賦得蝌斗子 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09abdb47-df32-4c61-8835-624e2b018077', '登嘉州凌雲寺作', '登嘉州凌云寺作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["寺出飛鳥外，青峰戴朱樓。","搏壁躋半空，喜得登上頭。","始知宇宙闊，下看三江流。","天晴見峨眉，如向波上浮。","迥曠煙景豁，陰森椶枏稠。","願割區中緣，永從塵外遊。","迴風吹虎穴，片雨當龍湫。","僧房雲濛濛，夏月寒颼颼。","回合俯近郭，寥落見遠舟。","勝概無端倪，天宮可淹留。","一官詎足道，欲去令人愁。"]', '["寺出飞鸟外，青峰戴朱楼。","搏壁躋半空，喜得登上头。","始知宇宙闊，下看三江流。","天晴见峨眉，如向波上浮。","迥曠煙景豁，陰森椶枏稠。","願割區中緣，永從塵外游。","迴风吹虎穴，片雨當龙湫。","僧房云濛濛，夏月寒颼颼。","回合俯近郭，寥落见远舟。","勝概無端倪，天宮可淹留。","一官詎足道，欲去令人愁。"]', '诗', 'shi', '', NULL, '登嘉州凌雲寺作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93d82a12-5e4d-45c2-b837-d0c54447fba3', '與高適薛據慈恩寺浮圖', '與高適薛據慈恩寺浮圖', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["塔勢如湧出，孤高聳天宮。","登臨出世界，磴道盤虛空。","突兀壓神州，崢嶸如鬼工。","四角礙白日，七層摩蒼穹。","下窺指高鳥，俯聽聞驚風。","連山若波濤，奔湊似朝東。","青槐夾馳道，宮館何玲瓏。","秋色從西來，蒼然滿關中。","五陵北原上，萬古青濛濛。","淨理了可悟，勝因夙所宗。","誓將挂冠去，覺道資無窮。"]', '["塔勢如湧出，孤高聳天宮。","登臨出世界，磴道盤虛空。","突兀壓神州，崢嶸如鬼工。","四角礙白日，七層摩蒼穹。","下窺指高鸟，俯听闻驚风。","連山若波濤，奔湊似朝东。","青槐夾驰道，宮館何玲瓏。","秋色從西来，蒼然满关中。","五陵北原上，万古青濛濛。","淨理了可悟，勝因夙所宗。","誓將挂冠去，覺道資無窮。"]', '诗', 'shi', '', NULL, '與高適薛據慈恩寺浮圖 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d015d5d-e928-4a58-8897-b42765cefc31', '登千福寺楚金禪師法華院多寶塔', '登千福寺楚金禪師法华院多寶塔', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["多寶滅已久，蓮華付吾師。","寶塔凌太空，忽如湧出時。","數年功不成，一志堅自持。","明主親夢見，世人今始知。","千家獻黃金，萬匠磨琉璃。","既空泰山木，亦罄天府貲。","焚香如雲屯，蟠蓋珊珊垂。","悉窣神繞護，衆魔不敢窺。","作禮覩靈境，焚香方證疑。","庶割區中緣，脫身恆在茲。"]', '["多寶滅已久，蓮华付吾師。","寶塔凌太空，忽如湧出时。","數年功不成，一志堅自持。","明主親梦见，世人今始知。","千家獻黄金，万匠磨琉璃。","既空泰山木，亦罄天府貲。","焚香如云屯，蟠蓋珊珊垂。","悉窣神繞護，衆魔不敢窺。","作禮覩靈境，焚香方證疑。","庶割區中緣，脫身恆在茲。"]', '诗', 'shi', '', NULL, '登千福寺楚金禪師法華院多寶塔 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5847653-9150-4041-929e-b97ff6516554', '出關經華嶽寺訪法華雲公', '出关經华嶽寺訪法华云公', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["野寺聊解鞍，偶見法華僧。","開門對西嶽，石壁青稜層。","竹徑厚蒼苔，松門盤紫藤。","長廊列古畫，高殿懸孤燈。","五月山雨熱，三峰火雲蒸。","側聞樵人言，深谷猶積冰。","久願尋此山，至今嗟未能。","謫官忽東走，王程苦相仍。","欲去戀雙樹，何由窮一乘。","月輪吐山郭，夜色空清澄。"]', '["野寺聊解鞍，偶见法华僧。","开门对西嶽，石壁青稜層。","竹徑厚蒼苔，松门盤紫藤。","长廊列古畫，高殿懸孤灯。","五月山雨熱，三峰火云蒸。","側闻樵人言，深谷猶積冰。","久願尋此山，至今嗟未能。","謫官忽东走，王程苦相仍。","欲去戀雙樹，何由窮一乘。","月輪吐山郭，夜色空清澄。"]', '诗', 'shi', '', NULL, '出關經華嶽寺訪法華雲公 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5057de82-fb98-474d-9b78-e76138f6ff59', '春半與羣公同遊元處士別業', '春半與羣公同游元处士別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["郭南處士宅，門外羅羣峰。","勝概忽相引，春華今正濃。","山廚竹裏爨，野碓藤間舂。","對酒雲數片，捲簾花萬重。","巖泉嗟到晚，州縣欲歸慵。","草色帶朝雨，灘聲兼夜鐘。","愛茲清俗慮，何事老塵容。","況有林下約，轉懷方外蹤。"]', '["郭南处士宅，门外羅羣峰。","勝概忽相引，春华今正濃。","山廚竹裏爨，野碓藤间舂。","对酒云數片，捲簾花万重。","巖泉嗟到晚，州縣欲归慵。","草色带朝雨，灘声兼夜鐘。","愛茲清俗慮，何事老塵容。","況有林下約，轉懷方外蹤。"]', '诗', 'shi', '', NULL, '春半與羣公同遊元處士別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da22ce8d-121e-4d5d-b2d4-7b4684b19bdd', '陪羣公龍岡寺泛舟', '陪羣公龙岡寺泛舟', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["漢水天一色，寺樓波底看。","鐘鳴長空夕，月出孤舟寒。","映酒見山火，隔簾聞夜灘。","紫鱗掣芳餌，紅燭然金盤。","良友興正愜，勝遊情未闌。","此中堪倒載，須盡主人歡。"]', '["漢水天一色，寺楼波底看。","鐘鳴长空夕，月出孤舟寒。","映酒见山火，隔簾闻夜灘。","紫鱗掣芳餌，紅燭然金盤。","良友兴正愜，勝游情未闌。","此中堪倒載，須尽主人歡。"]', '诗', 'shi', '', NULL, '陪羣公龍岡寺泛舟 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26328360-9008-44f2-8c81-8cfd2097f669', '終南山雙峰草堂作', '終南山雙峰草堂作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["斂跡歸山田，息心謝時輩。","晝還草堂臥，但與雙峰對。","興來恣佳遊，事愜符勝槩。","著書高牕下，日夕見城內。","曩爲世人誤，遂負平生愛。","久與林壑辭，及來松杉大。","偶茲近精廬，屢得名僧會。","有時逐樵漁，盡日不冠帶。","崖口上新月，石門破蒼靄。","色向羣木深，光搖一潭碎。","緬懷鄭生谷，頗憶嚴子瀨。","勝事猶可追，斯人邈千載。"]', '["斂跡归山田，息心謝时輩。","晝還草堂臥，但與雙峰对。","兴来恣佳游，事愜符勝槩。","著书高牕下，日夕见城內。","曩爲世人誤，遂負平生愛。","久與林壑辞，及来松杉大。","偶茲近精廬，屢得名僧會。","有时逐樵漁，尽日不冠带。","崖口上新月，石门破蒼靄。","色向羣木深，光搖一潭碎。","緬懷鄭生谷，頗憶嚴子瀨。","勝事猶可追，斯人邈千載。"]', '诗', 'shi', '', NULL, '終南山雙峰草堂作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84bfdc76-9061-4af1-990b-617bca9bd33f', '左僕射相國冀公東齋幽居', '左僕射相国冀公东斋幽居', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["丞相百僚長，兩朝居此官。","成功雲雷際，翊聖天地安。","不矜南宮貴，祗向東山看。","宅占鳳城勝，牕中雲嶺寬。","午時松軒夕，六月藤齋寒。","玉珮罥女蘿，金印耀牡丹。","山蟬上衣桁，野鼠緣藥盤。","有時披道書，竟日不著冠。","幸得趨省闈，常欣在門闌。","何當復持衡，短翮期風[摶]。"]', '["丞相百僚长，兩朝居此官。","成功云雷際，翊聖天地安。","不矜南宮貴，祗向东山看。","宅占鳳城勝，牕中云嶺寬。","午时松軒夕，六月藤斋寒。","玉珮罥女蘿，金印耀牡丹。","山蟬上衣桁，野鼠緣藥盤。","有时披道书，竟日不著冠。","幸得趨省闈，常欣在门闌。","何當复持衡，短翮期风[摶]。"]', '诗', 'shi', '', NULL, '左僕射相國冀公東齋幽居 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc8561fc-e31a-4601-a247-988488ca72be', '過緱山王處士黑石谷隱居', '過緱山王处士黑石谷隐居', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["舊居緱山下，偏識緱山雲。","處士久不還，見雲如見君。","別來逾十秋，兵馬日紛紛。","青谿開戰場，黑谷屯行軍。","遂令巢由輩，遠逐麋鹿羣。","獨有南澗水，潺湲如昔聞。"]', '["旧居緱山下，偏識緱山云。","处士久不還，见云如见君。","別来逾十秋，兵马日紛紛。","青谿开戰場，黑谷屯行軍。","遂令巢由輩，远逐麋鹿羣。","独有南澗水，潺湲如昔闻。"]', '诗', 'shi', '', NULL, '過緱山王處士黑石谷隱居 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0786fae3-fe55-4095-b9f9-28675422adce', '緱山西峰草堂作', '緱山西峰草堂作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["結廬對中嶽，青翠常在門。","遂耽水木興，盡作漁樵言。","頃來闕章句，但欲閒心魂。","日色隱空谷，蟬聲喧暮村。","曩聞道士語，偶見清淨源。","隱几閱吹葉，乘秋眺歸根。","獨遊念求仲，開徑招王孫。","片雨下南澗，孤峰出東原。","棲遲慮益澹，脫略道彌敦。","野靄晴拂枕，客帆遙入軒。","尚平今何在，此意誰與論。","佇立雲去盡，蒼蒼月開園。"]', '["結廬对中嶽，青翠常在门。","遂耽水木兴，尽作漁樵言。","頃来闕章句，但欲閒心魂。","日色隐空谷，蟬声喧暮村。","曩闻道士語，偶见清淨源。","隐几閱吹葉，乘秋眺归根。","独游念求仲，开徑招王孫。","片雨下南澗，孤峰出东原。","棲遲慮益澹，脫略道彌敦。","野靄晴拂枕，客帆遙入軒。","尚平今何在，此意誰與論。","佇立云去尽，蒼蒼月开园。"]', '诗', 'shi', '', NULL, '緱山西峰草堂作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48e2508f-1adb-4fdc-a9c3-af8b164d6c38', '觀楚國寺璋上人寫一切經院南有曲池深竹', '观楚国寺璋上人寫一切經院南有曲池深竹', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["璋公不出院，羣木閉深居。","誓寫一切經，欲向萬卷餘。","揮毫散林鵲，研墨警池魚。","音翻四句偈，字譯五天書。","鳴鐘竹陰晚，汲水桐花初。","雨氣潤衣鉢，香煙泛庭除。","此地日清淨，諸天應未如。","不知將錫杖，早晚躡空虛。"]', '["璋公不出院，羣木閉深居。","誓寫一切經，欲向万卷餘。","揮毫散林鵲，研墨警池鱼。","音翻四句偈，字譯五天书。","鳴鐘竹陰晚，汲水桐花初。","雨氣潤衣鉢，香煙泛庭除。","此地日清淨，諸天應未如。","不知將錫杖，早晚躡空虛。"]', '诗', 'shi', '', NULL, '觀楚國寺璋上人寫一切經院南有曲池深竹 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd8be159-308b-4ee0-a3b8-84a9a15dbdc3', '尋鞏縣南李處士別業', '尋鞏縣南李处士別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["先生近南郭，茅屋臨東川。","桑葉隱村戶，蘆花映釣船。","有時著書暇，盡日牕中眠。","且喜閭井近，灌田同一泉。"]', '["先生近南郭，茅屋臨东川。","桑葉隐村戶，蘆花映釣船。","有时著书暇，尽日牕中眠。","且喜閭井近，灌田同一泉。"]', '诗', 'shi', '', NULL, '尋鞏縣南李處士別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('302a3538-2ba1-42ce-be55-f8a3920d4e27', '聞崔十二侍御灌口夜宿報恩寺', '闻崔十二侍御灌口夜宿報恩寺', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["聞君尋野寺，便宿支公房。","溪月冷深殿，江雲擁迴廊。","然燈松林靜，煮茗柴門香。","勝事不可接，相思幽興長。"]', '["闻君尋野寺，便宿支公房。","溪月冷深殿，江云擁迴廊。","然灯松林静，煮茗柴门香。","勝事不可接，相思幽兴长。"]', '诗', 'shi', '', NULL, '聞崔十二侍御灌口夜宿報恩寺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3695034-cb53-40cb-9e95-96368130d979', '自潘陵尖還少室居止秋夕憑眺', '自潘陵尖還少室居止秋夕憑眺', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["草堂近少室，夜靜聞風松。","月出潘陵尖，照見十六峰。","九月山葉赤，谿雲淡秋容。","火點伊陽村，煙深嵩角鐘。","尚子不可見，蔣生難再逢。","勝愜只自知，佳趣爲誰濃。","昨詣山僧期，上到天壇東。","向下望雷雨，雲間見回龍。","夕與人羣疎，轉愛丘壑中。","心澹水木會，興幽魚鳥通。","稀微了自釋，出處乃不同。","況本無宦情，誓將依道風。"]', '["草堂近少室，夜静闻风松。","月出潘陵尖，照见十六峰。","九月山葉赤，谿云淡秋容。","火点伊陽村，煙深嵩角鐘。","尚子不可见，蔣生难再逢。","勝愜只自知，佳趣爲誰濃。","昨詣山僧期，上到天壇东。","向下望雷雨，云间见回龙。","夕與人羣疎，轉愛丘壑中。","心澹水木會，兴幽鱼鸟通。","稀微了自釋，出处乃不同。","況本無宦情，誓將依道风。"]', '诗', 'shi', '', NULL, '自潘陵尖還少室居止秋夕憑眺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aeae05e-ce10-44b3-9aac-ff880bd1077b', '南池夜宿思王屋青蘿舊齋', '南池夜宿思王屋青蘿旧斋', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["池上臥煩暑，不櫛復不巾。","有時清風來，自謂羲皇人。","天晴雲歸盡，雨洗月色新。","公事常不閑，道書日生塵。","早年家王屋，五別青蘿春。","安得還舊山，東谿垂釣綸。"]', '["池上臥煩暑，不櫛复不巾。","有时清风来，自謂羲皇人。","天晴云归尽，雨洗月色新。","公事常不闲，道书日生塵。","早年家王屋，五別青蘿春。","安得還旧山，东谿垂釣綸。"]', '诗', 'shi', '', NULL, '南池夜宿思王屋青蘿舊齋 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f676e64-f490-4806-b4bb-86bd304415e0', '過王判官西津所居', '過王判官西津所居', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["勝迹不在遠，愛君池館幽。","素懷巖中諾，宛得塵外遊。","何必到清谿，忽來見滄洲。","潛移岷山石，暗引巴江流。","樹密晝先夜，竹深夏已秋。","沙鳥上筆牀，谿花篲簾鈎。","夫子賤簪冕，注心向林丘。","落日出公堂，垂綸乘釣舟。","賦詩憶楚老，載酒隨江鷗。","翛然一傲吏，獨在西津頭。"]', '["勝迹不在远，愛君池館幽。","素懷巖中諾，宛得塵外游。","何必到清谿，忽来见滄洲。","潛移岷山石，暗引巴江流。","樹密晝先夜，竹深夏已秋。","沙鸟上笔牀，谿花篲簾鈎。","夫子賤簪冕，注心向林丘。","落日出公堂，垂綸乘釣舟。","賦诗憶楚老，載酒隨江鷗。","翛然一傲吏，独在西津头。"]', '诗', 'shi', '', NULL, '過王判官西津所居 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('528e55a1-c0c1-4091-8667-3bd46c15a26c', '因假歸白閣西草堂', '因假归白閣西草堂', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["雷聲傍太白，雨在八九峰。","東望白閣雲，半入紫閣松。","勝概紛滿目，衡門趣彌濃。","幸有數畝田，得延二仲蹤。","早聞達士語，偶與心相通。","誤徇一微官，還山愧塵容。","釣竿不復把，野碓無人舂。","惆悵飛鳥盡，南谿聞夜鐘。"]', '["雷声傍太白，雨在八九峰。","东望白閣云，半入紫閣松。","勝概紛满目，衡门趣彌濃。","幸有數畝田，得延二仲蹤。","早闻達士語，偶與心相通。","誤徇一微官，還山愧塵容。","釣竿不复把，野碓無人舂。","惆悵飞鸟尽，南谿闻夜鐘。"]', '诗', 'shi', '', NULL, '因假歸白閣西草堂 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd0a584f-0999-46d9-9ca3-ce92955e138b', '題華嚴寺瓌公禪房', '題华嚴寺瓌公禪房', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["寺南幾十峰，峰翠晴可掬。","朝從老僧飯，昨日崖口宿。","錫杖倚枯松，繩牀暎深竹。","東谿草堂路，來往行自熟。","生事在雲山，誰能復羈束。"]', '["寺南幾十峰，峰翠晴可掬。","朝從老僧飯，昨日崖口宿。","錫杖倚枯松，繩牀暎深竹。","东谿草堂路，来往行自熟。","生事在云山，誰能复羈束。"]', '诗', 'shi', '', NULL, '題華嚴寺瓌公禪房 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16a97993-feed-4148-bf82-dacf5fcb71de', '東歸留題太常徐卿草堂', '东归留題太常徐卿草堂', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["不謝古名將，吾知徐太常。","年纔三十餘，勇冠西南方。","頃曾策匹馬，獨出持兩鎗。","虜騎無數來，見君不敢當。","漢將小衛霍，蜀將凌關張。","卿月益清澄，將星轉光芒。","復居少城北，遙對岷山陽。","車馬日盈門，賓客常滿堂。","曲池蔭高樹，小徑穿叢篁。","江鳥飛入簾，山雲來到牀。","題詩芭蕉滑，對酒椶花香。","諸將射獵時，君在翰墨場。","聖主賞勳業，邊城最輝光。","與我情綢繆，相知久芬芳。","忽作萬里別，東歸三峽長。"]', '["不謝古名將，吾知徐太常。","年纔三十餘，勇冠西南方。","頃曾策匹马，独出持兩鎗。","虜騎無數来，见君不敢當。","漢將小衛霍，蜀將凌关張。","卿月益清澄，將星轉光芒。","复居少城北，遙对岷山陽。","车马日盈门，賓客常满堂。","曲池蔭高樹，小徑穿叢篁。","江鸟飞入簾，山云来到牀。","題诗芭蕉滑，对酒椶花香。","諸將射獵时，君在翰墨場。","聖主賞勳業，邊城最輝光。","與我情綢繆，相知久芬芳。","忽作万里別，东归三峽长。"]', '诗', 'shi', '', NULL, '東歸留題太常徐卿草堂 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb6a8afe-08b7-4182-9867-e8e3eea4d51b', '太一石鱉崖口潭舊廬招王學士', '太一石鱉崖口潭旧廬招王学士', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["驟雨鳴淅瀝，颼飀谿谷寒。","碧潭千餘尺，下見蛟龍蟠。","石門吞衆流，絕岸呀層巒。","幽趣倏萬變，奇觀非一端。","偶逐干祿徒，十年皆小官。","抱板尋舊圃，弊廬臨迅湍。","君子滿清朝，小人思挂冠。","釀酒漉松子，引泉通竹竿。","何必濯滄浪，不能釣嚴灘。","此地可遺老，勸君來考槃。"]', '["驟雨鳴淅瀝，颼飀谿谷寒。","碧潭千餘尺，下见蛟龙蟠。","石门吞衆流，絕岸呀層巒。","幽趣倏万变，奇观非一端。","偶逐干祿徒，十年皆小官。","抱板尋旧圃，弊廬臨迅湍。","君子满清朝，小人思挂冠。","釀酒漉松子，引泉通竹竿。","何必濯滄浪，不能釣嚴灘。","此地可遺老，勸君来考槃。"]', '诗', 'shi', '', NULL, '太一石鱉崖口潭舊廬招王學士 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('384fd5e8-ba72-4a81-8516-32234490db05', '林臥', '林臥', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["偶得魚鳥趣，復茲水木涼。","遠峰帶雨色，落日搖川光。","臼中西山藥，袖裏淮南方。","唯愛隱几時，獨遊無何鄉。"]', '["偶得鱼鸟趣，复茲水木涼。","远峰带雨色，落日搖川光。","臼中西山藥，袖裏淮南方。","唯愛隐几时，独游無何乡。"]', '诗', 'shi', '', NULL, '林臥 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec37bf03-b0e4-46b7-afd1-af9988d9f07a', '驪姬墓下作', '驪姬墓下作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["驪姬北原上，閉骨已千秋。","澮水日東注，惡名終不流。","獻公恣耽惑，視子如仇讎。","此事成蔓草，我來逢古丘。","蛾眉山月苦，蟬鬢野雲愁。","欲弔二公子，橫汾無輕舟。"]', '["驪姬北原上，閉骨已千秋。","澮水日东注，惡名終不流。","獻公恣耽惑，視子如仇讎。","此事成蔓草，我来逢古丘。","蛾眉山月苦，蟬鬢野云愁。","欲弔二公子，橫汾無轻舟。"]', '诗', 'shi', '', NULL, '驪姬墓下作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2d792d4-690b-483a-9dc9-6c1bc308d479', '東歸晚次潼關懷古', '东归晚次潼关懷古', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["暮春別鄉樹，晚景低津樓。","伯夷在首陽，欲往無輕舟。","遂登關城望，下見洪河流。","自從巨靈開，流血千萬秋。","行行潘生賦，赫赫曹公謀。","川上多往事，淒涼滿空洲。"]', '["暮春別乡樹，晚景低津楼。","伯夷在首陽，欲往無轻舟。","遂登关城望，下见洪河流。","自從巨靈开，流血千万秋。","行行潘生賦，赫赫曹公謀。","川上多往事，淒涼满空洲。"]', '诗', 'shi', '', NULL, '東歸晚次潼關懷古 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a489626c-115e-42b8-9a2e-e955ccd2032b', '楚夕旅泊古興', '楚夕旅泊古兴', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["獨鶴唳江月，孤帆凌楚雲。","秋風冷蕭瑟，蘆荻花紛紛。","忽思湘川老，欲訪雲中君。","騏驎息悲鳴，愁見豺虎羣。"]', '["独鹤唳江月，孤帆凌楚云。","秋风冷蕭瑟，蘆荻花紛紛。","忽思湘川老，欲訪云中君。","騏驎息悲鳴，愁见豺虎羣。"]', '诗', 'shi', '', NULL, '楚夕旅泊古興 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab0af607-4847-45d7-b0b0-3da583eda41a', '先主武侯廟', '先主武侯廟', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["先主與武侯，相逢雲雷際。","感通君臣分，義激魚水契。","遺廟空蕭然，英靈貫千歲。"]', '["先主與武侯，相逢云雷際。","感通君臣分，義激鱼水契。","遺廟空蕭然，英靈貫千歲。"]', '诗', 'shi', '', NULL, '先主武侯廟 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca469b5-a92f-408f-a8ab-0815e898e216', '文公講堂', '文公講堂', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["文公不可見，空使蜀人傳。","講席何時散，高臺豈復全。","豐碑文字滅，冥漠不知年。"]', '["文公不可见，空使蜀人傳。","講席何时散，高台豈复全。","豐碑文字滅，冥漠不知年。"]', '诗', 'shi', '', NULL, '文公講堂 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56fc6e91-1a4d-4e55-948e-3e919ccf85b0', '楊雄草玄臺', '楊雄草玄台', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["吾悲子雲居，寂寞人已去。","娟娟西江月，猶照草玄處。","精怪喜無人，睢盱藏老樹。"]', '["吾悲子云居，寂寞人已去。","娟娟西江月，猶照草玄处。","精怪喜無人，睢盱藏老樹。"]', '诗', 'shi', '', NULL, '楊雄草玄臺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38bed822-d6be-4418-b1a0-81bbeed3ef36', '司馬相如琴臺', '司马相如琴台', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["相如琴臺古，人去臺亦空。","臺上寒蕭條，至今多悲風。","荒臺漢時月，色與舊時同。"]', '["相如琴台古，人去台亦空。","台上寒蕭條，至今多悲风。","荒台漢时月，色與旧时同。"]', '诗', 'shi', '', NULL, '司馬相如琴臺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9af61cdf-9699-4c8e-b8f7-711a73567e9f', '嚴君平卜肆', '嚴君平卜肆', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["君平曾賣卜，卜肆蕪已久。","至今杖頭錢，時時地上有。","不知支機石，還在人間否。"]', '["君平曾賣卜，卜肆蕪已久。","至今杖头錢，时时地上有。","不知支機石，還在人间否。"]', '诗', 'shi', '', NULL, '嚴君平卜肆 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2188df7-af62-4e04-8368-cc74b5aba800', '張儀樓', '張儀楼', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["傳是秦時樓，巍巍至今在。","樓南兩江水，千古長不改。","曾聞昔時人，歲月不相待。"]', '["傳是秦时楼，巍巍至今在。","楼南兩江水，千古长不改。","曾闻昔时人，歲月不相待。"]', '诗', 'shi', '', NULL, '張儀樓 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b23d9f-8c1f-4ec3-8812-0287a2508498', '昇仙橋', '昇仙橋', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["長橋題柱去，猶是未達時。","及乘駟馬車，却從橋上歸。","名共東流水，滔滔無盡期。"]', '["长橋題柱去，猶是未達时。","及乘駟马车，却從橋上归。","名共东流水，滔滔無尽期。"]', '诗', 'shi', '', NULL, '昇仙橋 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce27c3e3-309b-4319-9550-e9dc125e8478', '萬里橋', '万里橋', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["成都與維揚，相去萬里地。","滄江東流疾，帆去如鳥翅。","楚客過此橋，東看盡垂淚。"]', '["成都與維揚，相去万里地。","滄江东流疾，帆去如鸟翅。","楚客過此橋，东看尽垂泪。"]', '诗', 'shi', '', NULL, '萬里橋 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac0c59d6-2aac-4c7a-964b-461d8ad87a21', '石犀', '石犀', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["江水初蕩潏，蜀人幾爲魚。","向無爾石犀，安得有邑居。","始知李太守，伯禹亦不如。"]', '["江水初蕩潏，蜀人幾爲鱼。","向無爾石犀，安得有邑居。","始知李太守，伯禹亦不如。"]', '诗', 'shi', '', NULL, '石犀 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf8593b-c22e-47e4-ad29-9c5744343b90', '龍女祠', '龙女祠', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["龍女何處來，來時乘風雨。","祠堂青林下，宛宛如相語。","蜀人競祈恩，捧酒仍擊鼓。"]', '["龙女何处来，来时乘风雨。","祠堂青林下，宛宛如相語。","蜀人競祈恩，捧酒仍擊鼓。"]', '诗', 'shi', '', NULL, '龍女祠 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c6fc61f-438f-4d0d-81a3-cfa15a53e955', '使交河郡郡在火山脚其地苦熱無雨雪獻封大夫', '使交河郡郡在火山脚其地苦熱無雨雪獻封大夫', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["奉使按胡俗，平明發輪臺。","暮投交河城，火山赤崔巍。","九月尚流汗，炎風吹沙埃。","何事陰陽工，不遣雨雪來。","吾君方憂邊，分閫資大才。","昨者新破胡，安西兵馬回。","鐵關控天涯，萬里何遼哉。","煙塵不敢飛，白草空皚皚。","軍中日無事，醉舞傾金罍。","漢代李將軍，微功合可咍。"]', '["奉使按胡俗，平明發輪台。","暮投交河城，火山赤崔巍。","九月尚流汗，炎风吹沙埃。","何事陰陽工，不遣雨雪来。","吾君方憂邊，分閫資大才。","昨者新破胡，安西兵马回。","鐵关控天涯，万里何遼哉。","煙塵不敢飞，白草空皚皚。","軍中日無事，醉舞傾金罍。","漢代李將軍，微功合可咍。"]', '诗', 'shi', '', NULL, '使交河郡郡在火山脚其地苦熱無雨雪獻封大夫 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc87acf3-d083-44a0-9e44-eb849eefe780', '與鮮于庶子自梓州成都少尹自襃城同行至利州道中作', '與鲜于庶子自梓州成都少尹自襃城同行至利州道中作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["剖竹向西蜀，岷峨眇天涯。","空深北闕戀，豈憚南路賒。","前日登七盤，曠然見三巴。","漢水出嶓冢，梁山控襃斜。","棧道籠迅湍，行人貫層崖。","巖傾劣通馬，石窄難容車。","深林怯魑魅，洞穴防龍蛇。","水種新插秧，山田正燒畬。","夜猿嘯山雨，曙鳥鳴江花。","過午方始飯，經時旋及瓜。","數公各遊宦，千里皆辭家。","言笑忘羈旅，還如在京華。"]', '["剖竹向西蜀，岷峨眇天涯。","空深北闕戀，豈憚南路賒。","前日登七盤，曠然见三巴。","漢水出嶓冢，梁山控襃斜。","棧道籠迅湍，行人貫層崖。","巖傾劣通马，石窄难容车。","深林怯魑魅，洞穴防龙蛇。","水種新插秧，山田正燒畬。","夜猿嘯山雨，曙鸟鳴江花。","過午方始飯，經时旋及瓜。","數公各游宦，千里皆辞家。","言笑忘羈旅，還如在京华。"]', '诗', 'shi', '', NULL, '與鮮于庶子自梓州成都少尹自襃城同行至利州道中作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c5306db-2975-4d15-967f-43cf50d6522a', '下外江舟懷終南舊居', '下外江舟懷終南旧居', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["杉冷曉猿悲，楚客心欲絕。","孤舟巴山雨，萬里陰臺月。","水宿已淹時，蘆花白如雪。","顏容老難赬，把鏡悲鬢髮。","早年好金丹，方士傳口訣。","敝廬終南下，久與真侶別。","道書誰更開，藥竈煙遂滅。","頃來壓塵網，安得有仙骨。","巖壑歸去來，公卿是何物。"]', '["杉冷晓猿悲，楚客心欲絕。","孤舟巴山雨，万里陰台月。","水宿已淹时，蘆花白如雪。","顏容老难赬，把镜悲鬢髮。","早年好金丹，方士傳口訣。","敝廬終南下，久與真侶別。","道书誰更开，藥竈煙遂滅。","頃来壓塵網，安得有仙骨。","巖壑归去来，公卿是何物。"]', '诗', 'shi', '', NULL, '下外江舟懷終南舊居 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14e8178c-20eb-4e34-bf06-0eb43c0e8e23', '安西館中思長安', '安西館中思长安', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["家在日出處，朝來起東風。","風從帝鄉來，不異家信通。","絕域地欲盡，孤城天遂窮。","彌年但走馬，終日隨飄蓬。","寂寞不得意，辛勤方在公。","胡塵淨古塞，兵氣屯邊空。","鄉路眇天外，歸期如夢中。","遙憑長房術，爲縮天山東。"]', '["家在日出处，朝来起东风。","风從帝乡来，不異家信通。","絕域地欲尽，孤城天遂窮。","彌年但走马，終日隨飄蓬。","寂寞不得意，辛勤方在公。","胡塵淨古塞，兵氣屯邊空。","乡路眇天外，归期如梦中。","遙憑长房術，爲縮天山东。"]', '诗', 'shi', '', NULL, '安西館中思長安 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55e59dfb-2711-40cf-8e15-dbf3b40c322c', '暮秋山行', '暮秋山行', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["疲馬臥長坂，夕陽下通津。","山風吹空林，颯颯如有人。","蒼旻霽涼雨，石路無飛塵。","千念集暮節，萬籟悲蕭晨。","鶗鴂昨夜鳴，蕙草色已陳。","況在遠行客，自然多苦辛。"]', '["疲马臥长坂，夕陽下通津。","山风吹空林，颯颯如有人。","蒼旻霽涼雨，石路無飞塵。","千念集暮節，万籟悲蕭晨。","鶗鴂昨夜鳴，蕙草色已陳。","況在远行客，自然多苦辛。"]', '诗', 'shi', '', NULL, '暮秋山行 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82cf958f-aba0-41ba-a01e-fee89c0c5d2b', '赴犍爲經龍閣道', '赴犍爲經龙閣道', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["側徑轉青壁，危梁透滄波。","汗流出鳥道，膽碎窺龍渦。","驟雨暗谿口，歸雲網松蘿。","屢聞羌兒笛，厭聽巴童歌。","江路險復永，夢魂愁更多。","聖朝幸典郡，不敢嫌岷峨。"]', '["側徑轉青壁，危梁透滄波。","汗流出鸟道，膽碎窺龙渦。","驟雨暗谿口，归云網松蘿。","屢闻羌兒笛，厭听巴童歌。","江路險复永，梦魂愁更多。","聖朝幸典郡，不敢嫌岷峨。"]', '诗', 'shi', '', NULL, '赴犍爲經龍閣道 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e51f3b2f-cd90-4b0c-985a-a681d5aab870', '江上阻風雨', '江上阻风雨', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["江上風欲來，泊舟未能發。","氣昏雨已過，突兀山復出。","積浪成高丘，盤渦爲嵌窟。","雲低岸花掩，水漲灘草沒。","老樹蛇蛻皮，崩崖龍退骨。","平生抱忠信，艱險殊可忽。"]', '["江上风欲来，泊舟未能發。","氣昏雨已過，突兀山复出。","積浪成高丘，盤渦爲嵌窟。","云低岸花掩，水漲灘草沒。","老樹蛇蛻皮，崩崖龙退骨。","平生抱忠信，艱險殊可忽。"]', '诗', 'shi', '', NULL, '江上阻風雨 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3392e070-4cd4-4e46-b1f5-7d7c9b4cdfdf', '經火山', '經火山', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["火山今始見，突兀蒲昌東。","赤焰燒虜雲，炎氛蒸塞空。","不知陰陽炭，何獨然此中。","我來嚴冬時，山下多炎風。","人馬盡汗流，孰知造化功。"]', '["火山今始见，突兀蒲昌东。","赤焰燒虜云，炎氛蒸塞空。","不知陰陽炭，何独然此中。","我来嚴冬时，山下多炎风。","人马尽汗流，孰知造化功。"]', '诗', 'shi', '', NULL, '經火山 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('173fb26f-eb55-4a3b-bbc9-b8f672c7baa4', '題鐵門關樓', '題鐵门关楼', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["鐵關天西涯，極目少行客。","關門一小吏，終日對石壁。","橋跨千仞危，路盤兩崖窄。","試登西樓望，一望頭欲白。"]', '["鐵关天西涯，極目少行客。","关门一小吏，終日对石壁。","橋跨千仞危，路盤兩崖窄。","試登西楼望，一望头欲白。"]', '诗', 'shi', '', NULL, '題鐵門關樓 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f6ecab4-18c7-4258-8534-da1b858ca1ba', '早上五盤嶺', '早上五盤嶺', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["平旦驅駟馬，曠然出五盤。","江迴兩崖鬬，日隱羣峰攢。","蒼翠煙景曙，森沈雲樹寒。","松疎露孤驛，花密藏迴灘。","棧道谿雨滑，畬田原草乾。","此行爲知己，不覺蜀道難。"]', '["平旦驱駟马，曠然出五盤。","江迴兩崖鬬，日隐羣峰攢。","蒼翠煙景曙，森沈云樹寒。","松疎露孤驛，花密藏迴灘。","棧道谿雨滑，畬田原草乾。","此行爲知己，不覺蜀道难。"]', '诗', 'shi', '', NULL, '早上五盤嶺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92a22684-9363-45c9-b869-2fbee3986059', '峨眉東脚臨江聽猿懷二室舊廬', '峨眉东脚臨江听猿懷二室旧廬', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["峨眉煙翠新，昨夜秋雨洗。","分明峰頭樹，倒插秋江底。","久別二室間，圖他五斗米。","哀猿不可聽，北客欲流涕。"]', '["峨眉煙翠新，昨夜秋雨洗。","分明峰头樹，倒插秋江底。","久別二室间，圖他五斗米。","哀猿不可听，北客欲流涕。"]', '诗', 'shi', '', NULL, '峨眉東脚臨江聽猿懷二室舊廬 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fae37351-bc37-48df-8f77-3014e4477b6f', '東歸發犍爲至泥谿舟中作', '东归發犍爲至泥谿舟中作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["前日解侯印，泛舟歸山東。","平旦發犍爲，逍遙信回風。","七月江水大，滄波漲秋空。","復有峨眉僧，誦經在舟中。","夜泊防虎豹，朝行逼魚龍。","一道鳴迅湍，兩邊走連峰。","猿拂岸花落，鳥啼簷樹重。","煙靄吳楚連，泝沿湖海通。","憶昨在西掖，復曾入南宮。","日出朝聖人，端笏陪羣公。","不意今棄置，何由豁心胸。","吾當海上去，且學乘桴翁。"]', '["前日解侯印，泛舟归山东。","平旦發犍爲，逍遙信回风。","七月江水大，滄波漲秋空。","复有峨眉僧，誦經在舟中。","夜泊防虎豹，朝行逼鱼龙。","一道鳴迅湍，兩邊走連峰。","猿拂岸花落，鸟啼簷樹重。","煙靄吳楚連，泝沿湖海通。","憶昨在西掖，复曾入南宮。","日出朝聖人，端笏陪羣公。","不意今棄置，何由豁心胸。","吾當海上去，且学乘桴翁。"]', '诗', 'shi', '', NULL, '東歸發犍爲至泥谿舟中作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87b7f79f-5b83-460c-9c0b-c224d2db37c6', '阻戎瀘間羣盜', '阻戎瀘间羣盜', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["南州林莽深，亡命聚其間。","殺人無昏曉，屍積填江灣。","餓虎銜髑髏，飢烏啄心肝。","腥裛灘草死，血流江水殷。","夜雨風蕭蕭，鬼哭連楚山。","三江行人絕，萬里無征船。","唯有白鳥飛，空見秋月園。","罷官自南蜀，假道來茲川。","瞻望陽臺雲，惆悵不敢前。","帝鄉北近日，瀘口南連蠻。","何當遇長房，縮地到京關。","願得隨琴高，騎魚向雲煙。","明主每憂人，節使恆在邊。","兵革方禦寇，爾惡胡不悛。","吾竊悲爾徒，此生安得全。"]', '["南州林莽深，亡命聚其间。","殺人無昏晓，屍積填江灣。","餓虎銜髑髏，飢烏啄心肝。","腥裛灘草死，血流江水殷。","夜雨风蕭蕭，鬼哭連楚山。","三江行人絕，万里無征船。","唯有白鸟飞，空见秋月园。","罷官自南蜀，假道来茲川。","瞻望陽台云，惆悵不敢前。","帝乡北近日，瀘口南連蠻。","何當遇长房，縮地到京关。","願得隨琴高，騎鱼向云煙。","明主每憂人，節使恆在邊。","兵革方禦寇，爾惡胡不悛。","吾竊悲爾徒，此生安得全。"]', '诗', 'shi', '', NULL, '阻戎瀘間羣盜 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c977192-db7d-4ad1-af6a-ef4defb1d1fa', '郡齋閑坐', '郡斋闲坐', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["負郭無良田，屈身狥微祿。","平生好疎曠，何事就羈束。","幸曾趨丹墀，數得侍黃屋。","故人盡榮寵，誰念此幽獨。","州縣非宿心，雲山欣滿目。","頃來廢章句，終日披案牘。","佐郡竟何成，自悲徒碌碌。"]', '["負郭無良田，屈身狥微祿。","平生好疎曠，何事就羈束。","幸曾趨丹墀，數得侍黄屋。","故人尽榮寵，誰念此幽独。","州縣非宿心，云山欣满目。","頃来廢章句，終日披案牘。","佐郡竟何成，自悲徒碌碌。"]', '诗', 'shi', '', NULL, '郡齋閑坐 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e87e6eca-3a0d-46f8-869e-ce53a6bc8876', '衙郡守還', '衙郡守還', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["世事何反覆，一身難可料。","頭白翻折腰，還家私自笑。","所嗟無產業，妻子嫌不調。","五斗米留人，東谿憶垂釣。"]', '["世事何反覆，一身难可料。","头白翻折腰，還家私自笑。","所嗟無產業，妻子嫌不調。","五斗米留人，东谿憶垂釣。"]', '诗', 'shi', '', NULL, '衙郡守還 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24316fda-83a7-4bfe-bb3b-ea652f727463', '行軍詩二首 一', '行軍诗二首 一', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["吾竊悲此生，四十幸未老。","一朝逢世亂，終日不自保。","胡兵奪長安，宮殿生野草。","傷心五陵樹，不見二京道。","我皇在行軍，兵馬日浩浩。","胡雛尚未滅，諸將懇征討。","昨聞咸陽敗，殺戮淨如掃。","積屍若丘山，流血漲豐鎬。","干戈礙鄉國，豺虎滿城堡。","村落皆無人，蕭條空桑棗。","儒生有長策，無處豁懷抱。","塊然傷時人，舉首哭蒼昊。"]', '["吾竊悲此生，四十幸未老。","一朝逢世亂，終日不自保。","胡兵奪长安，宮殿生野草。","傷心五陵樹，不见二京道。","我皇在行軍，兵马日浩浩。","胡雛尚未滅，諸將懇征討。","昨闻咸陽敗，殺戮淨如掃。","積屍若丘山，流血漲豐鎬。","干戈礙乡国，豺虎满城堡。","村落皆無人，蕭條空桑棗。","儒生有长策，無处豁懷抱。","塊然傷时人，舉首哭蒼昊。"]', '诗', 'shi', '', NULL, '行軍詩二首 一 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5de0ee9b-7d0b-478a-8781-4f719d822dcb', '行軍詩二首 二', '行軍诗二首 二', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["早知逢世亂，少小謾讀書。","悔不學彎弓，向東射狂胡。","偶從諫官列，謬向丹墀趨。","未能匡吾君，虛作一丈夫。","撫劒傷世路，哀歌泣良圖。","功業今已遲，覽鏡悲白鬚。","平生抱忠義，不敢私微軀。"]', '["早知逢世亂，少小謾读书。","悔不学彎弓，向东射狂胡。","偶從諫官列，謬向丹墀趨。","未能匡吾君，虛作一丈夫。","撫劒傷世路，哀歌泣良圖。","功業今已遲，覽镜悲白鬚。","平生抱忠義，不敢私微軀。"]', '诗', 'shi', '', NULL, '行軍詩二首 二 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28203ee8-58e9-4486-bc10-4ff96f93eb01', '秋夕聽羅山人彈三峽流泉', '秋夕听羅山人彈三峽流泉', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["皤皤岷山老，抱琴鬢蒼然。","衫袖拂玉徽，爲彈三峽泉。","此曲彈未半，高堂如空山。","石林何[颼飀]，忽在窗戶間。","繞指弄嗚咽，青絲激潺湲。","演漾怨楚雲，虛徐韻秋煙。","疑兼陽臺雨，似雜巫山猿。","幽引鬼神聽，淨令耳目便。","楚客腸欲斷，湘妃淚斑斑。","誰裁青桐枝，絚以朱絲絃。","能含古人曲，遞與今人傳。","知音難再逢，惜君方年老。","曲終月已落，惆[悵]東齋眠。"]', '["皤皤岷山老，抱琴鬢蒼然。","衫袖拂玉徽，爲彈三峽泉。","此曲彈未半，高堂如空山。","石林何[颼飀]，忽在窗戶间。","繞指弄嗚咽，青絲激潺湲。","演漾怨楚云，虛徐韻秋煙。","疑兼陽台雨，似杂巫山猿。","幽引鬼神听，淨令耳目便。","楚客腸欲斷，湘妃泪斑斑。","誰裁青桐枝，絚以朱絲絃。","能含古人曲，遞與今人傳。","知音难再逢，惜君方年老。","曲終月已落，惆[悵]东斋眠。"]', '诗', 'shi', '', NULL, '秋夕聽羅山人彈三峽流泉 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4f4c725-be05-446d-a355-4d5ba576a907', '尹相公京兆府中棠樹降甘露詩', '尹相公京兆府中棠樹降甘露诗', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["相國尹京兆，政成人不欺。","甘露降府庭，上天表無私。","非無他人家，豈少羣木枝。","被茲甘棠樹，美掩召伯詩。","團團甜如[蜜]，皛皛凝若脂。","千柯玉光碎，萬葉珠顆垂。","崑崙何時來，慶雲相逐飛。","魏宮銅盤貯，漢帝金掌持。","王澤布人和，精心動靈祇。","君臣日同德，禎瑞方潛施。","何術令大臣，感通能及茲。","忽驚政化理，暗與神物期。","却笑趙張輩，徒稱今古稀。","爲君天下酒，麴糵將用時。"]', '["相国尹京兆，政成人不欺。","甘露降府庭，上天表無私。","非無他人家，豈少羣木枝。","被茲甘棠樹，美掩召伯诗。","團團甜如[蜜]，皛皛凝若脂。","千柯玉光碎，万葉珠顆垂。","崑崙何时来，慶云相逐飞。","魏宮銅盤貯，漢帝金掌持。","王澤布人和，精心动靈祇。","君臣日同德，禎瑞方潛施。","何術令大臣，感通能及茲。","忽驚政化理，暗與神物期。","却笑趙張輩，徒稱今古稀。","爲君天下酒，麴糵將用时。"]', '诗', 'shi', '', NULL, '尹相公京兆府中棠樹降甘露詩 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855d1e36-5a93-4f76-b6bc-e349130a9276', '劉相公中書江山畫障', '劉相公中书江山畫障', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["相府徵墨妙，揮毫天地窮。","始知丹青筆，能奪造化功。","瀟湘在簾間，廬壑橫座中。","忽疑鳳凰池，暗與江海通。","粉白湖上雲，黛青天際峰。","晝日恆見月，孤帆如有風。","巖花不飛落，澗草無春冬。","擔錫香鑪緇，釣魚滄浪翁。","如何平津意，尚想塵外蹤。","富貴心獨輕，山林興彌濃。","喧幽趣頗異，出處事不同。","請君爲蒼生，未可追赤松。"]', '["相府徵墨妙，揮毫天地窮。","始知丹青笔，能奪造化功。","瀟湘在簾间，廬壑橫座中。","忽疑鳳凰池，暗與江海通。","粉白湖上云，黛青天際峰。","晝日恆见月，孤帆如有风。","巖花不飞落，澗草無春冬。","擔錫香鑪緇，釣鱼滄浪翁。","如何平津意，尚想塵外蹤。","富貴心独轻，山林兴彌濃。","喧幽趣頗異，出处事不同。","請君爲蒼生，未可追赤松。"]', '诗', 'shi', '', NULL, '劉相公中書江山畫障 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4cf8ffd-04a4-46bd-9e43-e873cf37f361', '精衛', '精衛', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["負劒出北門，乘桴適東溟。","一鳥海上飛，云是帝女靈。","玉顏溺水死，精衛空爲名。","怨積徒有志，力微竟不成。","西山木石盡，巨壑何時平。"]', '["負劒出北门，乘桴適东溟。","一鸟海上飞，云是帝女靈。","玉顏溺水死，精衛空爲名。","怨積徒有志，力微竟不成。","西山木石尽，巨壑何时平。"]', '诗', 'shi', '', NULL, '精衛 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5005e6f9-54b2-48ee-a17e-93a1ee74fc49', '石上藤', '石上藤', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["石上生孤藤，弱蔓依石長。","不逢高枝引，未得凌空上。","何處堪託身，爲君長萬丈。"]', '["石上生孤藤，弱蔓依石长。","不逢高枝引，未得凌空上。","何处堪託身，爲君长万丈。"]', '诗', 'shi', '', NULL, '石上藤 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1134b996-462c-450f-a34c-656487d68bb7', '臨河客舍呈狄明府兄留題縣南樓', '臨河客舍呈狄明府兄留題縣南楼', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["黎陽城南雪正飛，黎陽渡頭人未歸。","河邊酒家堪寄宿，主人小女能縫衣。","故人高臥黎陽縣，一別三年不相見。","邑中雨雪偏着時，隔河東郡人遙羨。","鄴都唯見古時丘，漳水還如舊日流。","城上望鄉應不見，朝來好是嬾登樓。"]', '["黎陽城南雪正飞，黎陽渡头人未归。","河邊酒家堪寄宿，主人小女能縫衣。","故人高臥黎陽縣，一別三年不相见。","邑中雨雪偏着时，隔河东郡人遙羨。","鄴都唯见古时丘，漳水還如旧日流。","城上望乡應不见，朝来好是嬾登楼。"]', '诗', 'shi', '', NULL, '臨河客舍呈狄明府兄留題縣南樓 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65cbc848-38e4-46f6-aba6-226de39a3a3c', '客舍悲秋有懷兩省舊遊呈幕中諸公', '客舍悲秋有懷兩省旧游呈幕中諸公', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["三度爲郎便白頭，一從出守五經秋。","莫言聖主長不用，其那蒼生應未休。","人間歲月如流水，客舍秋風今又起。","不知心事向誰論，江上蟬鳴空滿耳。"]', '["三度爲郎便白头，一從出守五經秋。","莫言聖主长不用，其那蒼生應未休。","人间歲月如流水，客舍秋风今又起。","不知心事向誰論，江上蟬鳴空满耳。"]', '诗', 'shi', '', NULL, '客舍悲秋有懷兩省舊遊呈幕中諸公 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('294bc7b2-b4f8-4a53-be17-a40ded4afd1a', '白雪歌送武判官歸京', '白雪歌送武判官归京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["北風捲地白草折，胡天八月即飛雪。","忽然一夜春風來，千樹萬樹梨花開。","散入珠簾濕羅幕，狐裘不煖錦衾薄。","將軍角弓不得控，都護鐵衣冷難着。","瀚海闌干百丈冰，愁雲黲淡萬里凝。","中軍置酒飲歸客，胡琴琵琶與羌笛。","紛紛暮雪下轅門，風掣紅旗凍不翻。","輪臺東門送君去，去時雪滿天山路。","山迴路轉不見君，雪上空留馬行處。"]', '["北风捲地白草折，胡天八月即飞雪。","忽然一夜春风来，千樹万樹梨花开。","散入珠簾濕羅幕，狐裘不煖錦衾薄。","將軍角弓不得控，都護鐵衣冷难着。","瀚海闌干百丈冰，愁云黲淡万里凝。","中軍置酒饮归客，胡琴琵琶與羌笛。","紛紛暮雪下轅门，风掣紅旗凍不翻。","輪台东门送君去，去时雪满天山路。","山迴路轉不见君，雪上空留马行处。"]', '诗', 'shi', '', NULL, '白雪歌送武判官歸京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('760788a0-b091-414b-bf9f-291cec928701', '熱海行送崔侍御還京', '熱海行送崔侍御還京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["側聞陰山胡兒語，西頭熱海水如煮。","海上衆鳥不敢飛，中有鯉魚長且肥。","岸傍青草常不歇，空中白雪遙旋滅。","蒸沙爍石然虜雲，沸浪炎波煎漢月。","陰火潛燒天地鑪，何事偏烘西一隅。","勢吞月窟侵太白，氣連赤坂通單于。","送君一醉天山郭，正見夕陽海邊落。","柏臺霜威寒逼人，熱海炎氣爲之薄。"]', '["側闻陰山胡兒語，西头熱海水如煮。","海上衆鸟不敢飞，中有鯉鱼长且肥。","岸傍青草常不歇，空中白雪遙旋滅。","蒸沙爍石然虜云，沸浪炎波煎漢月。","陰火潛燒天地鑪，何事偏烘西一隅。","勢吞月窟侵太白，氣連赤坂通單于。","送君一醉天山郭，正见夕陽海邊落。","柏台霜威寒逼人，熱海炎氣爲之薄。"]', '诗', 'shi', '', NULL, '熱海行送崔侍御還京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d129dc0f-cec9-4073-bb89-cb9312564d9d', '輪臺歌奉送封大夫出師西征', '輪台歌奉送封大夫出師西征', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["輪臺城頭夜吹角，輪臺城北旄頭落。","羽書昨夜過渠黎，單于已在金山西。","戍樓西望煙塵黑，漢兵屯在輪臺北。","上將擁旄西出征，平明吹笛大軍行。","四邊伐鼓雪海湧，三軍大呼陰山動。","虜塞兵氣連雲屯，戰場白骨纏草根。","劒河風急雪片闊，沙口石凍馬蹄脫。","亞相勤王甘苦辛，誓將報主靜邊塵。","古來青史誰不見，今見功名勝古人。"]', '["輪台城头夜吹角，輪台城北旄头落。","羽书昨夜過渠黎，單于已在金山西。","戍楼西望煙塵黑，漢兵屯在輪台北。","上將擁旄西出征，平明吹笛大軍行。","四邊伐鼓雪海湧，三軍大呼陰山动。","虜塞兵氣連云屯，戰場白骨纏草根。","劒河风急雪片闊，沙口石凍马蹄脫。","亞相勤王甘苦辛，誓將報主静邊塵。","古来青史誰不见，今见功名勝古人。"]', '诗', 'shi', '', NULL, '輪臺歌奉送封大夫出師西征 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93639a7d-ea8a-451b-8cd7-5531e9ccf86c', '敷水歌送竇漸入京', '敷水歌送竇漸入京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["羅敷昔時秦氏女，千載無人空處所。","昔時流水至今流，萬事皆逐東流去。","此水東流無盡期，水聲還似舊來時。","岸花仍自羞紅臉，隄柳猶能學翠眉。","春去秋來不相待，水中月色長不改。","羅敷養蠶空耳聞，使君五馬今何在？","九月霜天水正寒，故人西去度征鞍。","水底鯉魚幸無數，願君別後垂尺素。"]', '["羅敷昔时秦氏女，千載無人空处所。","昔时流水至今流，万事皆逐东流去。","此水东流無尽期，水声還似旧来时。","岸花仍自羞紅臉，隄柳猶能学翠眉。","春去秋来不相待，水中月色长不改。","羅敷養蠶空耳闻，使君五马今何在？","九月霜天水正寒，故人西去度征鞍。","水底鯉鱼幸無數，願君別後垂尺素。"]', '诗', 'shi', '', NULL, '敷水歌送竇漸入京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e5e359-1e63-48bd-ae4d-9239aad418fa', '天山雪歌送蕭治歸京', '天山雪歌送蕭治归京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["天山有雪常不開，千峰萬嶺雪崔嵬。","北風夜捲赤亭口，一夜天山雪更厚。","能兼漢月照銀山，復逐胡風過鐵關。","交河城邊飛鳥絕，輪臺路上馬蹄滑。","晻靄寒氛萬里凝，闌干陰崖千丈冰。","將軍狐裘臥不暖，都護寶刀凍欲斷。","正是天山雪下時，送君走馬歸京師。","雪中何以贈君別，惟有青青松樹枝。"]', '["天山有雪常不开，千峰万嶺雪崔嵬。","北风夜捲赤亭口，一夜天山雪更厚。","能兼漢月照銀山，复逐胡风過鐵关。","交河城邊飞鸟絕，輪台路上马蹄滑。","晻靄寒氛万里凝，闌干陰崖千丈冰。","將軍狐裘臥不暖，都護寶刀凍欲斷。","正是天山雪下时，送君走马归京師。","雪中何以贈君別，惟有青青松樹枝。"]', '诗', 'shi', '', NULL, '天山雪歌送蕭治歸京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76009aa6-c0bb-43e5-9ee6-fa163bc901d8', '火山雲歌送別', '火山云歌送別', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["火山突兀赤亭口，火山五月火雲厚。","火雲滿山凝未開，飛鳥千里不敢來。","平明乍逐胡風斷，薄暮渾隨塞雨回。","繚繞斜吞鐵關樹，氛氳半掩交河戍。","迢迢征路火山東，山上孤雲隨馬去。"]', '["火山突兀赤亭口，火山五月火云厚。","火云满山凝未开，飞鸟千里不敢来。","平明乍逐胡风斷，薄暮渾隨塞雨回。","繚繞斜吞鐵关樹，氛氳半掩交河戍。","迢迢征路火山东，山上孤云隨马去。"]', '诗', 'shi', '', NULL, '火山雲歌送別 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('881c4241-c0a0-4c31-a0ba-2f87b4290c44', '青門歌送東臺張判官', '青门歌送东台張判官', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["青門金鎖平旦開，城頭日出使車回。","青門柳枝正堪折，路傍一日幾人別。","東出青門路不窮，驛樓官樹灞陵東。","花撲征衣看似繡，雲隨去馬色疑驄。","胡姬酒壚日未午，絲繩玉缸酒如乳。","灞頭落花沒馬蹄，昨夜微雨花成泥。","黃鸝翅濕飛轉低，關東尺書醉嬾題。","須臾望君不可見，揚鞭飛鞚疾如箭。","借問使乎何時來，莫作東飛伯勞西飛燕。"]', '["青门金鎖平旦开，城头日出使车回。","青门柳枝正堪折，路傍一日幾人別。","东出青门路不窮，驛楼官樹灞陵东。","花撲征衣看似繡，云隨去马色疑驄。","胡姬酒壚日未午，絲繩玉缸酒如乳。","灞头落花沒马蹄，昨夜微雨花成泥。","黄鸝翅濕飞轉低，关东尺书醉嬾題。","須臾望君不可见，揚鞭飞鞚疾如箭。","借问使乎何时来，莫作东飞伯勞西飞燕。"]', '诗', 'shi', '', NULL, '青門歌送東臺張判官 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7233ba7b-301d-4ca8-bf61-928eac520dfc', '梁園歌送河南王說判官', '梁园歌送河南王说判官', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["君不見梁孝王脩竹園，頹牆隱轔勢仍存。","嬌娥曼臉成草蔓，羅帷珠簾空竹根。","大梁一旦人代改，秋月春風不相待。","池中幾度雁新來，洲上千年鶴應在。","梁園二月梨花飛，却似梁王雪下時。","當時置酒延枚叟，肯料平臺狐兔走。","萬事翻覆如浮雲，昔人空在今人口。","單父古來稱宓生，祗今爲政有吾兄。","輶軒若過梁園道，應傍琴臺聞政聲。"]', '["君不见梁孝王脩竹园，頹牆隐轔勢仍存。","嬌娥曼臉成草蔓，羅帷珠簾空竹根。","大梁一旦人代改，秋月春风不相待。","池中幾度雁新来，洲上千年鹤應在。","梁园二月梨花飞，却似梁王雪下时。","當时置酒延枚叟，肯料平台狐兔走。","万事翻覆如浮云，昔人空在今人口。","單父古来稱宓生，祗今爲政有吾兄。","輶軒若過梁园道，應傍琴台闻政声。"]', '诗', 'shi', '', NULL, '梁園歌送河南王說判官 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e021d7-ea56-4341-947c-8fd024018e1c', '走馬川行奉送出師西征', '走马川行奉送出師西征', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["君不見走馬川行雪海邊，平沙莽莽黃入天。","輪臺九月風夜吼，一川碎石大如斗，隨風滿地石亂走。","匈奴草黃馬正肥，金山西見煙塵飛。","漢家大將西出師，將軍金甲夜不脫。","半夜軍行戈相撥，風頭如刀面如割。","馬毛帶雪汗氣蒸，五花連錢旋作冰。","幕中草檄硯水凝，虜騎聞之應膽懾。","料知短兵不敢接，車師西門佇獻捷。"]', '["君不见走马川行雪海邊，平沙莽莽黄入天。","輪台九月风夜吼，一川碎石大如斗，隨风满地石亂走。","匈奴草黄马正肥，金山西见煙塵飞。","漢家大將西出師，將軍金甲夜不脫。","半夜軍行戈相撥，风头如刀面如割。","马毛带雪汗氣蒸，五花連錢旋作冰。","幕中草檄硯水凝，虜騎闻之應膽懾。","料知短兵不敢接，车師西门佇獻捷。"]', '诗', 'shi', '', NULL, '走馬川行奉送出師西征 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad7e0050-66f9-4366-97d1-1dc1f69286bd', '函谷關歌送劉評事使關西', '函谷关歌送劉評事使关西', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["君不見函谷關，崩城毀壁至今在。","樹根草蔓遮古道，空谷千年長不改。","寂寞無人空舊山，聖朝無外不須關。","白馬公孫何處去，青牛老人更不還。","蒼苔白骨空滿地，月與古時長相似。","野花不省見行人，山鳥何曾識關吏。","故人方乘使者車，吾知郭丹却不如。","請君時憶關外客，行到關西多致書。"]', '["君不见函谷关，崩城毀壁至今在。","樹根草蔓遮古道，空谷千年长不改。","寂寞無人空旧山，聖朝無外不須关。","白马公孫何处去，青牛老人更不還。","蒼苔白骨空满地，月與古时长相似。","野花不省见行人，山鸟何曾識关吏。","故人方乘使者车，吾知郭丹却不如。","請君时憶关外客，行到关西多致书。"]', '诗', 'shi', '', NULL, '函谷關歌送劉評事使關西 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d784999c-efd0-4bf8-a06e-4c931be04042', '胡笳歌送顏真卿使赴河隴', '胡笳歌送顏真卿使赴河隴', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["君不聞胡笳聲最悲，紫髯綠眼胡人吹。","吹之一曲猶未了，愁殺樓蘭征戍兒。","涼秋八月蕭關道，北風吹斷天山草。","崑崙山南月欲斜，胡人向月吹胡笳。","胡笳怨兮將送君，秦山遙望隴山雲。","邊城夜夜多愁夢，向月胡笳誰喜聞。"]', '["君不闻胡笳声最悲，紫髯綠眼胡人吹。","吹之一曲猶未了，愁殺楼蘭征戍兒。","涼秋八月蕭关道，北风吹斷天山草。","崑崙山南月欲斜，胡人向月吹胡笳。","胡笳怨兮將送君，秦山遙望隴山云。","邊城夜夜多愁梦，向月胡笳誰喜闻。"]', '诗', 'shi', '', NULL, '胡笳歌送顏真卿使赴河隴 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3998e24-86de-480a-b799-38a302164f24', '秦箏歌送外甥蕭正歸京', '秦箏歌送外甥蕭正归京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["汝不聞秦箏聲最苦，五色纏弦十三柱。","怨調慢聲如欲語，一曲未終日移午。","紅亭水木不知暑，忽彈黃鐘和白紵。","清風颯來雲不去，聞之酒醒淚如雨。","汝歸秦兮彈秦聲，秦聲悲兮聊送汝。"]', '["汝不闻秦箏声最苦，五色纏弦十三柱。","怨調慢声如欲語，一曲未終日移午。","紅亭水木不知暑，忽彈黄鐘和白紵。","清风颯来云不去，闻之酒醒泪如雨。","汝归秦兮彈秦声，秦声悲兮聊送汝。"]', '诗', 'shi', '', NULL, '秦箏歌送外甥蕭正歸京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9e9a370-25c2-4030-8b4f-2f7abc5e353a', '與獨孤漸道別長句兼呈嚴八侍御', '與独孤漸道別长句兼呈嚴八侍御', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["輪臺客舍春草滿，潁陽歸客腸堪斷。","窮荒絕漠鳥不飛，萬磧千山夢猶嬾。","憐君白面一書生，讀書千卷未成名。","五侯貴門脚不到，數畝山田身自耕。","興來浪跡無遠近，及至辭家憶鄉信。","無事垂鞭信馬頭，西南幾欲窮天盡。","[奉]使三年獨未歸，邊頭詞客舊來稀。","借問君來得幾日，到家不覺換春衣。","高齋清晝卷帷幕，紗帽接䍦慵不着。","中酒朝眠日色高，彈棋夜半燈花落。","冰片高堆金錯盤，滿堂凜凜五月寒。","桂林蒲萄新吐蔓，武城刺蜜未可餐。","軍中置酒夜撾鼓，錦筵紅燭月未午。","花門將軍善胡歌，葉河蕃王能漢語。","知爾園林壓渭濱，夫人堂上泣羅帬。","魚龍川北盤谿雨，鳥鼠山西洮水雲。","臺中嚴公於我厚，別後新詩滿人口。","自憐棄置天西頭，因君爲問相思否。"]', '["輪台客舍春草满，潁陽归客腸堪斷。","窮荒絕漠鸟不飞，万磧千山梦猶嬾。","怜君白面一书生，读书千卷未成名。","五侯貴门脚不到，數畝山田身自耕。","兴来浪跡無远近，及至辞家憶乡信。","無事垂鞭信马头，西南幾欲窮天尽。","[奉]使三年独未归，邊头词客旧来稀。","借问君来得幾日，到家不覺換春衣。","高斋清晝卷帷幕，紗帽接䍦慵不着。","中酒朝眠日色高，彈棋夜半灯花落。","冰片高堆金錯盤，满堂凜凜五月寒。","桂林蒲萄新吐蔓，武城刺蜜未可餐。","軍中置酒夜撾鼓，錦筵紅燭月未午。","花门將軍善胡歌，葉河蕃王能漢語。","知爾园林壓渭濱，夫人堂上泣羅帬。","鱼龙川北盤谿雨，鸟鼠山西洮水云。","台中嚴公於我厚，別後新诗满人口。","自怜棄置天西头，因君爲问相思否。"]', '诗', 'shi', '', NULL, '與獨孤漸道別長句兼呈嚴八侍御 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d04b4104-01c2-4de2-b5fb-f659a6586bc4', '送費子歸武昌', '送費子归武昌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["漢陽歸客悲秋草，旅舍葉飛愁不掃。","秋來倍憶武昌魚，夢着只在巴陵道。","曾隨上將過祁連，離家十年恆在邊。","劒鋒可惜虛用盡，馬蹄無事今已穿。","知君開館常愛客，樗蒱百金每一擲。","平生有錢將與人，江上故園空四壁。","吾觀費子毛骨奇，廣眉大口仍赤髭。","看君失路尚如此，人生貴賤那得知。","高秋八月歸南楚，東門一壺聊出祖。","路指鳳皇山北雲，衣沾鸚鵡洲邊雨。","勿歎蹉跎白髮新，應須守道勿羞貧。","男兒何必戀妻子，莫向江村老却人。"]', '["漢陽归客悲秋草，旅舍葉飞愁不掃。","秋来倍憶武昌鱼，梦着只在巴陵道。","曾隨上將過祁連，離家十年恆在邊。","劒鋒可惜虛用尽，马蹄無事今已穿。","知君开館常愛客，樗蒱百金每一擲。","平生有錢將與人，江上故园空四壁。","吾观費子毛骨奇，廣眉大口仍赤髭。","看君失路尚如此，人生貴賤那得知。","高秋八月归南楚，东门一壺聊出祖。","路指鳳皇山北云，衣沾鸚鵡洲邊雨。","勿歎蹉跎白髮新，應須守道勿羞貧。","男兒何必戀妻子，莫向江村老却人。"]', '诗', 'shi', '', NULL, '送費子歸武昌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d1a310-f9bf-43fc-af1e-38eb0762b0de', '送韓巽入都覲省便赴舉', '送韓巽入都覲省便赴舉', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["槐葉蒼蒼柳葉黃，秋高八月天欲霜。","青門百壺送韓侯，白雲千里連嵩丘。","北堂倚門望君憶，東歸扇枕後秋色。","洛陽才子能幾人，明年桂枝是君得。"]', '["槐葉蒼蒼柳葉黄，秋高八月天欲霜。","青门百壺送韓侯，白云千里連嵩丘。","北堂倚门望君憶，东归扇枕後秋色。","洛陽才子能幾人，明年桂枝是君得。"]', '诗', 'shi', '', NULL, '送韓巽入都覲省便赴舉 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd3df17-14f0-4fba-99a8-8ed70a83a1ad', '送李副使赴磧西官車', '送李副使赴磧西官车', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["火山六月應更熱，赤亭道口行人絕。","知君慣度祁連城，豈能愁見輪臺月。","脫鞍暫入酒家壚，送君萬里西擊胡。","功名祗向馬上取，真是英雄一丈夫。"]', '["火山六月應更熱，赤亭道口行人絕。","知君慣度祁連城，豈能愁见輪台月。","脫鞍暫入酒家壚，送君万里西擊胡。","功名祗向马上取，真是英雄一丈夫。"]', '诗', 'shi', '', NULL, '送李副使赴磧西官車 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('580e95b9-b4ec-4224-ab4d-1cc5484a1539', '涼州館中與諸判官夜集', '涼州館中與諸判官夜集', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["彎彎月出挂城頭，城頭月出照梁州。","涼州七里十萬家，胡人半解彈琵琶。","琵琶一曲腸堪斷，風蕭蕭兮夜漫漫。","河西幕中多故人，故人別來三五春。","花門樓前見秋草，豈能貧賤相看老。","一生大笑能幾迴，斗酒相逢須醉倒。"]', '["彎彎月出挂城头，城头月出照梁州。","涼州七里十万家，胡人半解彈琵琶。","琵琶一曲腸堪斷，风蕭蕭兮夜漫漫。","河西幕中多故人，故人別来三五春。","花门楼前见秋草，豈能貧賤相看老。","一生大笑能幾迴，斗酒相逢須醉倒。"]', '诗', 'shi', '', NULL, '涼州館中與諸判官夜集 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0623c5c6-0a91-4048-b267-cb6dd0d0e667', '酒泉太守席上醉後作', '酒泉太守席上醉後作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["琵琶長笛曲相和，羌兒胡雛齊唱歌。","渾炙犂牛烹野駝，交河美酒歸叵羅。","三更醉後軍中寢，無奈秦山歸夢何。"]', '["琵琶长笛曲相和，羌兒胡雛齊唱歌。","渾炙犂牛烹野駝，交河美酒归叵羅。","三更醉後軍中寢，無奈秦山归梦何。"]', '诗', 'shi', '', NULL, '酒泉太守席上醉後作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35fcaec7-8450-4f81-be58-ee56634cf1ba', '偃師東與韓樽同詣景雲暉上人即事', '偃師东與韓樽同詣景云暉上人即事', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["山陰老僧解楞伽，潁陽歸客遠相過。","煙深草濕昨夜雨，雨後秋風渡漕河。","空山終日塵事少，平郊遠見行人小。","尚書磧上黃昏鐘，別駕渡頭一歸鳥。"]', '["山陰老僧解楞伽，潁陽归客远相過。","煙深草濕昨夜雨，雨後秋风渡漕河。","空山終日塵事少，平郊远见行人小。","尚书磧上黄昏鐘，別駕渡头一归鸟。"]', '诗', 'shi', '', NULL, '偃師東與韓樽同詣景雲暉上人即事 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('189fc6a0-4f1c-425a-bedb-5e894a75b5d0', '醉題匡城周少府廳壁', '醉題匡城周少府廳壁', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["婦姑城南風雨秋，婦姑城中人獨愁。","愁雲遮却望鄉處，數日不上西南樓。","故人薄暮公事閑，玉壺美酒琥珀殷。","潁陽秋草今黃盡，醉臥君家猶未還。"]', '["婦姑城南风雨秋，婦姑城中人独愁。","愁云遮却望乡处，數日不上西南楼。","故人薄暮公事闲，玉壺美酒琥珀殷。","潁陽秋草今黄尽，醉臥君家猶未還。"]', '诗', 'shi', '', NULL, '醉題匡城周少府廳壁 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11d89263-29a6-4a47-838e-28f415c64cf0', '燉煌太守後庭歌', '燉煌太守後庭歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["燉煌太守才且賢，郡中無事高枕眠。","太守到來山出泉，黃砂磧裏人種田。","燉煌耆舊鬢皓然，願留太守更五年。","城頭月出星滿天，曲房置酒張錦筵。","美人紅妝色正鮮，側垂高髻插金鈿。","醉坐藏鉤紅燭前，不知鈎在若箇邊。","爲君手把珊瑚鞭，射得半段黃金錢，此中樂事亦已偏。"]', '["燉煌太守才且賢，郡中無事高枕眠。","太守到来山出泉，黄砂磧裏人種田。","燉煌耆旧鬢皓然，願留太守更五年。","城头月出星满天，曲房置酒張錦筵。","美人紅妝色正鲜，側垂高髻插金鈿。","醉坐藏鉤紅燭前，不知鈎在若箇邊。","爲君手把珊瑚鞭，射得半段黄金錢，此中乐事亦已偏。"]', '诗', 'shi', '', NULL, '燉煌太守後庭歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b4aa31f-6abb-4987-8b52-3d2cdd107287', '喜韓樽相過', '喜韓樽相過', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["三月灞陵春已老，故人相逢耐醉倒。","甕頭春酒黃花脂，祿米只充沽酒資。","長安城中足年少，獨共韓侯開口笑。","桃花點地紅斑斑，有酒留君且莫還。","與君兄弟日攜手，世上虛名好是閑。"]', '["三月灞陵春已老，故人相逢耐醉倒。","甕头春酒黄花脂，祿米只充沽酒資。","长安城中足年少，独共韓侯开口笑。","桃花点地紅斑斑，有酒留君且莫還。","與君兄弟日携手，世上虛名好是闲。"]', '诗', 'shi', '', NULL, '喜韓樽相過 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bc49eb1-cde3-4aba-a939-871e3d178484', '銀山磧西館', '銀山磧西館', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["銀山磧口風似箭，鐵門關西月如練。","雙雙愁淚沾馬毛，颯颯胡沙迸人面。","丈夫三十未富貴，安能終日守筆硯。"]', '["銀山磧口风似箭，鐵门关西月如練。","雙雙愁泪沾马毛，颯颯胡沙迸人面。","丈夫三十未富貴，安能終日守笔硯。"]', '诗', 'shi', '', NULL, '銀山磧西館 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dc6ff35-ae2b-4d66-bae4-04770eda11c1', '感遇', '感遇', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["五花驄馬七香車，云是平陽帝子家。","鳳皇城頭日欲斜，門前高樹鳴春鴉。","漢家魯元君不聞，今作城西一古墳。","昔來唯有秦王女，獨自吹蕭乘白雲。"]', '["五花驄马七香车，云是平陽帝子家。","鳳皇城头日欲斜，门前高樹鳴春鴉。","漢家魯元君不闻，今作城西一古墳。","昔来唯有秦王女，独自吹蕭乘白云。"]', '诗', 'shi', '', NULL, '感遇 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58f90338-5fad-40bc-9071-3f83658c46a0', '太白胡僧歌', '太白胡僧歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["聞有胡僧在太白，蘭若去天三百尺。","一持楞伽入中峰，世人難見但聞鐘。","牕邊錫杖解兩虎，牀下鉢盂藏一龍。","草衣不鍼復不線，兩耳垂肩眉覆面。","此僧年幾那得知，手種青松今十圍。","心將流水同清淨，身與浮雲無是非。","商山老人已曾識，願一見之何由得。","山中有僧人不知，城裏看山空黛色。"]', '["闻有胡僧在太白，蘭若去天三百尺。","一持楞伽入中峰，世人难见但闻鐘。","牕邊錫杖解兩虎，牀下鉢盂藏一龙。","草衣不鍼复不線，兩耳垂肩眉覆面。","此僧年幾那得知，手種青松今十圍。","心將流水同清淨，身與浮云無是非。","商山老人已曾識，願一见之何由得。","山中有僧人不知，城裏看山空黛色。"]', '诗', 'shi', '', NULL, '太白胡僧歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5dfd013-1975-4f54-a7ad-d94ee8073191', '衛節度赤驃馬歌', '衛節度赤驃马歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["君家赤驃畫不得，一團旋風桃花色。","紅纓紫鞚珊瑚鞭，玉鞍錦韉黃金勒。","請君鞲出看君騎，尾長窣地如紅絲。","自矜諸馬皆不及，却憶百金新買時。","香街紫陌鳳城內，滿城見者誰不愛。","揚鞭驟急白汗流，弄影行驕碧蹄碎。","紫髯胡雛金剪刀，平明剪出三鬉高。","櫪上看時獨意氣，衆中牽出偏雄豪。","騎將獵向南山口，城南孤兔不復有。","草頭一點疾如飛，卻使蒼鷹翻向後。","憶昨看君朝未央，鳴珂擁蓋滿路香。","始知邊將真富貴，可憐人馬相輝光。","男兒稱意得如此，駿馬長鳴北風起。","待君東去埽胡塵，爲君一日行千里。"]', '["君家赤驃畫不得，一團旋风桃花色。","紅纓紫鞚珊瑚鞭，玉鞍錦韉黄金勒。","請君鞲出看君騎，尾长窣地如紅絲。","自矜諸马皆不及，却憶百金新買时。","香街紫陌鳳城內，满城见者誰不愛。","揚鞭驟急白汗流，弄影行驕碧蹄碎。","紫髯胡雛金剪刀，平明剪出三鬉高。","櫪上看时独意氣，衆中牽出偏雄豪。","騎將獵向南山口，城南孤兔不复有。","草头一点疾如飞，卻使蒼鷹翻向後。","憶昨看君朝未央，鳴珂擁蓋满路香。","始知邊將真富貴，可怜人马相輝光。","男兒稱意得如此，駿马长鳴北风起。","待君东去埽胡塵，爲君一日行千里。"]', '诗', 'shi', '', NULL, '衛節度赤驃馬歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78bcf1fa-7303-4196-9911-49533efcfd88', '田使君美人舞如蓮花北鋋歌', '田使君美人舞如蓮花北鋋歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["美人舞如蓮花旋，世人有眼應未見。","高堂滿地紅氍毹，試舞一曲天下無。","此曲胡人傳入漢，諸客見之驚且歎。","慢臉嬌娥纖復穠，輕羅金縷花葱蘢。","回裾轉袖若飛雪，左鋋右鋋生旋風。","琵琶橫笛和未匝，花門山頭黃雲合。","忽作出塞入塞聲，白草胡沙寒颯颯。","翻身入破如有神，前見後見回回新。","始知諸曲不可比，采蓮落梅徒聒耳。","世人學舞祗是舞，恣態豈能得如此。"]', '["美人舞如蓮花旋，世人有眼應未见。","高堂满地紅氍毹，試舞一曲天下無。","此曲胡人傳入漢，諸客见之驚且歎。","慢臉嬌娥纖复穠，轻羅金縷花葱蘢。","回裾轉袖若飞雪，左鋋右鋋生旋风。","琵琶橫笛和未匝，花门山头黄云合。","忽作出塞入塞声，白草胡沙寒颯颯。","翻身入破如有神，前见後见回回新。","始知諸曲不可比，采蓮落梅徒聒耳。","世人学舞祗是舞，恣態豈能得如此。"]', '诗', 'shi', '', NULL, '田使君美人舞如蓮花北鋋歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5923c05c-cacd-4dae-b93f-baee6db3ba94', '裴將軍宅蘆管歌', '裴將軍宅蘆管歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["遼東九月蘆葉斷，遼東小兒采蘆管。","可憐新管清且悲，一曲風飄海頭滿。","海樹蕭索天雨霜，管聲寥亮月蒼蒼。","白狼河北堪愁恨，玄兔城南皆斷腸。","遼東將軍長安宅，美人蘆管會佳客。","弄調啾颼勝洞簫，發聲窈窕欺橫笛。","夜半高堂客未回，祗將蘆管送君杯。","巧能陌上驚楊柳，復向園中誤落梅。","諸客愛之聽未足，高捲珠簾列紅燭。","將軍醉舞不肯休，更使美人吹一曲。"]', '["遼东九月蘆葉斷，遼东小兒采蘆管。","可怜新管清且悲，一曲风飄海头满。","海樹蕭索天雨霜，管声寥亮月蒼蒼。","白狼河北堪愁恨，玄兔城南皆斷腸。","遼东將軍长安宅，美人蘆管會佳客。","弄調啾颼勝洞簫，發声窈窕欺橫笛。","夜半高堂客未回，祗將蘆管送君杯。","巧能陌上驚楊柳，复向园中誤落梅。","諸客愛之听未足，高捲珠簾列紅燭。","將軍醉舞不肯休，更使美人吹一曲。"]', '诗', 'shi', '', NULL, '裴將軍宅蘆管歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b15f3808-4d29-40cb-97f7-7465843ae7b0', '韋員外家花樹歌', '韋員外家花樹歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["今年花似去年好，去年人到今年老。","始知人老不如花，可惜落花君莫埽。","君家兄弟不可當，列卿御史尚書郎。","朝回花底恆會客，花撲玉缸春酒香。"]', '["今年花似去年好，去年人到今年老。","始知人老不如花，可惜落花君莫埽。","君家兄弟不可當，列卿御史尚书郎。","朝回花底恆會客，花撲玉缸春酒香。"]', '诗', 'shi', '', NULL, '韋員外家花樹歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('126694de-4b58-4ebd-9028-cd0633031927', '醉後戲與趙歌兒', '醉後戲與趙歌兒', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["秦州歌兒歌調苦，偏能立唱濮陽女。","座中醉客不得意，聞之一聲淚如雨。","向使逢着漢帝憐，董賢氣咽不能語。"]', '["秦州歌兒歌調苦，偏能立唱濮陽女。","座中醉客不得意，闻之一声泪如雨。","向使逢着漢帝怜，董賢氣咽不能語。"]', '诗', 'shi', '', NULL, '醉後戲與趙歌兒 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9baec5a9-b39b-41e6-8259-637d2cd3336c', '范公叢竹歌', '范公叢竹歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["世人見竹不解愛，知君種竹府城內。","此君託根幸得地，種來幾時聞已大。","盛暑翛翛叢色寒，閑宵槭槭葉聲乾。","能清案牘簾下見，宜對琴書窗外看。","爲君成陰將蔽日，迸笋穿堦踏還出。","守節偏凌御史霜，虛心願比郎官筆。","君莫愛南山松樹枝，竹色四時也不移。","寒天草木黃落盡，猶自青青君始知。"]', '["世人见竹不解愛，知君種竹府城內。","此君託根幸得地，種来幾时闻已大。","盛暑翛翛叢色寒，闲宵槭槭葉声乾。","能清案牘簾下见，宜对琴书窗外看。","爲君成陰將蔽日，迸笋穿堦踏還出。","守節偏凌御史霜，虛心願比郎官笔。","君莫愛南山松樹枝，竹色四时也不移。","寒天草木黄落尽，猶自青青君始知。"]', '诗', 'shi', '', NULL, '范公叢竹歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc7cf78b-a1fc-4c9b-8b2e-1cbb16916842', '玉門關蓋將軍歌', '玉门关蓋將軍歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["蓋將軍，真丈夫，行年三十執金吾，身長七尺頗有鬚。","玉門關城迥且孤，黃沙萬里白草枯。","南鄰犬戎北接胡，將軍到來備不虞。","五千甲兵膽力麤，軍中無事但歡娛。","暖屋繡簾紅地爐，織成壁衣花氍毹。","燈前侍婢瀉玉壺，金鐺亂點野酡酥。","紫紱金章左右趨，問着只是蒼頭奴。","美人一雙閑且都，朱脣翠眉映明矑。","清歌一曲世所無，今日喜聞鳳將雛。","可憐絕勝秦羅敷，使君五馬謾踟躕。","野草繡窠紫羅襦，紅牙縷馬對樗蒱。","玉盤纖手撒作盧，衆中誇道不曾輸。","櫪上昂昂皆駿駒，桃花叱撥價最殊。","騎將獵向城南隅，臘日射殺千年狐。","我來塞外按邊儲，爲君取醉酒剩沽。","醉爭酒盞相喧呼，忽憶咸陽舊酒徒。"]', '["蓋將軍，真丈夫，行年三十執金吾，身长七尺頗有鬚。","玉门关城迥且孤，黄沙万里白草枯。","南鄰犬戎北接胡，將軍到来備不虞。","五千甲兵膽力麤，軍中無事但歡娛。","暖屋繡簾紅地爐，织成壁衣花氍毹。","灯前侍婢瀉玉壺，金鐺亂点野酡酥。","紫紱金章左右趨，问着只是蒼头奴。","美人一雙闲且都，朱脣翠眉映明矑。","清歌一曲世所無，今日喜闻鳳將雛。","可怜絕勝秦羅敷，使君五马謾踟躕。","野草繡窠紫羅襦，紅牙縷马对樗蒱。","玉盤纖手撒作盧，衆中誇道不曾輸。","櫪上昂昂皆駿駒，桃花叱撥價最殊。","騎將獵向城南隅，臘日射殺千年狐。","我来塞外按邊儲，爲君取醉酒剩沽。","醉爭酒盞相喧呼，忽憶咸陽旧酒徒。"]', '诗', 'shi', '', NULL, '玉門關蓋將軍歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8379d844-617f-478f-afa4-64ff67f2929a', '贈酒泉韓太守', '贈酒泉韓太守', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["太守有能政，遙聞如古人。","俸錢盡供客，家計常清貧。","酒泉西望玉關道，千山萬磧皆白草。","辭君走馬歸長安，憶君倏忽令人老。"]', '["太守有能政，遙闻如古人。","俸錢尽供客，家計常清貧。","酒泉西望玉关道，千山万磧皆白草。","辞君走马归长安，憶君倏忽令人老。"]', '诗', 'shi', '', NULL, '贈酒泉韓太守 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd4f0e0b-9e65-435e-b46e-bde6466aaecd', '贈西嶽山人李岡', '贈西嶽山人李岡', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["君隱處，當一星，蓮花峰頭飯黃精，仙人掌上演丹經。","鳥可到，人莫攀，隱來十年不下山。","袖中短書誰爲達，華陰道士賣藥還。"]', '["君隐处，當一星，蓮花峰头飯黄精，仙人掌上演丹經。","鸟可到，人莫攀，隐来十年不下山。","袖中短书誰爲達，华陰道士賣藥還。"]', '诗', 'shi', '', NULL, '贈西嶽山人李岡 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ac853aa-b238-4769-a90d-5d9cb067b63c', '送張獻心充副使歸河西雜句', '送張獻心充副使归河西杂句', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["將門子弟君獨賢，一從受命常在邊。","未至三十已高位，腰間金印色赭然。","前日承恩白虎殿，歸來見者誰不羨。","篋中賜衣十重餘，案上軍書十二卷。","看君謀智若有神，愛君詞句皆清新。","澄湖萬頃深見底，清冰一片光照人。","雲中昨夜使星動，西門驛樓出相送。","玉瓶素蟻臘酒香，金鞭白馬紫遊韁。","花門南，燕支北，張掖城頭雲正黑，送君一去天外憶。"]', '["將门子弟君独賢，一從受命常在邊。","未至三十已高位，腰间金印色赭然。","前日承恩白虎殿，归来见者誰不羨。","篋中賜衣十重餘，案上軍书十二卷。","看君謀智若有神，愛君词句皆清新。","澄湖万頃深见底，清冰一片光照人。","云中昨夜使星动，西门驛楼出相送。","玉瓶素蟻臘酒香，金鞭白马紫游韁。","花门南，燕支北，張掖城头云正黑，送君一去天外憶。"]', '诗', 'shi', '', NULL, '送張獻心充副使歸河西雜句 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a60665-ddc0-4b05-99a2-393d5910852e', '送郭乂雜言', '送郭乂杂言', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["地上青草出，經冬今始歸。","博陵無近信，猶未換春衣。","憐汝不忍別，送汝上酒樓。","初行莫早發，且宿霸橋頭。","功名須及早，歲月莫虛擲。","早年已工詩，近日兼注易。","何時過東洛，早晚度盟津。","朝歌城邊柳嚲地，邯鄲道上花撲人。","去年四月初，我正在河朔。","曾上君家縣北樓，樓上分明見恆嶽。","中山明府待君來，須計行程及早回。","到家速覓長安使，待汝書封我自開。"]', '["地上青草出，經冬今始归。","博陵無近信，猶未換春衣。","怜汝不忍別，送汝上酒楼。","初行莫早發，且宿霸橋头。","功名須及早，歲月莫虛擲。","早年已工诗，近日兼注易。","何时過东洛，早晚度盟津。","朝歌城邊柳嚲地，邯鄲道上花撲人。","去年四月初，我正在河朔。","曾上君家縣北楼，楼上分明见恆嶽。","中山明府待君来，須計行程及早回。","到家速覓长安使，待汝书封我自开。"]', '诗', 'shi', '', NULL, '送郭乂雜言 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf44d412-33f8-475e-ba60-a95e321fb35e', '送魏升卿擢第歸東都因懷魏校書陸渾喬潭', '送魏升卿擢第归东都因懷魏校书陸渾喬潭', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["井上桐葉雨，灞亭卷秋風。","故人適戰勝，匹馬歸山東。","問君今年三十幾，能使香名滿人耳。","君不見三峰直上五千仞，見君文章亦如此。","如君兄弟天下稀，雄辭健筆皆若飛。","將軍金印嚲紫綬，御史鐵冠重繡衣。","喬生作尉別來久，因君爲問平安否。","魏侯校理復何如，前日人來不得書。","陸渾山下佳可賞，蓬閣閑時日應往。","自料青雲未有期，誰知白髮偏能長。","壚頭青絲白玉瓶，別時相顧酒如傾。","搖鞭舉袂忽不見，千樹萬樹空蟬鳴。"]', '["井上桐葉雨，灞亭卷秋风。","故人適戰勝，匹马归山东。","问君今年三十幾，能使香名满人耳。","君不见三峰直上五千仞，见君文章亦如此。","如君兄弟天下稀，雄辞健笔皆若飞。","將軍金印嚲紫綬，御史鐵冠重繡衣。","喬生作尉別来久，因君爲问平安否。","魏侯校理复何如，前日人来不得书。","陸渾山下佳可賞，蓬閣闲时日應往。","自料青云未有期，誰知白髮偏能长。","壚头青絲白玉瓶，別时相顧酒如傾。","搖鞭舉袂忽不见，千樹万樹空蟬鳴。"]', '诗', 'shi', '', NULL, '送魏升卿擢第歸東都因懷魏校書陸渾喬潭 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f054e33-b7bb-4334-b1fa-37a96ddb3ec0', '送魏四落第還鄉', '送魏四落第還乡', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["東歸不稱意，客舍戴勝鳴。","臘酒飲未盡，春衫縫已成。","長安柳枝春欲來，洛陽梨花在前開。","魏侯池館今尚在，猶有太師歌舞臺。","君家盛德豈徒然，時人注意在吾賢。","莫令別後無佳句，祗向壚頭空醉眠。"]', '["东归不稱意，客舍戴勝鳴。","臘酒饮未尽，春衫縫已成。","长安柳枝春欲来，洛陽梨花在前开。","魏侯池館今尚在，猶有太師歌舞台。","君家盛德豈徒然，时人注意在吾賢。","莫令別後無佳句，祗向壚头空醉眠。"]', '诗', 'shi', '', NULL, '送魏四落第還鄉 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f59863d1-e0b2-46a5-b431-4a5cf38a50fc', '送宇文南金放後歸太原寓居因呈太原郝主簿', '送宇文南金放後归太原寓居因呈太原郝主簿', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["歸去不得意，北京關路賒。","却投晉山老，愁見汾陽花。","翻作灞陵客，憐君丞相家。","夜眠旅舍雨，曉辭春城鴉。","送君繫馬青門口，胡姬壚頭勸君酒。","爲問太原賢主人，春來更有新詩否。"]', '["归去不得意，北京关路賒。","却投晉山老，愁见汾陽花。","翻作灞陵客，怜君丞相家。","夜眠旅舍雨，晓辞春城鴉。","送君繫马青门口，胡姬壚头勸君酒。","爲问太原賢主人，春来更有新诗否。"]', '诗', 'shi', '', NULL, '送宇文南金放後歸太原寓居因呈太原郝主簿 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1758b66b-ae92-4eb1-bbb3-fcfe3aa8dece', '西亭子送李司馬', '西亭子送李司马', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["高高亭子郡城西，直上千尺與雲齊。","盤崖緣壁試攀躋，羣山向下飛鳥低。","使君五馬天半嘶，絲繩玉壺爲君提。","坐來一望無端倪，紅花綠柳鶯亂啼。","千家萬井連迴谿，酒行未醉聞暮雞，點筆操紙爲君題。","爲君題，惜解攜，草萋萋，沒馬蹄。"]', '["高高亭子郡城西，直上千尺與云齊。","盤崖緣壁試攀躋，羣山向下飞鸟低。","使君五马天半嘶，絲繩玉壺爲君提。","坐来一望無端倪，紅花綠柳鶯亂啼。","千家万井連迴谿，酒行未醉闻暮雞，点笔操紙爲君題。","爲君題，惜解携，草萋萋，沒马蹄。"]', '诗', 'shi', '', NULL, '西亭子送李司馬 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71a414a4-8939-48fc-90f6-d18b9e4bac57', '漁父', '漁父', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["扁舟滄浪叟，心與滄浪清。","不自道鄉里，無人知姓名。","朝從灘上飯，暮向蘆中宿。","歌竟還復歌，手持一竿竹。","竿頭釣絲長丈餘，鼓栧乘流無定居。","世人那得識深意，此翁取適非取魚。"]', '["扁舟滄浪叟，心與滄浪清。","不自道乡里，無人知姓名。","朝從灘上飯，暮向蘆中宿。","歌竟還复歌，手持一竿竹。","竿头釣絲长丈餘，鼓栧乘流無定居。","世人那得識深意，此翁取適非取鱼。"]', '诗', 'shi', '', NULL, '漁父 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a1e9614-6afb-4c44-a30c-aaf3e9ead632', '登古鄴城', '登古鄴城', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["下馬登鄴城，城空復何見。","東風吹野火，暮入飛雲殿。","城隅南對望陵臺，漳水東流不復回。","武帝宮中人去盡，年年春色爲誰來。"]', '["下马登鄴城，城空复何见。","东风吹野火，暮入飞云殿。","城隅南对望陵台，漳水东流不复回。","武帝宮中人去尽，年年春色爲誰来。"]', '诗', 'shi', '', NULL, '登古鄴城 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d9969c4-babf-4e5c-bf13-0a31d533d69e', '邯鄲客舍歌', '邯鄲客舍歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["客從長安來，驅馬邯鄲道。","傷心叢臺下，一帶生蔓草。","客舍門臨漳水邊，垂楊下繫釣魚船。","邯鄲女兒夜沽酒，對客挑燈誇數錢。","酪酊醉時日正午，一曲狂歌壚上眠。"]', '["客從长安来，驱马邯鄲道。","傷心叢台下，一带生蔓草。","客舍门臨漳水邊，垂楊下繫釣鱼船。","邯鄲女兒夜沽酒，对客挑灯誇數錢。","酪酊醉时日正午，一曲狂歌壚上眠。"]', '诗', 'shi', '', NULL, '邯鄲客舍歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2582b61-2240-40ce-8268-54f96edfdfe6', '宿蒲關東店憶杜陵別業', '宿蒲关东店憶杜陵別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["關門鎖歸客，一夜夢還家。","月落河上曉，遙聞秦樹鴉。","長安二月歸正好，杜陵樹邊純是花。"]', '["关门鎖归客，一夜梦還家。","月落河上晓，遙闻秦樹鴉。","长安二月归正好，杜陵樹邊純是花。"]', '诗', 'shi', '', NULL, '宿蒲關東店憶杜陵別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('430a141d-b995-4db4-875e-47838b3123cb', '感遇', '感遇', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["北山有芳杜，靡靡花正發。","未及得采之，秋風忽吹殺。","君不見拂雲百丈青松柯，縱使秋風無奈何。","四時常作青黛色，可憐杜花不相識。"]', '["北山有芳杜，靡靡花正發。","未及得采之，秋风忽吹殺。","君不见拂云百丈青松柯，縱使秋风無奈何。","四时常作青黛色，可怜杜花不相識。"]', '诗', 'shi', '', NULL, '感遇 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a77b437-f3b1-486b-9fa8-909215ed7044', '優鉢羅花歌', '優鉢羅花歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["白山南，赤山北，其間有花人不識。","綠莖碧葉好顏色，葉六瓣，花九房，夜掩朝開多異香，何不生彼中國兮生西方？移根在庭，媚我公堂，恥與衆草之爲伍，何亭亭而獨芳？何不爲人之所賞兮？深山窮谷委嚴霜。","吾竊悲陽關道路長，曾不得獻于君王。"]', '["白山南，赤山北，其间有花人不識。","綠莖碧葉好顏色，葉六瓣，花九房，夜掩朝开多異香，何不生彼中国兮生西方？移根在庭，媚我公堂，恥與衆草之爲伍，何亭亭而独芳？何不爲人之所賞兮？深山窮谷委嚴霜。","吾竊悲陽关道路长，曾不得獻于君王。"]', '诗', 'shi', '', NULL, '優鉢羅花歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d2ee883-5b18-43aa-9826-81b372388bb8', '蜀葵花歌', '蜀葵花歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["昨日一花開，今日一花開。","今日花正好，昨日花已老。","始知人老不如花，可惜落花君莫埽。","人生不得長少年，莫惜牀頭沽酒錢。","請君有錢向酒家，君不見，蜀葵花。"]', '["昨日一花开，今日一花开。","今日花正好，昨日花已老。","始知人老不如花，可惜落花君莫埽。","人生不得长少年，莫惜牀头沽酒錢。","請君有錢向酒家，君不见，蜀葵花。"]', '诗', 'shi', '', NULL, '蜀葵花歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f53d562-10fa-4259-9030-9bcb93654af9', '題李士曹廳壁畫度雨雲歌', '題李士曹廳壁畫度雨云歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["似出棟梁裏，如和風雨飛。","掾曹有時不敢歸，謂言雨過濕人衣。"]', '["似出棟梁裏，如和风雨飞。","掾曹有时不敢归，謂言雨過濕人衣。"]', '诗', 'shi', '', NULL, '題李士曹廳壁畫度雨雲歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cad2c5a-ed2d-41c5-bd69-9d0a74ff8f43', '入蒲關先寄秦中故人', '入蒲关先寄秦中故人', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["秦山數點似青黛，渭上一條如白練。","京師故人不可見，寄將兩眼看飛燕。"]', '["秦山數点似青黛，渭上一條如白練。","京師故人不可见，寄將兩眼看飞燕。"]', '诗', 'shi', '', NULL, '入蒲關先寄秦中故人 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a673ef6a-62a4-4fa1-80c4-4054785395e2', '長門怨', '长门怨', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["君王嫌妾妬，閉妾在長門。","舞袖垂新寵，愁眉結舊恩。","綠錢侵履跡，紅粉濕啼痕。","羞被夭桃笑，看春獨不言。"]', '["君王嫌妾妬，閉妾在长门。","舞袖垂新寵，愁眉結旧恩。","綠錢侵履跡，紅粉濕啼痕。","羞被夭桃笑，看春独不言。"]', '诗', 'shi', '', NULL, '長門怨 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2779f710-4ab4-46cb-a2b6-1889752f26c2', '寄左省杜拾遺', '寄左省杜拾遺', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["聯步趨丹陛，分曹限紫微。","曉隨天仗入，暮惹御香歸。","白髮悲花落，青雲羨鳥飛。","聖朝無闕事，自覺諫書稀。"]', '["聯步趨丹陛，分曹限紫微。","晓隨天仗入，暮惹御香归。","白髮悲花落，青云羨鸟飞。","聖朝無闕事，自覺諫书稀。"]', '诗', 'shi', '', NULL, '寄左省杜拾遺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72b5a28-601c-4169-9a39-bc8a57171223', '歲暮磧外寄元撝', '歲暮磧外寄元撝', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["西風傳戍鼓，南望見前軍。","沙磧人愁月，山城犬吠雲。","別家逢逼歲，出塞獨離羣。","髮到陽關白，書今遠報君。"]', '["西风傳戍鼓，南望见前軍。","沙磧人愁月，山城犬吠云。","別家逢逼歲，出塞独離羣。","髮到陽关白，书今远報君。"]', '诗', 'shi', '', NULL, '歲暮磧外寄元撝 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0924c48-5e6f-44c9-a658-4d79e8053f76', '寄宇文判官', '寄宇文判官', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["西行殊未已，東望何時還。","終日風與雪，連天沙復山。","二年領公事，兩度過陽關。","相憶不可見，別來頭已斑。"]', '["西行殊未已，东望何时還。","終日风與雪，連天沙复山。","二年領公事，兩度過陽关。","相憶不可见，別来头已斑。"]', '诗', 'shi', '', NULL, '寄宇文判官 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2a142e8-d1c6-4d24-8b48-1a11b54c5823', '宿關西客舍寄東山嚴許二山人時天寶初七月初三日在內學見有高道舉徵', '宿关西客舍寄东山嚴許二山人时天寶初七月初三日在內学见有高道舉徵', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["雲送關西雨，風傳渭北秋。","孤燈然客夢，寒杵搗鄉愁。","灘上思嚴子，山中憶許由。","蒼生今有望，飛詔下林丘。"]', '["云送关西雨，风傳渭北秋。","孤灯然客梦，寒杵捣乡愁。","灘上思嚴子，山中憶許由。","蒼生今有望，飞詔下林丘。"]', '诗', 'shi', '', NULL, '宿關西客舍寄東山嚴許二山人時天寶初七月初三日在內學見有高道舉徵 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('836b5f1f-eb4a-4ea9-a733-d06943297d45', '丘中春臥寄王子', '丘中春臥寄王子', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["田中開白室，林下閉玄關。","卷跡人方處，無心雲自閑。","竹深喧暮鳥，花缺露春山。","勝事那能說，王孫去未還。"]', '["田中开白室，林下閉玄关。","卷跡人方处，無心云自闲。","竹深喧暮鸟，花缺露春山。","勝事那能说，王孫去未還。"]', '诗', 'shi', '', NULL, '丘中春臥寄王子 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e4bc2b-bcc0-46a2-9330-d72de872f4ce', '江行夜宿龍吼灘臨眺思峨眉隱者兼寄幕中諸公', '江行夜宿龙吼灘臨眺思峨眉隐者兼寄幕中諸公', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["官舍臨江口，灘聲人慣聞。","水煙晴吐月，山火夜燒雲。","且欲尋方士，無心戀使君。","異鄉何可住，況復久離羣。"]', '["官舍臨江口，灘声人慣闻。","水煙晴吐月，山火夜燒云。","且欲尋方士，無心戀使君。","異乡何可住，況复久離羣。"]', '诗', 'shi', '', NULL, '江行夜宿龍吼灘臨眺思峨眉隱者兼寄幕中諸公 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('280ffd6c-823e-4834-844a-e1e02b67d57b', '漢川山行呈成少尹', '漢川山行呈成少尹', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["西蜀方攜手，南宮憶比肩。","平生猶不淺，羈旅轉相憐。","山店雲迎客，江村犬吠船。","秋來取一醉，須待月光眠。"]', '["西蜀方携手，南宮憶比肩。","平生猶不淺，羈旅轉相怜。","山店云迎客，江村犬吠船。","秋来取一醉，須待月光眠。"]', '诗', 'shi', '', NULL, '漢川山行呈成少尹 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f477b9d-fe17-40e5-8f75-ae047f37fccc', '奉和杜相公初發京城作', '奉和杜相公初發京城作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["按節辭黃閣，登壇戀赤墀。","銜恩期報主，授律遠行師。","野鵲迎金印，郊雲拂畫旗。","叨陪幕中客，敢和出車詩。"]', '["按節辞黄閣，登壇戀赤墀。","銜恩期報主，授律远行師。","野鵲迎金印，郊云拂畫旗。","叨陪幕中客，敢和出车诗。"]', '诗', 'shi', '', NULL, '奉和杜相公初發京城作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81bbbd9c-12f3-4c30-b7f3-d4c5874244f5', '敬酬李判官使院即事見呈', '敬酬李判官使院即事见呈', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["公府日無事，吾徒只是閑。","草根侵柱礎，苔色上門關。","飲硯時見鳥，卷簾晴對山。","新詩吟未足，昨夜夢東還。"]', '["公府日無事，吾徒只是闲。","草根侵柱礎，苔色上门关。","饮硯时见鸟，卷簾晴对山。","新诗吟未足，昨夜梦东還。"]', '诗', 'shi', '', NULL, '敬酬李判官使院即事見呈 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1454d21c-0fd8-4011-b297-d9f33690150d', '虢州酬辛侍御見贈', '虢州酬辛侍御见贈', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["門柳葉已大，春花今復闌。","鬢毛方二色，愁緒日千端。","夫子屢新命，鄙夫仍舊官。","相思難見面，時展尺書看。"]', '["门柳葉已大，春花今复闌。","鬢毛方二色，愁緒日千端。","夫子屢新命，鄙夫仍旧官。","相思难见面，时展尺书看。"]', '诗', 'shi', '', NULL, '虢州酬辛侍御見贈 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25ee70e2-5059-4e8d-a748-64c9e2c9147a', '酬崔十三侍御登玉壘山思故園見寄', '酬崔十三侍御登玉壘山思故园见寄', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["玉壘天晴望，諸峰盡覺低。","故園江樹北，斜日巔雲西。","曠野看人小，長空共鳥齊。","高山徒仰止，不得日攀躋。"]', '["玉壘天晴望，諸峰尽覺低。","故园江樹北，斜日巔云西。","曠野看人小，长空共鸟齊。","高山徒仰止，不得日攀躋。"]', '诗', 'shi', '', NULL, '酬崔十三侍御登玉壘山思故園見寄 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fd7ed37-4b8d-4aab-aab1-d9a8862f0d77', '南樓送衛憑', '南楼送衛憑', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["近縣多過客，似君誠亦稀。","南樓取涼好，便送故人歸。","鳥向望中滅，雨侵晴處飛。","應須乘月去，且爲解征衣。"]', '["近縣多過客，似君誠亦稀。","南楼取涼好，便送故人归。","鸟向望中滅，雨侵晴处飞。","應須乘月去，且爲解征衣。"]', '诗', 'shi', '', NULL, '南樓送衛憑 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('021bc793-64cc-4fbe-b992-d079e1d201ca', '送王伯倫應制授正字歸', '送王伯倫應制授正字归', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["當年最稱意，數子不如君。","戰勝時偏許，名高人共聞。","半天城北雨，斜日灞西雲。","科斗皆成字，無令錯古文。"]', '["當年最稱意，數子不如君。","戰勝时偏許，名高人共闻。","半天城北雨，斜日灞西云。","科斗皆成字，無令錯古文。"]', '诗', 'shi', '', NULL, '送王伯倫應制授正字歸 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8b1ae0b-d5a2-4aa4-b665-119d5420c723', '送宇文舍人出宰元城', '送宇文舍人出宰元城', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["雙鳧出未央，千里過河陽。","馬帶新行色，衣聞舊御香。","縣花迎墨綬，關柳拂銅章。","別後能爲政，相思淇水長。"]', '["雙鳧出未央，千里過河陽。","马带新行色，衣闻旧御香。","縣花迎墨綬，关柳拂銅章。","別後能爲政，相思淇水长。"]', '诗', 'shi', '', NULL, '送宇文舍人出宰元城 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c721211-73ff-44c1-96a1-559aba4ef143', '崔駙馬山池重送宇文明府', '崔駙马山池重送宇文明府', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["竹裏過紅橋，花間藉綠苗。","池涼醒別酒，山翠拂行鑣。","鳳去妝樓閉，鳧飛葉縣遙。"]', '["竹裏過紅橋，花间藉綠苗。","池涼醒別酒，山翠拂行鑣。","鳳去妝楼閉，鳧飞葉縣遙。"]', '诗', 'shi', '', NULL, '崔駙馬山池重送宇文明府 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7de7975b-5efb-4f14-9a1b-2fc667e5b328', '送李郎尉武康', '送李郎尉武康', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["潘郎腰綬新，霅上縣花春。","山色低官舍，湖光映吏人。","不須嫌邑小，莫即恥家貧。","更作東征賦，知君有老親。"]', '["潘郎腰綬新，霅上縣花春。","山色低官舍，湖光映吏人。","不須嫌邑小，莫即恥家貧。","更作东征賦，知君有老親。"]', '诗', 'shi', '', NULL, '送李郎尉武康 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f2699d2-b060-43af-bcee-ee8abea39ade', '磧西頭送李判官入京', '磧西头送李判官入京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["一身從遠使，萬里向安西。","漢月垂鄉淚，胡沙費馬蹄。","尋河愁地盡，過磧覺天低。","送子軍中飲，家書醉裏題。"]', '["一身從远使，万里向安西。","漢月垂乡泪，胡沙費马蹄。","尋河愁地尽，過磧覺天低。","送子軍中饮，家书醉裏題。"]', '诗', 'shi', '', NULL, '磧西頭送李判官入京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e174b765-a22d-4b24-8438-544098fde00b', '陪使君早春西亭送王贊府赴選', '陪使君早春西亭送王贊府赴選', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["西亭繫五馬，爲送故人歸。","客舍草新出，關門花欲飛。","到來逢歲酒，却去換春衣。","吏部應相待，如君才調稀。"]', '["西亭繫五马，爲送故人归。","客舍草新出，关门花欲飞。","到来逢歲酒，却去換春衣。","吏部應相待，如君才調稀。"]', '诗', 'shi', '', NULL, '陪使君早春西亭送王贊府赴選 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fc0f637-f65f-4352-ae9d-ea1189a9047e', '送劉郎將歸河東', '送劉郎將归河东', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["借問虎賁將，從軍凡幾年。","殺人寶刀缺，走馬貂裘穿。","山雨醒別酒，關雲迎渡船。","謝君賢主將，豈忘輪臺邊。"]', '["借问虎賁將，從軍凡幾年。","殺人寶刀缺，走马貂裘穿。","山雨醒別酒，关云迎渡船。","謝君賢主將，豈忘輪台邊。"]', '诗', 'shi', '', NULL, '送劉郎將歸河東 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b413861-1cb9-4680-aed8-236f710f29c3', '滻水東店送唐子歸嵩陽', '滻水东店送唐子归嵩陽', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["野店臨官路，重城壓御隄。","山開灞水北，雨過杜陵西。","歸夢秋能作，鄉書醉嬾題。","橋回忽不見，征馬尚聞嘶。"]', '["野店臨官路，重城壓御隄。","山开灞水北，雨過杜陵西。","归梦秋能作，乡书醉嬾題。","橋回忽不见，征马尚闻嘶。"]', '诗', 'shi', '', NULL, '滻水東店送唐子歸嵩陽 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a9abb11-67ab-48df-b22a-f72b744d4aaf', '西亭送蔣侍御還京', '西亭送蔣侍御還京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["忽聞驄馬至，喜見故人來。","欲語多時別，先愁計日回。","山河宜晚眺，雲霧待君開。","爲報烏臺客，須憐白髮催。"]', '["忽闻驄马至，喜见故人来。","欲語多时別，先愁計日回。","山河宜晚眺，云霧待君开。","爲報烏台客，須怜白髮催。"]', '诗', 'shi', '', NULL, '西亭送蔣侍御還京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c696cba-6230-4cbc-b41e-b25aa10aa2df', '水亭送劉顒使還歸節度', '水亭送劉顒使還归節度', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["無計留君住，應須絆馬蹄。","紅亭莫惜醉，白日眼看低。","解帶憐高柳，移牀愛小谿。","此來相見少，正事各東西。"]', '["無計留君住，應須絆马蹄。","紅亭莫惜醉，白日眼看低。","解带怜高柳，移牀愛小谿。","此来相见少，正事各东西。"]', '诗', 'shi', '', NULL, '水亭送劉顒使還歸節度 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('533b0fd0-935f-4a9b-b80e-81f92af96165', '送楊錄事充潼關判官', '送楊錄事充潼关判官', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["夫子方寸裏，秋天澄霽江。","關西望第一，郡內政無雙。","狹室下珠箔，連宵傾玉缸。","平明猶未醉，斜月隱書牕。"]', '["夫子方寸裏，秋天澄霽江。","关西望第一，郡內政無雙。","狹室下珠箔，連宵傾玉缸。","平明猶未醉，斜月隐书牕。"]', '诗', 'shi', '', NULL, '送楊錄事充潼關判官 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f35944-c98f-4456-839f-92a6d792463f', '送裴判官自賊中再歸河陽幕府', '送裴判官自賊中再归河陽幕府', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["東郊未解圍，忠義似君稀。","誤落胡塵裏，能持漢節歸。","卷簾山對酒，上馬雪沾衣。","却向嫖姚幕，翩翩去若飛。"]', '["东郊未解圍，忠義似君稀。","誤落胡塵裏，能持漢節归。","卷簾山对酒，上马雪沾衣。","却向嫖姚幕，翩翩去若飞。"]', '诗', 'shi', '', NULL, '送裴判官自賊中再歸河陽幕府 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159fa3a6-de23-4c08-844d-434ce30093cc', '送陝縣王主簿赴襄陽成親', '送陝縣王主簿赴襄陽成親', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["六月襄山道，三星漢水邊。","求鳳應不遠，去馬賸須鞭。","野店愁中雨，江城夢裏蟬。","襄陽多故事，爲我訪先賢。"]', '["六月襄山道，三星漢水邊。","求鳳應不远，去马賸須鞭。","野店愁中雨，江城梦裏蟬。","襄陽多故事，爲我訪先賢。"]', '诗', 'shi', '', NULL, '送陝縣王主簿赴襄陽成親 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71634838-149c-4fde-9fe0-aa1c528376ca', '送李卿賦得孤島石', '送李卿賦得孤島石', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["一片他山石，巉巉映小池。","綠窠攢剝蘚，尖碩坐鸕鷀。","水底看常倒，花邊勢欲欹。","君心能不轉，卿月豈相離。"]', '["一片他山石，巉巉映小池。","綠窠攢剝蘚，尖碩坐鸕鷀。","水底看常倒，花邊勢欲欹。","君心能不轉，卿月豈相離。"]', '诗', 'shi', '', NULL, '送李卿賦得孤島石 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7828a7c6-eeb4-4336-afea-3f9015fecfc4', '送王錄事卻歸華陰', '送王錄事卻归华陰', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["相送欲狂歌，其如此別何。","攀轅人共惜，解印日無多。","仙掌雲重見，關門路再過。","雙魚莫不寄，縣外是黃河。"]', '["相送欲狂歌，其如此別何。","攀轅人共惜，解印日無多。","仙掌云重见，关门路再過。","雙鱼莫不寄，縣外是黄河。"]', '诗', 'shi', '', NULL, '送王錄事卻歸華陰 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa02a951-2237-4352-b209-821e4edd79cd', '送二十二兄北遊尋羅中', '送二十二兄北游尋羅中', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["斗柄欲東指，吾兄方北遊。","無媒謁明主，失計干諸侯。","夜雪入穿履，朝霜凝敝裘。","遙知客舍飲，醉裏聞春鳩。"]', '["斗柄欲东指，吾兄方北游。","無媒謁明主，失計干諸侯。","夜雪入穿履，朝霜凝敝裘。","遙知客舍饮，醉裏闻春鳩。"]', '诗', 'shi', '', NULL, '送二十二兄北遊尋羅中 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('488ac7aa-03f4-4da7-a627-b926aa9cac3b', '送鄭堪歸東京氾水別業', '送鄭堪归东京氾水別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["客舍見春草，忽聞思舊山。","看君灞陵去，匹馬成臯還。","對酒風與雪，向家河復關。","因悲宦遊子，終歲無時閑。"]', '["客舍见春草，忽闻思旧山。","看君灞陵去，匹马成臯還。","对酒风與雪，向家河复关。","因悲宦游子，終歲無时闲。"]', '诗', 'shi', '', NULL, '送鄭堪歸東京氾水別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaea0c4a-fff0-4282-9d71-87e636d4b673', '送崔全被放歸都覲省', '送崔全被放归都覲省', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["夫子不自衒，世人知者稀。","來傾阮氏酒，去着老萊衣。","渭北草新出，關東花欲飛。","楚王猶自惑，宋玉且將歸。"]', '["夫子不自衒，世人知者稀。","来傾阮氏酒，去着老萊衣。","渭北草新出，关东花欲飞。","楚王猶自惑，宋玉且將归。"]', '诗', 'shi', '', NULL, '送崔全被放歸都覲省 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('140531c1-b825-4405-b56c-a8daca14221f', '送孟孺卿落第歸濟陽', '送孟孺卿落第归濟陽', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["獻賦頭欲白，還家衣已穿。","羞過灞陵樹，歸種汶陽田。","客舍少鄉信，牀頭無酒錢。","聖朝徒側席，濟上獨遺賢。"]', '["獻賦头欲白，還家衣已穿。","羞過灞陵樹，归種汶陽田。","客舍少乡信，牀头無酒錢。","聖朝徒側席，濟上独遺賢。"]', '诗', 'shi', '', NULL, '送孟孺卿落第歸濟陽 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f06a9e7-55a8-4c0f-ac67-cb42a46e116a', '送裴校書從大夫淄川覲省', '送裴校书從大夫淄川覲省', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["尚書未出守，愛子向青州。","一路通關樹，孤城近海樓。","懷中江橘熟，倚處戟門秋。","更奉輕軒去，知君無客愁。"]', '["尚书未出守，愛子向青州。","一路通关樹，孤城近海楼。","懷中江橘熟，倚处戟门秋。","更奉轻軒去，知君無客愁。"]', '诗', 'shi', '', NULL, '送裴校書從大夫淄川覲省 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a232cacc-23f1-4c99-b1ea-7fdda56249d1', '送楊千牛趂歲赴汝南郡覲省便成婚', '送楊千牛趂歲赴汝南郡覲省便成婚', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["問吉轉征鞍，安仁道姓潘。","歸期明主賜，別酒故人歡。","珠箔障爐煖，孤裘耐臘寒。","汝南遙倚望，蚤去及春盤。"]', '["问吉轉征鞍，安仁道姓潘。","归期明主賜，別酒故人歡。","珠箔障爐煖，孤裘耐臘寒。","汝南遙倚望，蚤去及春盤。"]', '诗', 'shi', '', NULL, '送楊千牛趂歲赴汝南郡覲省便成婚 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97c78d0d-bbc3-49ad-889e-d0252e6b7849', '送胡象落第歸王屋別業', '送胡象落第归王屋別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["看君尚少年，不第莫悽然。","可即疲獻賦，山村歸種田。","野花迎短褐，河柳拂長鞭。","置酒聊相送，青門一醉眠。"]', '["看君尚少年，不第莫悽然。","可即疲獻賦，山村归種田。","野花迎短褐，河柳拂长鞭。","置酒聊相送，青门一醉眠。"]', '诗', 'shi', '', NULL, '送胡象落第歸王屋別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46b36db7-76c4-4424-9e1b-f4519b8ac02a', '送顏韶', '送顏韶', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["遷客猶未老，聖朝今復歸。","一從襄陽住，幾度梨花飛。","世事了可見，憐君人亦稀。","相逢貪醉臥，未得作春衣。"]', '["遷客猶未老，聖朝今复归。","一從襄陽住，幾度梨花飞。","世事了可见，怜君人亦稀。","相逢貪醉臥，未得作春衣。"]', '诗', 'shi', '', NULL, '送顏韶 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c56579-fd4e-438d-a072-455ed608a07f', '送杜佐下第歸陸渾別業', '送杜佐下第归陸渾別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["正月今欲半，陸渾花未開。","出關見青草，春色正東來。","夫子且歸去，明時方愛才。","還須及秋賦，莫即隱嵩萊。"]', '["正月今欲半，陸渾花未开。","出关见青草，春色正东来。","夫子且归去，明时方愛才。","還須及秋賦，莫即隐嵩萊。"]', '诗', 'shi', '', NULL, '送杜佐下第歸陸渾別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0247050-b161-4b3e-ae32-0d79b2b611d7', '送張郎中赴隴右覲省卿公', '送張郎中赴隴右覲省卿公', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["中郎鳳一毛，世上獨賢豪。","弱冠已銀印，出身唯寶刀。","還家卿月迥，度隴將星高。","幕下多相識，邊書醉嬾操。"]', '["中郎鳳一毛，世上独賢豪。","弱冠已銀印，出身唯寶刀。","還家卿月迥，度隴將星高。","幕下多相識，邊书醉嬾操。"]', '诗', 'shi', '', NULL, '送張郎中赴隴右覲省卿公 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6634baf-1b44-4cf3-9fab-0333330d986f', '送楚丘麴少府赴官', '送楚丘麴少府赴官', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["青袍美少年，黃綬一神仙。","微子城東面，梁王苑北邊。","桃花色似馬，榆莢小於錢。","單父聞相近，家書早爲傳。"]', '["青袍美少年，黄綬一神仙。","微子城东面，梁王苑北邊。","桃花色似马，榆莢小於錢。","單父闻相近，家书早爲傳。"]', '诗', 'shi', '', NULL, '送楚丘麴少府赴官 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15058957-c82e-4381-99db-8ba10dc2daa0', '送蜀郡李掾', '送蜀郡李掾', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["飲酒俱未醉，一言聊贈君。","功曹善爲政，明主還應聞。","夜宿劒門月，朝行巴水雲。","江城菊花發，滿道香氛氳。"]', '["饮酒俱未醉，一言聊贈君。","功曹善爲政，明主還應闻。","夜宿劒门月，朝行巴水云。","江城菊花發，满道香氛氳。"]', '诗', 'shi', '', NULL, '送蜀郡李掾 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('206c827e-5527-4ba7-a3cb-9b50d827b020', '送鄭少府赴滏陽', '送鄭少府赴滏陽', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["子真河朔尉，邑里帶清漳。","春草迎袍色，晴花拂綬香。","青山入官舍，黃鳥度宮牆。","若到銅臺上，應憐魏寢荒。"]', '["子真河朔尉，邑里带清漳。","春草迎袍色，晴花拂綬香。","青山入官舍，黄鸟度宮牆。","若到銅台上，應怜魏寢荒。"]', '诗', 'shi', '', NULL, '送鄭少府赴滏陽 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c65ae3f-33b4-4815-be75-50927a8b7df3', '還高冠潭口留別舍弟', '還高冠潭口留別舍弟', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["昨日山有信，祗今耕種時。","遙傳杜陵叟，怪我還山遲。","獨向潭上酌，無人林下棊。","東谿憶汝處，閑臥對鸕鷀。"]', '["昨日山有信，祗今耕種时。","遙傳杜陵叟，怪我還山遲。","独向潭上酌，無人林下棊。","东谿憶汝处，闲臥对鸕鷀。"]', '诗', 'shi', '', NULL, '還高冠潭口留別舍弟 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef601522-2609-43fd-bb82-aad1abff7669', '醴泉東谿送程皓元鏡微入蜀', '醴泉东谿送程皓元镜微入蜀', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["蜀郡路漫漫，梁州過七盤。","二人來信宿，一縣醉衣冠。","谿逼春衫冷，林交宴席寒。","西南如噴酒，遙向雨中看。"]', '["蜀郡路漫漫，梁州過七盤。","二人来信宿，一縣醉衣冠。","谿逼春衫冷，林交宴席寒。","西南如噴酒，遙向雨中看。"]', '诗', 'shi', '', NULL, '醴泉東谿送程皓元鏡微入蜀 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61aadf8a-d87b-44f8-8519-e07915791beb', '夏初醴泉南樓送太康顏少府', '夏初醴泉南楼送太康顏少府', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["何地堪相餞，南樓出萬家。","可憐高處送，遠見故人車。","野果新成子，庭槐欲作花。","愛君兄弟好，書向潁中誇。"]', '["何地堪相餞，南楼出万家。","可怜高处送，远见故人车。","野果新成子，庭槐欲作花。","愛君兄弟好，书向潁中誇。"]', '诗', 'shi', '', NULL, '夏初醴泉南樓送太康顏少府 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('243385c4-42fd-4352-8621-e966de6fd7cc', '送嚴詵擢第歸蜀', '送嚴詵擢第归蜀', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["巴江秋月新，閣道發征輪。","戰勝真才子，名高動世人。","工文能似舅，擢第去榮親。","十月天官待，應須早赴秦。"]', '["巴江秋月新，閣道發征輪。","戰勝真才子，名高动世人。","工文能似舅，擢第去榮親。","十月天官待，應須早赴秦。"]', '诗', 'shi', '', NULL, '送嚴詵擢第歸蜀 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b9070aa-2450-436a-abe9-09e68ccef4b3', '送張直公歸南鄭拜省', '送張直公归南鄭拜省', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["夫子思何速，世人皆歎奇。","萬言不加點，七步猶嫌遲。","對酒落日後，還家飛雪時。","北堂應久待，鄉夢促征期。"]', '["夫子思何速，世人皆歎奇。","万言不加点，七步猶嫌遲。","对酒落日後，還家飞雪时。","北堂應久待，乡梦促征期。"]', '诗', 'shi', '', NULL, '送張直公歸南鄭拜省 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37083527-cecd-4dac-a3da-e567dc28473a', '送周子落第遊荆南', '送周子落第游荆南', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["足下復不第，家貧尋故人。","且傾湘南酒，羞對關西塵。","山店橘花發，江城楓葉新。","若從巫峽過，應見楚王神。"]', '["足下复不第，家貧尋故人。","且傾湘南酒，羞对关西塵。","山店橘花發，江城楓葉新。","若從巫峽過，應见楚王神。"]', '诗', 'shi', '', NULL, '送周子落第遊荆南 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('419a6b58-3fda-4ea3-b78c-4cf70c97440b', '送薛彥偉擢第東歸', '送薛彥偉擢第东归', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["時輩似君稀，青春戰勝歸。","名登郄詵第，身着老萊衣。","稱意人皆羨，還家馬若飛。","一枝誰不折，棣蕚獨相輝。"]', '["时輩似君稀，青春戰勝归。","名登郄詵第，身着老萊衣。","稱意人皆羨，還家马若飞。","一枝誰不折，棣蕚独相輝。"]', '诗', 'shi', '', NULL, '送薛彥偉擢第東歸 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58214442-7fdc-4e08-a03c-663f722f739c', '送楊瑗尉南海', '送楊瑗尉南海', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["不擇南州尉，高堂有老親。","樓臺重蜃氣，邑里雜鮫人。","海暗三山雨，花明五嶺春。","此鄉多寶玉，慎莫厭清貧。"]', '["不擇南州尉，高堂有老親。","楼台重蜃氣，邑里杂鮫人。","海暗三山雨，花明五嶺春。","此乡多寶玉，慎莫厭清貧。"]', '诗', 'shi', '', NULL, '送楊瑗尉南海 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ed43de4-918c-4a9b-99dd-20757e2aad13', '鳳翔府行軍送程使君赴成州', '鳳翔府行軍送程使君赴成州', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["程侯新出守，好日發行軍。","拜命時人羨，能官聖主聞。","江樓黑塞雨，山郭冷秋雲。","竹馬諸童子，朝朝待使君。"]', '["程侯新出守，好日發行軍。","拜命时人羨，能官聖主闻。","江楼黑塞雨，山郭冷秋云。","竹马諸童子，朝朝待使君。"]', '诗', 'shi', '', NULL, '鳳翔府行軍送程使君赴成州 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c664e8ce-59c0-4f63-96b6-e8ec2b85b050', '送張昇卿宰新滏', '送張昇卿宰新滏', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["官柳葉尚小，長安春未濃。","送君潯陽宰，把酒青門鐘。","水驛楚雲冷，山城江樹重。","遙知南湖上，只對香爐峰。"]', '["官柳葉尚小，长安春未濃。","送君潯陽宰，把酒青门鐘。","水驛楚云冷，山城江樹重。","遙知南湖上，只对香爐峰。"]', '诗', 'shi', '', NULL, '送張昇卿宰新滏 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60527424-7af4-4f9b-a318-c99b4e01ac61', '送陳子歸陸渾別業', '送陳子归陸渾別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["雖不舊相識，知君丞相家。","故園伊川上，夜夢方山花。","種藥畏春過，出關愁路賒。","青門酒壚別，日暮東城鴉。"]', '["雖不旧相識，知君丞相家。","故园伊川上，夜梦方山花。","種藥畏春過，出关愁路賒。","青门酒壚別，日暮东城鴉。"]', '诗', 'shi', '', NULL, '送陳子歸陸渾別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eac4a1de-dfbc-41ea-8e53-44111648bbd8', '稠桑驛喜逢嚴河南中丞便別', '稠桑驛喜逢嚴河南中丞便別', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["駟馬映花枝，人人夾路窺。","離心且莫問，春草自應知。","不謂青雲客，猶思紫禁時。","別君能幾日，看取鬢成絲。"]', '["駟马映花枝，人人夾路窺。","離心且莫问，春草自應知。","不謂青云客，猶思紫禁时。","別君能幾日，看取鬢成絲。"]', '诗', 'shi', '', NULL, '稠桑驛喜逢嚴河南中丞便別 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feb6d17f-1f93-4acc-8498-8303ec15057d', '送蒲秀才擢第歸蜀', '送蒲秀才擢第归蜀', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["去馬疾如飛，看君戰勝歸。","新登郄詵第，更著老萊衣。","漢水行人少，巴山客舍稀。","向南風候暖，臘月見春輝。"]', '["去马疾如飞，看君戰勝归。","新登郄詵第，更著老萊衣。","漢水行人少，巴山客舍稀。","向南风候暖，臘月见春輝。"]', '诗', 'shi', '', NULL, '送蒲秀才擢第歸蜀 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d889671b-32ce-4339-96df-8223c6d3008d', '送郭司馬赴伊吾郡請示李明府', '送郭司马赴伊吾郡請示李明府', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["安西美少年，脫劒卸弓弦。","不倚將軍勢，皆稱司馬賢。","秋山城北面，古治郡東邊。","江上舟中月，遙思李郭仙。"]', '["安西美少年，脫劒卸弓弦。","不倚將軍勢，皆稱司马賢。","秋山城北面，古治郡东邊。","江上舟中月，遙思李郭仙。"]', '诗', 'shi', '', NULL, '送郭司馬赴伊吾郡請示李明府 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f45910-131f-4781-ab15-04030dd42120', '送滕亢擢第歸蘇州拜親', '送滕亢擢第归蘇州拜親', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["送爾姑蘇客，滄波秋正涼。","橘懷三箇去，桂折一枝將。","湖上山當舍，天邊水是鄉。","江村人事少，時作捕魚郎。"]', '["送爾姑蘇客，滄波秋正涼。","橘懷三箇去，桂折一枝將。","湖上山當舍，天邊水是乡。","江村人事少，时作捕鱼郎。"]', '诗', 'shi', '', NULL, '送滕亢擢第歸蘇州拜親 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e1243ee-98d9-4d44-989b-bd0addd325ac', '送任郎中出守明州', '送任郎中出守明州', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["罷起郎官草，初封刺史符。","城邊樓枕海，郭裏樹侵湖。","郡政傍連楚，朝恩獨借吳。","觀濤秋正好，莫不上姑蘇。"]', '["罷起郎官草，初封刺史符。","城邊楼枕海，郭裏樹侵湖。","郡政傍連楚，朝恩独借吳。","观濤秋正好，莫不上姑蘇。"]', '诗', 'shi', '', NULL, '送任郎中出守明州 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67a554f7-a0db-40b2-b9ca-06d85e21c235', '臨洮客舍留別祁四', '臨洮客舍留別祁四', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["無事向邊外，至今仍不歸。","三年絕鄉信，六月未春衣。","客舍洮水聒，孤城胡雁飛。","心知別君後，開口笑應稀。"]', '["無事向邊外，至今仍不归。","三年絕乡信，六月未春衣。","客舍洮水聒，孤城胡雁飞。","心知別君後，开口笑應稀。"]', '诗', 'shi', '', NULL, '臨洮客舍留別祁四 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecef8d02-193f-415c-a8fe-38bd9fdd8f5d', '送弘文李校書往漢南拜親', '送弘文李校书往漢南拜親', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["未識已先聞，清辭果出羣。","如逢禰處士，似見鮑參軍。","夢暗巴山雨，家連漢水雲。","慈親思愛子，幾度泣霑帬。"]', '["未識已先闻，清辞果出羣。","如逢禰处士，似见鲍參軍。","梦暗巴山雨，家連漢水云。","慈親思愛子，幾度泣霑帬。"]', '诗', 'shi', '', NULL, '送弘文李校書往漢南拜親 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ccd0fc6-775c-441e-b147-7f4751ad2913', '送李別將攝伊吾令充使赴武威便寄崔員外', '送李別將攝伊吾令充使赴武威便寄崔員外', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["詞賦滿書囊，胡爲在戰場。","行間脫寶劒，邑里挂銅章。","馬疾飛千里，鳧飛向五涼。","遙知竹林下，星使對星郎。"]', '["词賦满书囊，胡爲在戰場。","行间脫寶劒，邑里挂銅章。","马疾飞千里，鳧飞向五涼。","遙知竹林下，星使对星郎。"]', '诗', 'shi', '', NULL, '送李別將攝伊吾令充使赴武威便寄崔員外 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('198e7e9b-4df9-4717-a097-cdbfff71088b', '送四鎮薛侍御東歸', '送四鎮薛侍御东归', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["相送淚沾衣，天涯獨未歸。","將軍初得罪，門客復何依。","夢去湖山闊，書停隴雁稀。","園林幸接近，一爲到柴扉。"]', '["相送泪沾衣，天涯独未归。","將軍初得罪，门客复何依。","梦去湖山闊，书停隴雁稀。","园林幸接近，一爲到柴扉。"]', '诗', 'shi', '', NULL, '送四鎮薛侍御東歸 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0485439-df87-4157-a93d-3d3182421a1c', '送張都尉東歸', '送張都尉东归', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["白羽綠弓弦，年年只在邊。","還家劒鋒盡，出塞馬蹄穿。","逐虜西踰海，平胡北到天。","封侯應不遠，燕頷豈徒然。"]', '["白羽綠弓弦，年年只在邊。","還家劒鋒尽，出塞马蹄穿。","逐虜西踰海，平胡北到天。","封侯應不远，燕頷豈徒然。"]', '诗', 'shi', '', NULL, '送張都尉東歸 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66de4228-f223-4ed1-8247-f0581d19fa19', '送樊侍御使丹陽便覲', '送樊侍御使丹陽便覲', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["臥病窮巷晚，忽驚驄馬來。","知君京口去，借問幾時回。","驛舫江風引，鄉書海雁催。","慈親應倍喜，愛子在霜臺。"]', '["臥病窮巷晚，忽驚驄马来。","知君京口去，借问幾时回。","驛舫江风引，乡书海雁催。","慈親應倍喜，愛子在霜台。"]', '诗', 'shi', '', NULL, '送樊侍御使丹陽便覲 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be250398-698d-4578-9c92-38a03d12b674', '送張卿郎君赴硤石尉', '送張卿郎君赴硤石尉', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["卿家送愛子，愁見灞頭春。","草羨青袍色，花隨黃綬新。","縣西函谷路，城北大陽津。","日暮征鞍去，東郊一片塵。"]', '["卿家送愛子，愁见灞头春。","草羨青袍色，花隨黄綬新。","縣西函谷路，城北大陽津。","日暮征鞍去，东郊一片塵。"]', '诗', 'shi', '', NULL, '送張卿郎君赴硤石尉 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d9d22a6-554a-4ae2-ae04-7c8270c81564', '送顏少府投鄭陳州', '送顏少府投鄭陳州', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["一尉便垂白，數年唯草玄。","出關策匹馬，逆旅聞秋蟬。","愛客多酒債，罷官無俸錢。","知君羈思少，所適主人賢。"]', '["一尉便垂白，數年唯草玄。","出关策匹马，逆旅闻秋蟬。","愛客多酒債，罷官無俸錢。","知君羈思少，所適主人賢。"]', '诗', 'shi', '', NULL, '送顏少府投鄭陳州 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c95f2fb-72a4-4b94-b310-a0a29e25837c', '趙少尹南亭送鄭侍御歸東臺', '趙少尹南亭送鄭侍御归东台', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["紅亭酒甕香，白面繡衣郎。","砌冷蟲喧坐，簾疎雨到牀。","鐘催離興急，絃逐醉歌長。","關樹應先落，隨君滿鬢霜。"]', '["紅亭酒甕香，白面繡衣郎。","砌冷蟲喧坐，簾疎雨到牀。","鐘催離兴急，絃逐醉歌长。","关樹應先落，隨君满鬢霜。"]', '诗', 'shi', '', NULL, '趙少尹南亭送鄭侍御歸東臺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f8d79d6-22e4-4eea-aab8-eee493f9783a', '祁四再赴江南別詩', '祁四再赴江南別诗', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["萬里來又去，三湘東復西。","別多人換鬢，行遠馬穿蹄。","山驛秋雲冷，江帆暮雨低。","憐君不解說，相憶在書題。"]', '["万里来又去，三湘东复西。","別多人換鬢，行远马穿蹄。","山驛秋云冷，江帆暮雨低。","怜君不解说，相憶在书題。"]', '诗', 'shi', '', NULL, '祁四再赴江南別詩 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eb17488-6566-4e1c-b95c-fefea67389f6', '送許員外江外置常平倉', '送許員外江外置常平倉', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["詔置海陵倉，朝推畫省郎。","還家錦服貴，出使繡衣香。","水驛風催舫，江樓月透牀。","仍懷陸氏橘，歸獻老親嘗。"]', '["詔置海陵倉，朝推畫省郎。","還家錦服貴，出使繡衣香。","水驛风催舫，江楼月透牀。","仍懷陸氏橘，归獻老親嘗。"]', '诗', 'shi', '', NULL, '送許員外江外置常平倉 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('591de27e-b6fd-4ef1-9e8f-8752159bbc94', '送秘省虞校書赴虞鄉丞', '送秘省虞校书赴虞乡丞', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["花綬傍腰新，關東縣欲春。","殘書厭科斗，舊閣別麒麟。","虞坂臨官舍，條山映吏人。","看君有知己，坦腹向平津。"]', '["花綬傍腰新，关东縣欲春。","殘书厭科斗，旧閣別麒麟。","虞坂臨官舍，條山映吏人。","看君有知己，坦腹向平津。"]', '诗', 'shi', '', NULL, '送秘省虞校書赴虞鄉丞 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce69ecd-3b11-47a2-8b60-89171fb032fb', '送江陵泉少府赴任便呈衛荆州', '送江陵泉少府赴任便呈衛荆州', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["神仙吏姓梅，人吏待君來。","渭北草新出，江南花已開。","城邊宋玉宅，峽口楚王臺。","不畏無知己，荆州甚愛才。"]', '["神仙吏姓梅，人吏待君来。","渭北草新出，江南花已开。","城邊宋玉宅，峽口楚王台。","不畏無知己，荆州甚愛才。"]', '诗', 'shi', '', NULL, '送江陵泉少府赴任便呈衛荆州 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2ad53f7-18e4-484b-b9a0-ad05d136563d', '奉送李太保兼御史大夫充渭北節度使', '奉送李太保兼御史大夫充渭北節度使', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["詔出未央宮，登壇近總戎。","上公周太保，副相漢司空。","弓抱關西月，旗翻渭北風。","弟兄皆許國，天地荷成功。"]', '["詔出未央宮，登壇近總戎。","上公周太保，副相漢司空。","弓抱关西月，旗翻渭北风。","弟兄皆許国，天地荷成功。"]', '诗', 'shi', '', NULL, '奉送李太保兼御史大夫充渭北節度使 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3918d69c-4a7c-4001-9d86-050b98b4e3d1', '送江陵黎少府', '送江陵黎少府', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["悔繫腰間綬，翻爲膝下愁。","那堪漢水遠，更值楚山秋。","新橘香官舍，征帆拂縣樓。","王城不敢住，豈是愛荆州。"]', '["悔繫腰间綬，翻爲膝下愁。","那堪漢水远，更值楚山秋。","新橘香官舍，征帆拂縣楼。","王城不敢住，豈是愛荆州。"]', '诗', 'shi', '', NULL, '送江陵黎少府 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce711110-1b21-4a18-ac8e-6287f395c3f7', '虢州送天平何丞入京市馬', '虢州送天平何丞入京市马', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["關樹晚蒼蒼，長安近夕陽。","回風醒別酒，細雨濕行裝。","習戰邊塵黑，防秋塞草黃。","知君市駿馬，不是學燕王。"]', '["关樹晚蒼蒼，长安近夕陽。","回风醒別酒，細雨濕行裝。","習戰邊塵黑，防秋塞草黄。","知君市駿马，不是学燕王。"]', '诗', 'shi', '', NULL, '虢州送天平何丞入京市馬 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db346c45-7693-4606-b44c-4eab9b7d1c11', '送揚州王司馬', '送揚州王司马', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["君家舊淮水，水上到揚州。","海樹青官舍，江雲黑郡樓。","東南隨去鳥，人吏待行舟。","爲報吾兄道，如今已白頭。"]', '["君家旧淮水，水上到揚州。","海樹青官舍，江云黑郡楼。","东南隨去鸟，人吏待行舟。","爲報吾兄道，如今已白头。"]', '诗', 'shi', '', NULL, '送揚州王司馬 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99363abb-17d8-426a-9f85-0ade96a3cf83', '陝州月城樓送辛判官入奏', '陝州月城楼送辛判官入奏', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["送客飛鳥外，城頭樓最高。","樽前遇風雨，牕裏動波濤。","謁帝向金殿，隨身唯寶刀。","相思灞陵月，祗有夢偏勞。"]', '["送客飞鸟外，城头楼最高。","樽前遇风雨，牕裏动波濤。","謁帝向金殿，隨身唯寶刀。","相思灞陵月，祗有梦偏勞。"]', '诗', 'shi', '', NULL, '陝州月城樓送辛判官入奏 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21470562-7e1f-4787-8ffd-a8a8167f2413', '送王七錄事赴虢州', '送王七錄事赴虢州', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["早歲即相知，嗟君最後時。","青雲仍未達，白髮欲成絲。","小店關門樹，長河華岳祠。","弘農人吏待，莫使馬行遲。"]', '["早歲即相知，嗟君最後时。","青云仍未達，白髮欲成絲。","小店关门樹，长河华岳祠。","弘農人吏待，莫使马行遲。"]', '诗', 'shi', '', NULL, '送王七錄事赴虢州 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a58320b6-241f-4493-a16b-07548852a4f1', '閿鄉送上官秀才歸關西別業', '閿乡送上官秀才归关西別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["風塵奈汝何，終日獨波波。","親老無官養，家貧在外多。","醉眼輕白髮，春夢渡黃河。","相去關城近，何時更肯過。"]', '["风塵奈汝何，終日独波波。","親老無官養，家貧在外多。","醉眼轻白髮，春梦渡黄河。","相去关城近，何时更肯過。"]', '诗', 'shi', '', NULL, '閿鄉送上官秀才歸關西別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c930ad8-7e4a-4cb3-896e-bcac8a90e366', '送羽林長孫將軍赴歙州', '送羽林长孫將軍赴歙州', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["剖竹向江濆，能名計日聞。","隼旗新刺史，虎劒舊將軍。","驛舫宿湖月，州城浸海雲。","青門酒樓上，欲別醉醺醺。"]', '["剖竹向江濆，能名計日闻。","隼旗新刺史，虎劒旧將軍。","驛舫宿湖月，州城浸海云。","青门酒楼上，欲別醉醺醺。"]', '诗', 'shi', '', NULL, '送羽林長孫將軍赴歙州 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a12ebde7-17c1-4657-b20e-64841a6a9c1a', '送崔主簿赴夏陽', '送崔主簿赴夏陽', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["常愛夏陽縣，往年曾再過。","縣中饒白鳥，郭外是黃河。","地近行程少，家貧酒債多。","知君新稱意，好得奈春何。"]', '["常愛夏陽縣，往年曾再過。","縣中饒白鸟，郭外是黄河。","地近行程少，家貧酒債多。","知君新稱意，好得奈春何。"]', '诗', 'shi', '', NULL, '送崔主簿赴夏陽 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c5f6b9-be0c-47d6-8dac-10586a2ba00b', '送梁判官歸女几舊廬', '送梁判官归女几旧廬', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["女几知君憶，春雲相逐歸。","草堂開藥裹，苔壁取荷衣。","老竹移時少，新花舊處飛。","可憐真傲吏，塵事到山稀。"]', '["女几知君憶，春云相逐归。","草堂开藥裹，苔壁取荷衣。","老竹移时少，新花旧处飞。","可怜真傲吏，塵事到山稀。"]', '诗', 'shi', '', NULL, '送梁判官歸女几舊廬 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed6531c4-32e3-409a-9c1c-7a3d07fe4765', '送懷州吳別駕', '送懷州吳別駕', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["灞上柳枝黃，壚頭酒正香。","春流飲去馬，暮雨濕行裝。","驛路通函谷，州城接太行。","覃懷人總喜，別駕得王祥。"]', '["灞上柳枝黄，壚头酒正香。","春流饮去马，暮雨濕行裝。","驛路通函谷，州城接太行。","覃懷人總喜，別駕得王祥。"]', '诗', 'shi', '', NULL, '送懷州吳別駕 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c060b80-d568-48e9-9bdd-8bd686764b7a', '送人歸江寧', '送人归江寧', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["楚客憶鄉信，向家湖水長。","住愁春草綠，去喜桂枝香。","海月迎歸楚，江雲引到鄉。","吾兄應借問，爲報鬢毛霜。"]', '["楚客憶乡信，向家湖水长。","住愁春草綠，去喜桂枝香。","海月迎归楚，江云引到乡。","吾兄應借问，爲報鬢毛霜。"]', '诗', 'shi', '', NULL, '送人歸江寧 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ebe151-f22e-43d0-8936-edd8555afc91', '送襄州任別駕', '送襄州任別駕', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["別乘向襄州，蕭條楚地秋。","江聲官舍裏，山色郡城頭。","莫羨黃公蓋，須乘彥伯舟。","高陽諸醉客，唯見古時丘。"]', '["別乘向襄州，蕭條楚地秋。","江声官舍裏，山色郡城头。","莫羨黄公蓋，須乘彥伯舟。","高陽諸醉客，唯见古时丘。"]', '诗', 'shi', '', NULL, '送襄州任別駕 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c714722f-dfa3-4c65-84a2-4ad47395ed29', '送李司諫歸京', '送李司諫归京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["別酒爲誰香，春官駁正郎。","醉經秦樹遠，夢怯漢川長。","雨過風頭黑，雲開日脚黃。","知君解起草，早去入文昌。"]', '["別酒爲誰香，春官駁正郎。","醉經秦樹远，梦怯漢川长。","雨過风头黑，云开日脚黄。","知君解起草，早去入文昌。"]', '诗', 'shi', '', NULL, '送李司諫歸京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdbe7199-8194-4036-b1e2-25940455925f', '送緜州李司馬秩滿歸京因呈李兵部', '送緜州李司马秩满归京因呈李兵部', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["久客厭江月，罷官思早歸。","眼看春光老，羞見梨花飛。","劒北山居小，巴南音信稀。","因君報兵部，愁淚日沾衣。"]', '["久客厭江月，罷官思早归。","眼看春光老，羞见梨花飞。","劒北山居小，巴南音信稀。","因君報兵部，愁泪日沾衣。"]', '诗', 'shi', '', NULL, '送緜州李司馬秩滿歸京因呈李兵部 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4ba6980-9371-4c36-af22-0d3d12449c1d', '送崔員外入秦因訪故園', '送崔員外入秦因訪故园', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["欲謁明光殿，先趨建禮門。","仙郎去得意，亞相正承恩。","竹裏巴山道，花間漢水源。","憑將兩行淚，爲訪邵平園。"]', '["欲謁明光殿，先趨建禮门。","仙郎去得意，亞相正承恩。","竹裏巴山道，花间漢水源。","憑將兩行泪，爲訪邵平园。"]', '诗', 'shi', '', NULL, '送崔員外入秦因訪故園 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3289abaf-561f-4f52-bc3b-474ba34426c3', '送柳錄事赴梁州', '送柳錄事赴梁州', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["英掾柳家郎，離亭酒甕香。","折腰思漢北，隨傳過巴陽。","江樹連官舍，山雲到臥牀。","知君歸夢積，去去劒川長。"]', '["英掾柳家郎，離亭酒甕香。","折腰思漢北，隨傳過巴陽。","江樹連官舍，山云到臥牀。","知君归梦積，去去劒川长。"]', '诗', 'shi', '', NULL, '送柳錄事赴梁州 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ef9886d-e69b-4b6a-84d4-1bbb914cb0f3', '送韋侍御先歸京', '送韋侍御先归京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["聞欲朝龍闕，應須拂豸冠。","風霜隨馬去，炎暑爲君寒。","客淚題書落，鄉愁對酒寬。","先憑報親友，後月到長安。"]', '["闻欲朝龙闕，應須拂豸冠。","风霜隨马去，炎暑爲君寒。","客泪題书落，乡愁对酒寬。","先憑報親友，後月到长安。"]', '诗', 'shi', '', NULL, '送韋侍御先歸京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00b1cc10-cea3-480e-b521-534bed2bfca6', '送裴侍御赴歲入京', '送裴侍御赴歲入京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["羨他驄馬郎，元日謁明光。","立處聞天語，朝回惹御香。","臺寒柏樹綠，江暖柳條黃。","惜別津亭暮，揮戈憶魯陽。"]', '["羨他驄马郎，元日謁明光。","立处闻天語，朝回惹御香。","台寒柏樹綠，江暖柳條黄。","惜別津亭暮，揮戈憶魯陽。"]', '诗', 'shi', '', NULL, '送裴侍御赴歲入京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbec112f-e996-40af-a921-e6c50b8f4916', '送顏評事入京', '送顏評事入京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["顏子人歎屈，宦遊今未遲。","佇聞明主用，豈負青雲姿。","江柳秋吐葉，山花寒滿枝。","知君客愁處，月滿巴川時。"]', '["顏子人歎屈，宦游今未遲。","佇闻明主用，豈負青云姿。","江柳秋吐葉，山花寒满枝。","知君客愁处，月满巴川时。"]', '诗', 'shi', '', NULL, '送顏評事入京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00d1b5fb-ef26-4bee-b087-1e8f4b475ea3', '送趙侍御歸上都', '送趙侍御归上都', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["驄馬五花毛，青雲歸處高。","霜隨驅夏暑，風逐振江濤。","執簡皆推直，勤王豈告勞。","帝城誰不戀，回望動離騷。"]', '["驄马五花毛，青云归处高。","霜隨驱夏暑，风逐振江濤。","執簡皆推直，勤王豈告勞。","帝城誰不戀，回望动離騷。"]', '诗', 'shi', '', NULL, '送趙侍御歸上都 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f081e39e-395a-485f-970b-0bb9570bddbf', '送楊子', '送楊子', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["斗酒渭城邊，壚頭耐醉眠。","梨花千樹雪，楊葉萬條煙。","惜別添壺酒，臨岐贈馬鞭。","看君潁上去，新月到家圓。"]', '["斗酒渭城邊，壚头耐醉眠。","梨花千樹雪，楊葉万條煙。","惜別添壺酒，臨岐贈马鞭。","看君潁上去，新月到家圓。"]', '诗', 'shi', '', NULL, '送楊子 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64e47b56-6f5f-46a8-a02b-c0830a25d881', '送人赴安西', '送人赴安西', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["上馬帶胡鈎，翩翩度隴頭。","小來思報國，不是愛封侯。","萬里鄉爲夢，三邊月作愁。","早須清黠虜，無事莫經秋。"]', '["上马带胡鈎，翩翩度隴头。","小来思報国，不是愛封侯。","万里乡爲梦，三邊月作愁。","早須清黠虜，無事莫經秋。"]', '诗', 'shi', '', NULL, '送人赴安西 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a9d048-cd4a-44b2-b8fc-9be5c34b1c1b', '發臨洮將赴北庭留別', '發臨洮將赴北庭留別', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["聞說輪臺路，連年見雪飛。","春風曾不到，漢使亦應稀。","白草通疎勒，青山過武威。","勤王敢道遠，私向夢中歸。"]', '["闻说輪台路，連年见雪飞。","春风曾不到，漢使亦應稀。","白草通疎勒，青山過武威。","勤王敢道远，私向梦中归。"]', '诗', 'shi', '', NULL, '發臨洮將赴北庭留別 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1751b2ac-e010-467b-9331-dab0c0618096', '臨洮泛舟趙仙舟自北庭罷使還京', '臨洮泛舟趙仙舟自北庭罷使還京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["白髮輪臺使，邊功竟不成。","雲沙萬里地，孤負一書生。","池上風迴舫，橋西雨過城。","醉眠鄉夢罷，東望羨歸程。"]', '["白髮輪台使，邊功竟不成。","云沙万里地，孤負一书生。","池上风迴舫，橋西雨過城。","醉眠乡梦罷，东望羨归程。"]', '诗', 'shi', '', NULL, '臨洮泛舟趙仙舟自北庭罷使還京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2564b5f-f65c-43e9-b07a-a3385ff0e96e', '春日醴泉杜明府承恩五品宴席上賦詩', '春日醴泉杜明府承恩五品宴席上賦诗', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["鳧舃舊稱仙，鴻私降自天。","青袍移草色，朱綬奪花然。","邑裏雷仍震，臺中星欲懸。","吾兄此棲棘，因得賀初筵。"]', '["鳧舃旧稱仙，鴻私降自天。","青袍移草色，朱綬奪花然。","邑裏雷仍震，台中星欲懸。","吾兄此棲棘，因得賀初筵。"]', '诗', 'shi', '', NULL, '春日醴泉杜明府承恩五品宴席上賦詩 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e857891d-2247-488e-b445-2ecdb3e3cb1b', '早春陪崔中丞同泛浣花谿宴', '早春陪崔中丞同泛浣花谿宴', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["旌節臨谿口，塞郊陡覺暄。","紅亭移酒席，畫舸逗江村。","雲帶歌聲颺，風飄舞袖翻。","花間催秉燭，川上欲黃昏。"]', '["旌節臨谿口，塞郊陡覺暄。","紅亭移酒席，畫舸逗江村。","云带歌声颺，风飄舞袖翻。","花间催秉燭，川上欲黄昏。"]', '诗', 'shi', '', NULL, '早春陪崔中丞同泛浣花谿宴 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e36fc6e9-0c5c-4846-b18a-0ba7d4ea30fe', '喜華陰王少府使到南池宴集', '喜华陰王少府使到南池宴集', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["有客至鈴下，自言身姓梅。","仙人掌裏使，黃帝鼎邊來。","竹影拂棋局，荷香隨酒杯。","池前堪醉臥，待月未須回。"]', '["有客至鈴下，自言身姓梅。","仙人掌裏使，黄帝鼎邊来。","竹影拂棋局，荷香隨酒杯。","池前堪醉臥，待月未須回。"]', '诗', 'shi', '', NULL, '喜華陰王少府使到南池宴集 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dfe9475-04eb-4193-8178-e2af2e0ac0bf', '行軍雪後月夜宴王卿家', '行軍雪後月夜宴王卿家', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["子夜雪華餘，卿家月影初。","酒香薰枕席，爐氣煖軒除。","晚歲宦情薄，行軍歡宴疎。","相逢剩取醉，身外盡空虛。"]', '["子夜雪华餘，卿家月影初。","酒香薰枕席，爐氣煖軒除。","晚歲宦情薄，行軍歡宴疎。","相逢剩取醉，身外尽空虛。"]', '诗', 'shi', '', NULL, '行軍雪後月夜宴王卿家 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efe34525-547b-4c45-bd64-b198bd29b01f', '梁州陪趙行軍龍岡寺北庭泛舟宴王侍御', '梁州陪趙行軍龙岡寺北庭泛舟宴王侍御', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["誰宴霜臺使，行軍粉署郎。","唱歌江鳥沒，吹笛岸花香。","酒影搖新月，灘聲聒夕陽。","江鐘聞已暮，歸櫂綠川長。"]', '["誰宴霜台使，行軍粉署郎。","唱歌江鸟沒，吹笛岸花香。","酒影搖新月，灘声聒夕陽。","江鐘闻已暮，归櫂綠川长。"]', '诗', 'shi', '', NULL, '梁州陪趙行軍龍岡寺北庭泛舟宴王侍御 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d6a39b-839b-4fee-85a8-c44141947ae0', '奉陪封大夫宴得征字時封公兼鴻臚卿', '奉陪封大夫宴得征字时封公兼鴻臚卿', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["西邊虜盡平，何處更專征。","幕下人無事，軍中政已成。","座參殊俗語，樂雜異方聲。","醉裏東樓月，偏能照列卿。"]', '["西邊虜尽平，何处更專征。","幕下人無事，軍中政已成。","座參殊俗語，乐杂異方声。","醉裏东楼月，偏能照列卿。"]', '诗', 'shi', '', NULL, '奉陪封大夫宴得征字時封公兼鴻臚卿 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f94823d-3aee-4815-a360-c6444d2fa79b', '陪封大夫宴瀚海亭納涼', '陪封大夫宴瀚海亭納涼', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["細管雜青絲，千杯倒接䍦。","軍中乘興出，海上納涼時。","日沒鳥飛急，山高雲過遲。","吾從大夫後，歸路擁旌旗。"]', '["細管杂青絲，千杯倒接䍦。","軍中乘兴出，海上納涼时。","日沒鸟飞急，山高云過遲。","吾從大夫後，归路擁旌旗。"]', '诗', 'shi', '', NULL, '陪封大夫宴瀚海亭納涼 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e76f8af5-cc6e-4358-b62f-faefbc105c25', '虢州西亭陪端公宴集', '虢州西亭陪端公宴集', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["紅亭出鳥外，駿馬繫雲端。","萬嶺牕前睥，千家肘底看。","開瓶酒色嫩，踏地葉聲乾。","爲逼霜臺使，重裘也覺寒。"]', '["紅亭出鸟外，駿马繫云端。","万嶺牕前睥，千家肘底看。","开瓶酒色嫩，踏地葉声乾。","爲逼霜台使，重裘也覺寒。"]', '诗', 'shi', '', NULL, '虢州西亭陪端公宴集 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('201f9fdc-32b3-4760-bf45-fdf64e609d10', '陪使君早春東郊遊眺', '陪使君早春东郊游眺', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["太守擁朱輪，東郊物候新。","鶯聲隨坐嘯，柳色喚行春。","谷口雲迎馬，谿邊水照人。","郡中叨佐理，何幸接芳塵。"]', '["太守擁朱輪，东郊物候新。","鶯声隨坐嘯，柳色喚行春。","谷口云迎马，谿邊水照人。","郡中叨佐理，何幸接芳塵。"]', '诗', 'shi', '', NULL, '陪使君早春東郊遊眺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6e8b764-028a-4f37-ad86-79b7771901c8', '雪後與羣公過慈恩寺', '雪後與羣公過慈恩寺', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["乘興忽相招，僧房暮與朝。","雪融雙樹濕，沙闇一燈燒。","竹外山低塔，藤間院隔橋。","歸家如欲嬾，俗慮向來銷。"]', '["乘兴忽相招，僧房暮與朝。","雪融雙樹濕，沙闇一灯燒。","竹外山低塔，藤间院隔橋。","归家如欲嬾，俗慮向来銷。"]', '诗', 'shi', '', NULL, '雪後與羣公過慈恩寺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cab002c4-20bf-4655-816b-42285672ac52', '與鄠縣羣官泛渼陂', '與鄠縣羣官泛渼陂', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["萬頃浸天色，千尋窮地根。","舟移城入樹，岸闊水浮村。","閑鷺驚簫管，潛蚪傍酒樽。","暝來呼小吏，列火儼歸軒。"]', '["万頃浸天色，千尋窮地根。","舟移城入樹，岸闊水浮村。","闲鷺驚簫管，潛蚪傍酒樽。","暝来呼小吏，列火儼归軒。"]', '诗', 'shi', '', NULL, '與鄠縣羣官泛渼陂 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855e941b-a519-4c21-881e-f02b787c781b', '與鄠縣源少府泛渼陂', '與鄠縣源少府泛渼陂', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["載酒入天色，水涼難醉人。","清搖縣郭動，碧洗雲山新。","吹笛驚白鷺，垂竿跳紫鱗。","憐君公事後，陂上日娛賓。"]', '["載酒入天色，水涼难醉人。","清搖縣郭动，碧洗云山新。","吹笛驚白鷺，垂竿跳紫鱗。","怜君公事後，陂上日娛賓。"]', '诗', 'shi', '', NULL, '與鄠縣源少府泛渼陂 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8caa72e6-fb8a-4eec-b10c-b9c8e5aa604f', '終南東谿中作', '終南东谿中作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["谿水碧於草，潺潺花底流。","沙平堪濯足，石淺不勝舟。","洗藥朝與暮，釣魚春復秋。","興來從所適，還欲向滄洲。"]', '["谿水碧於草，潺潺花底流。","沙平堪濯足，石淺不勝舟。","洗藥朝與暮，釣鱼春复秋。","兴来從所適，還欲向滄洲。"]', '诗', 'shi', '', NULL, '終南東谿中作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d3ee014-4685-411f-a355-c61fb8f1c60f', '與鮮于庶子泛漢江', '與鲜于庶子泛漢江', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["急管更須吹，杯行莫遣遲。","酒光紅琥珀，江色碧琉璃。","日影浮歸櫂，蘆花罥釣絲。","山公醉不醉，問取葛[彊]知。"]', '["急管更須吹，杯行莫遣遲。","酒光紅琥珀，江色碧琉璃。","日影浮归櫂，蘆花罥釣絲。","山公醉不醉，问取葛[彊]知。"]', '诗', 'shi', '', NULL, '與鮮于庶子泛漢江 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b5dace5-0190-47bd-9ccb-753d02586841', '晦日陪侍御泛北池', '晦日陪侍御泛北池', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["春池滿復寬，晦節耐邀歡。","月帶蝦蟆冷，霜隨獬豸寒。","水雲低錦席，岸柳拂金盤。","日暮舟中散，都人夾道看。"]', '["春池满复寬，晦節耐邀歡。","月带蝦蟆冷，霜隨獬豸寒。","水云低錦席，岸柳拂金盤。","日暮舟中散，都人夾道看。"]', '诗', 'shi', '', NULL, '晦日陪侍御泛北池 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9386166-3c09-4fe5-8729-211522fed11c', '登涼州尹臺寺', '登涼州尹台寺', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["胡地三月半，梨花今始開。","因從老僧飯，更上夫人臺。","清唱雲不去，彈弦風颯來。","應須一倒載，還似山公回。"]', '["胡地三月半，梨花今始开。","因從老僧飯，更上夫人台。","清唱云不去，彈弦风颯来。","應須一倒載，還似山公回。"]', '诗', 'shi', '', NULL, '登涼州尹臺寺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('942207f5-4f44-4a17-be61-d8c1d920e15b', '登總持閣', '登總持閣', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["高閣逼諸天，登臨近日邊。","晴開萬井樹，愁看五陵煙。","檻外低秦嶺，牕中小渭川。","蚤知清淨理，常願奉金仙。"]', '["高閣逼諸天，登臨近日邊。","晴开万井樹，愁看五陵煙。","檻外低秦嶺，牕中小渭川。","蚤知清淨理，常願奉金仙。"]', '诗', 'shi', '', NULL, '登總持閣 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93d374e6-a2de-40d6-8693-00d9f2f12735', '奉陪封大夫九日登高', '奉陪封大夫九日登高', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["九日黃花酒，登高會昔聞。","霜威逐亞相，殺氣傍中軍。","橫笛驚征雁，嬌歌落塞雲。","邊頭幸無事，醉舞荷吾君。"]', '["九日黄花酒，登高會昔闻。","霜威逐亞相，殺氣傍中軍。","橫笛驚征雁，嬌歌落塞云。","邊头幸無事，醉舞荷吾君。"]', '诗', 'shi', '', NULL, '奉陪封大夫九日登高 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dadc890d-8b50-4436-a24b-ebbab78de0ac', '郡齋平望江山', '郡斋平望江山', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["水路東連楚，人煙北接巴。","山光圍一郡，江月照千家。","庭樹純栽橘，園畦半種茶。","夢魂知憶處，無夜不京華。"]', '["水路东連楚，人煙北接巴。","山光圍一郡，江月照千家。","庭樹純栽橘，园畦半種茶。","梦魂知憶处，無夜不京华。"]', '诗', 'shi', '', NULL, '郡齋平望江山 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dec866d2-fe96-49ae-b85c-b496ece796c1', '宿岐州北郭嚴給事別業', '宿岐州北郭嚴給事別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["郭外山色暝，主人林館秋。","疎鐘入臥內，片月到牀頭。","遙夜惜已半，清言殊未休。","君雖在青瑣，心不忘滄洲。"]', '["郭外山色暝，主人林館秋。","疎鐘入臥內，片月到牀头。","遙夜惜已半，清言殊未休。","君雖在青瑣，心不忘滄洲。"]', '诗', 'shi', '', NULL, '宿岐州北郭嚴給事別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10be75fb-88f4-48bd-9c47-693b105abeb9', '暮秋會嚴京兆後廳竹齋', '暮秋會嚴京兆後廳竹斋', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["京兆小齋寬，公庭半藥闌。","甌香茶色嫩，牕冷竹聲乾。","盛德中朝貴，清風畫省寒。","能將吏部鏡，照取寸心看。"]', '["京兆小斋寬，公庭半藥闌。","甌香茶色嫩，牕冷竹声乾。","盛德中朝貴，清风畫省寒。","能將吏部镜，照取寸心看。"]', '诗', 'shi', '', NULL, '暮秋會嚴京兆後廳竹齋 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('475e4fe0-2285-48fa-934c-45a953968c98', '省中即事', '省中即事', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["華省謬爲郎，蹉跎鬢已蒼。","到來恆襆被，隨例且含香。","竹影遮牕暗，花陰拂簟涼。","君王新賜筆，草奏向明光。"]', '["华省謬爲郎，蹉跎鬢已蒼。","到来恆襆被，隨例且含香。","竹影遮牕暗，花陰拂簟涼。","君王新賜笔，草奏向明光。"]', '诗', 'shi', '', NULL, '省中即事 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e501217e-860a-4c75-97a4-acd950c32a3b', '尋陽七郎中宅即事', '尋陽七郎中宅即事', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["萬事信蒼蒼，機心久已忘。","無端來出守，不是厭爲郎。","雨滴芭蕉赤，霜催橘子黃。","逢君開口笑，何處有他鄉。"]', '["万事信蒼蒼，機心久已忘。","無端来出守，不是厭爲郎。","雨滴芭蕉赤，霜催橘子黄。","逢君开口笑，何处有他乡。"]', '诗', 'shi', '', NULL, '尋陽七郎中宅即事 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9482ea5-89a4-4ad7-967c-b65206c8cc87', '攜琴酒尋閻防崇濟寺所居僧院', '携琴酒尋閻防崇濟寺所居僧院', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["相訪但尋鐘，門寒古殿松。","彈琴醒暮酒，卷幔引諸峰。","事愜林中語，人幽物外蹤。","吾廬幸接近，茲地興偏慵。"]', '["相訪但尋鐘，门寒古殿松。","彈琴醒暮酒，卷幔引諸峰。","事愜林中語，人幽物外蹤。","吾廬幸接近，茲地兴偏慵。"]', '诗', 'shi', '', NULL, '攜琴酒尋閻防崇濟寺所居僧院 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89b4aaae-3a69-4e0a-98bc-87dbed3aad15', '春尋河陽陶處士別業', '春尋河陽陶处士別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["風煖日暾暾，黃鸝飛近村。","花明潘子縣，柳暗陶公門。","藥椀搖山影，魚竿帶水痕。","南橋車馬客，何事苦喧喧。"]', '["风煖日暾暾，黄鸝飞近村。","花明潘子縣，柳暗陶公门。","藥椀搖山影，鱼竿带水痕。","南橋车马客，何事苦喧喧。"]', '诗', 'shi', '', NULL, '春尋河陽陶處士別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f7dc274-b65b-4444-90a7-0990b53cf412', '晚過盤石寺禮鄭和尚', '晚過盤石寺禮鄭和尚', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["暫詣高僧話，來尋野寺孤。","岸花藏水碓，谿水映風爐。","頂上巢新鵲，衣中帶舊珠。","談禪未得去，輟櫂且踟躕。"]', '["暫詣高僧話，来尋野寺孤。","岸花藏水碓，谿水映风爐。","頂上巢新鵲，衣中带旧珠。","談禪未得去，輟櫂且踟躕。"]', '诗', 'shi', '', NULL, '晚過盤石寺禮鄭和尚 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1c394cb-ae30-4e58-b94b-b7ccff9cea5f', '尋少室張山人聞與偃師周明府同入都', '尋少室張山人闻與偃師周明府同入都', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["中峰鍊金客，昨日遊人間。","葉縣鳧共去，葛陂龍暫還。","春雲湊深水，秋雨懸空山。","寂寂清谿上，空餘丹竈閑。"]', '["中峰鍊金客，昨日游人间。","葉縣鳧共去，葛陂龙暫還。","春云湊深水，秋雨懸空山。","寂寂清谿上，空餘丹竈闲。"]', '诗', 'shi', '', NULL, '尋少室張山人聞與偃師周明府同入都 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bc9be69-d53b-40c5-8ace-163dbfa5260c', '虢州臥疾喜劉判官相過水亭', '虢州臥疾喜劉判官相過水亭', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["臥疾嘗晏起，朝來頭未梳。","見君勝服藥，清話病能除。","低柳共繫馬，小池堪釣魚。","觀棋不覺暝，月出水亭初。"]', '["臥疾嘗晏起，朝来头未梳。","见君勝服藥，清話病能除。","低柳共繫马，小池堪釣鱼。","观棋不覺暝，月出水亭初。"]', '诗', 'shi', '', NULL, '虢州臥疾喜劉判官相過水亭 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d986d292-aede-419a-b03b-2c685e32ff3e', '武威春暮聞宇文判官西使還已到晉昌', '武威春暮闻宇文判官西使還已到晉昌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["岸雨過城頭，黃鸝上戍樓。","塞北飄客淚，邊柳挂鄉愁。","白髮悲明鏡，青春換敝裘。","君從萬里使，聞已到瓜州。"]', '["岸雨過城头，黄鸝上戍楼。","塞北飄客泪，邊柳挂乡愁。","白髮悲明镜，青春換敝裘。","君從万里使，闻已到瓜州。"]', '诗', 'shi', '', NULL, '武威春暮聞宇文判官西使還已到晉昌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d1230ef-8c29-49f7-b013-8fcf3f94ea0d', '虢州南池候嚴中丞不至', '虢州南池候嚴中丞不至', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["池上日相待，知君殊未回。","徒教柳葉長，漫使梨花開。","駟馬去不見，雙魚空往來。","思想不解說，孤負舟中杯。"]', '["池上日相待，知君殊未回。","徒教柳葉长，漫使梨花开。","駟马去不见，雙鱼空往来。","思想不解说，孤負舟中杯。"]', '诗', 'shi', '', NULL, '虢州南池候嚴中丞不至 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7575d20e-1b62-4590-b21a-70f42191a8a8', '春興思南山舊廬招柳建正字', '春兴思南山旧廬招柳建正字', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["終歲不得意，春風今復來。","自憐蓬鬢改，羞見梨花開。","西掖誠可戀，南山思早回。","園廬幸接近，相與歸蒿萊。"]', '["終歲不得意，春风今复来。","自怜蓬鬢改，羞见梨花开。","西掖誠可戀，南山思早回。","园廬幸接近，相與归蒿萊。"]', '诗', 'shi', '', NULL, '春興思南山舊廬招柳建正字 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a5fac36-da93-494c-a93f-5d10c1735cb4', '郡齋南池招楊轔', '郡斋南池招楊轔', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["郡僻人事少，雲山常眼前。","偶從池上醉，便向舟中眠。","與子居最近，周官情又偏。","閑時耐相訪，正有牀頭錢。"]', '["郡僻人事少，云山常眼前。","偶從池上醉，便向舟中眠。","與子居最近，周官情又偏。","闲时耐相訪，正有牀头錢。"]', '诗', 'shi', '', NULL, '郡齋南池招楊轔 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('606b154c-402d-4a13-a560-7e7fa8535dae', '高冠谷口招鄭鄠', '高冠谷口招鄭鄠', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["谷口來相訪，空齋不見君。","澗花然暮雨，潭樹煖春雲。","門徑稀人迹，簷峰下鹿羣。","衣裳與枕席，山靄碧氛氳。"]', '["谷口来相訪，空斋不见君。","澗花然暮雨，潭樹煖春云。","门徑稀人迹，簷峰下鹿羣。","衣裳與枕席，山靄碧氛氳。"]', '诗', 'shi', '', NULL, '高冠谷口招鄭鄠 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da097e8a-3f7b-4c3c-a17d-125314cf6895', '題新鄉王釜廳壁', '題新乡王釜廳壁', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["憐君守一尉，家計復清貧。","祿米嘗不足，俸錢供與人。","城頭蘇門樹，陌上黎陽塵。","不是舊相識，聲同心自親。"]', '["怜君守一尉，家計复清貧。","祿米嘗不足，俸錢供與人。","城头蘇门樹，陌上黎陽塵。","不是旧相識，声同心自親。"]', '诗', 'shi', '', NULL, '題新鄉王釜廳壁 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06d036e4-4c05-4000-83ff-0f208c4fa367', '題山寺僧房', '題山寺僧房', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["牕影搖羣木，牆陰載一峰。","野爐風自爇，山碓水能舂。","勤學翻知誤，爲官好欲慵。","高僧暝不見，月出但聞鐘。"]', '["牕影搖羣木，牆陰載一峰。","野爐风自爇，山碓水能舂。","勤学翻知誤，爲官好欲慵。","高僧暝不见，月出但闻鐘。"]', '诗', 'shi', '', NULL, '題山寺僧房 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45f168f2-81ab-4773-ab03-010f78d082b5', '漢上題韋氏莊', '漢上題韋氏莊', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["結茅聞楚客，卜築漢江邊。","日落數歸鳥，夜深聞扣舷。","水痕侵岸柳，山翠借廚煙。","調笑提筐婦，春來蠶幾眠。"]', '["結茅闻楚客，卜築漢江邊。","日落數归鸟，夜深闻扣舷。","水痕侵岸柳，山翠借廚煙。","調笑提筐婦，春来蠶幾眠。"]', '诗', 'shi', '', NULL, '漢上題韋氏莊 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('075c697f-4e90-48f3-8dcc-625a6fdb8ed4', '題永樂韋少府廳壁', '題永乐韋少府廳壁', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["大河南郭外，終日氣昏昏。","白鳥下公府，青山當縣門。","故人是邑尉，過客駐征軒。","不憚煙波闊，思君一笑言。"]', '["大河南郭外，終日氣昏昏。","白鸟下公府，青山當縣门。","故人是邑尉，過客駐征軒。","不憚煙波闊，思君一笑言。"]', '诗', 'shi', '', NULL, '題永樂韋少府廳壁 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8838562d-a64b-4e02-a707-ed044254e8b2', '題金城臨河驛樓', '題金城臨河驛楼', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["古戍依重險，高樓見五涼。","山根盤驛道，河水浸城牆。","庭樹巢鸚鵡，園花隱麝香。","忽如江浦上，憶作捕魚郎。"]', '["古戍依重險，高楼见五涼。","山根盤驛道，河水浸城牆。","庭樹巢鸚鵡，园花隐麝香。","忽如江浦上，憶作捕鱼郎。"]', '诗', 'shi', '', NULL, '題金城臨河驛樓 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af278a58-b504-4703-a2f0-eb6f5a31160a', '初授官題高冠草堂', '初授官題高冠草堂', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["三十始一命，宦情多欲闌。","自憐無舊業，不敢恥微官。","澗水吞樵路，山花醉藥欄。","秪緣五斗米，辜負一漁竿。"]', '["三十始一命，宦情多欲闌。","自怜無旧業，不敢恥微官。","澗水吞樵路，山花醉藥欄。","秪緣五斗米，辜負一漁竿。"]', '诗', 'shi', '', NULL, '初授官題高冠草堂 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5d991e6-38fa-40dc-ac49-acf47534095c', '題虢州西樓', '題虢州西楼', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["錯料一生事，蹉跎今白頭。","縱橫皆失計，妻子也堪羞。","明主雖然棄，丹心亦未休。","愁來無去處，祗上郡西樓。"]', '["錯料一生事，蹉跎今白头。","縱橫皆失計，妻子也堪羞。","明主雖然棄，丹心亦未休。","愁来無去处，祗上郡西楼。"]', '诗', 'shi', '', NULL, '題虢州西樓 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('941f0750-3bb4-449e-b184-c7fb60bbcecf', '夜過盤石隔河望永樂寄閨中效齊梁體', '夜過盤石隔河望永乐寄閨中效齊梁體', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["盈盈一水隔，寂寂二更初。","波上思羅襪，魚邊憶素書。","月如眉已畫，雲似鬢新梳。","春物知人意，桃花笑索居。"]', '["盈盈一水隔，寂寂二更初。","波上思羅襪，鱼邊憶素书。","月如眉已畫，云似鬢新梳。","春物知人意，桃花笑索居。"]', '诗', 'shi', '', NULL, '夜過盤石隔河望永樂寄閨中效齊梁體 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e8c6ead-4285-4dfc-bbe2-7907d66ecd60', '河西春暮憶秦中', '河西春暮憶秦中', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["渭北春已老，河西人未歸。","邊城細草出，客館梨花飛。","別後鄉夢數，昨來家信稀。","涼州三月半，猶未脫寒衣。"]', '["渭北春已老，河西人未归。","邊城細草出，客館梨花飞。","別後乡梦數，昨来家信稀。","涼州三月半，猶未脫寒衣。"]', '诗', 'shi', '', NULL, '河西春暮憶秦中 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34c6e792-41b4-4961-8841-50dddc9afc0d', '過酒泉憶杜陵別業', '過酒泉憶杜陵別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["昨夜宿[祈]連，今朝過酒泉。","黃沙西際海，白草北連天。","愁裏難消日，歸期尚隔年。","陽關萬里夢，知處杜陵田。"]', '["昨夜宿[祈]連，今朝過酒泉。","黄沙西際海，白草北連天。","愁裏难消日，归期尚隔年。","陽关万里梦，知处杜陵田。"]', '诗', 'shi', '', NULL, '過酒泉憶杜陵別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('799bb8ec-001a-4658-aa27-ce9b43b3af79', '早發焉耆懷終南別業', '早發焉耆懷終南別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["曉笛別鄉淚，秋冰鳴馬蹄。","一身虜雲外，萬里胡天西。","終日見征戰，連年聞鼓鼙。","故山在何處，昨日夢清谿。"]', '["晓笛別乡泪，秋冰鳴马蹄。","一身虜云外，万里胡天西。","終日见征戰，連年闻鼓鼙。","故山在何处，昨日梦清谿。"]', '诗', 'shi', '', NULL, '早發焉耆懷終南別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65370061-0dee-4946-8001-72968f6ba4cf', '宿鐵關西館', '宿鐵关西館', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["馬汗踏成泥，朝馳幾萬蹄。","雪中行地角，火處宿天倪。","塞迥心常怯，鄉遙夢亦迷。","那知故園月，也到鐵關西。"]', '["马汗踏成泥，朝驰幾万蹄。","雪中行地角，火处宿天倪。","塞迥心常怯，乡遙梦亦迷。","那知故园月，也到鐵关西。"]', '诗', 'shi', '', NULL, '宿鐵關西館 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2fc35c7-6fc6-467f-860d-57258912f837', '首秋輪臺', '首秋輪台', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["異域陰山外，孤城雪海邊。","秋來唯有雁，夏盡不聞蟬。","雨拂氊牆濕，風搖毳幕羶。","輪臺萬里地，無事歷三年。"]', '["異域陰山外，孤城雪海邊。","秋来唯有雁，夏尽不闻蟬。","雨拂氊牆濕，风搖毳幕羶。","輪台万里地，無事歷三年。"]', '诗', 'shi', '', NULL, '首秋輪臺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56829847-cde6-43e5-a01f-9a35ed3b4f75', '北庭作', '北庭作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["雁塞通鹽澤，龍堆接醋溝。","孤城天北畔，絕域海西頭。","秋雪春仍下，朝風夜不休。","可知年四十，猶自未對侯。"]', '["雁塞通鹽澤，龙堆接醋溝。","孤城天北畔，絕域海西头。","秋雪春仍下，朝风夜不休。","可知年四十，猶自未对侯。"]', '诗', 'shi', '', NULL, '北庭作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e7379f3-1485-48e1-adb5-c55a4a0fa0d6', '輪臺即事', '輪台即事', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["輪臺風物異，地是古單于。","三月無青草，千家盡白榆。","蕃書文字別，胡俗語音殊。","愁見流沙北，天西海一隅。"]', '["輪台风物異，地是古單于。","三月無青草，千家尽白榆。","蕃书文字別，胡俗語音殊。","愁见流沙北，天西海一隅。"]', '诗', 'shi', '', NULL, '輪臺即事 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a69f46d-4f3e-4702-bec3-f558896c639a', '還東山洛上作', '還东山洛上作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["春流急不淺，歸栧去何遲。","愁客葉舟裏，夕陽花水時。","雲晴開螮蝀，櫂發起鸕鷀。","莫道東山遠，衡門在夢思。"]', '["春流急不淺，归栧去何遲。","愁客葉舟裏，夕陽花水时。","云晴开螮蝀，櫂發起鸕鷀。","莫道东山远，衡门在梦思。"]', '诗', 'shi', '', NULL, '還東山洛上作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ede5d2f0-2250-4ce0-928a-189b8f78be3a', '楊固店', '楊固店', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["客舍梨葉赤，鄰家聞擣衣。","夜來嘗有夢，墜淚緣思歸。","洛水行欲盡，緱山看漸微。","長安祗千里，何事信音稀。"]', '["客舍梨葉赤，鄰家闻擣衣。","夜来嘗有梦，墜泪緣思归。","洛水行欲尽，緱山看漸微。","长安祗千里，何事信音稀。"]', '诗', 'shi', '', NULL, '楊固店 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0180137-77aa-45ae-bcef-bcb9871b16cf', '巴南舟中思陸渾別業', '巴南舟中思陸渾別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["瀘水南州遠，巴山北客稀。","嶺雲撩亂起，谿鷺等閑飛。","鏡裏愁衰鬢，舟中換旅衣。","夢魂知憶處，無夜不先歸。"]', '["瀘水南州远，巴山北客稀。","嶺云撩亂起，谿鷺等闲飞。","镜裏愁衰鬢，舟中換旅衣。","梦魂知憶处，無夜不先归。"]', '诗', 'shi', '', NULL, '巴南舟中思陸渾別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc644572-a42e-4f61-a13b-14ec8b31d6cb', '晚發五渡', '晚發五渡', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["客厭巴南地，鄉鄰劒北天。","江村片雨外，野寺夕陽邊。","芋葉藏山徑，蘆花雜渚田。","舟行未可住，乘月且須牽。"]', '["客厭巴南地，乡鄰劒北天。","江村片雨外，野寺夕陽邊。","芋葉藏山徑，蘆花杂渚田。","舟行未可住，乘月且須牽。"]', '诗', 'shi', '', NULL, '晚發五渡 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df0c041e-296c-4d2d-aacc-a3cd2a3ea5ce', '巴南舟中夜市', '巴南舟中夜市', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["渡口欲黃昏，歸人爭渡喧。","近鐘清野寺，遠火點江村。","見雁思鄉信，聞猿積淚痕。","孤舟萬里外，秋月不堪論。"]', '["渡口欲黄昏，归人爭渡喧。","近鐘清野寺，远火点江村。","见雁思乡信，闻猿積泪痕。","孤舟万里外，秋月不堪論。"]', '诗', 'shi', '', NULL, '巴南舟中夜市 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('090d3800-346b-438e-b46f-3721f5e98c9a', '江上春歎', '江上春歎', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["臘月江上煖，南橋新柳枝。","春風觸處到，憶得故園時。","終日不如意，出門何所之。","從人覓顏色，自笑弱男兒。"]', '["臘月江上煖，南橋新柳枝。","春风觸处到，憶得故园时。","終日不如意，出门何所之。","從人覓顏色，自笑弱男兒。"]', '诗', 'shi', '', NULL, '江上春歎 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d6c53a6-b931-415f-b64b-d5865fbdc3dd', '初至犍爲作', '初至犍爲作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["山色軒檻內，灘聲枕席間。","草生公府靜，花落訟庭閒。","雲雨連三峽，風塵接百蠻。","到來能幾日，不覺鬢毛斑。"]', '["山色軒檻內，灘声枕席间。","草生公府静，花落訟庭閒。","云雨連三峽，风塵接百蠻。","到来能幾日，不覺鬢毛斑。"]', '诗', 'shi', '', NULL, '初至犍爲作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f1e6bb4-4e9f-4b79-bac6-235db11ae50f', '使院中新栽柏樹子呈李十五栖筠', '使院中新栽柏樹子呈李十五栖筠', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["愛爾青青色，移根此地來。","不曾臺上種，留向磧中栽。","脆葉欺門柳，狂花笑院梅。","不須愁歲晚，霜露豈能摧。"]', '["愛爾青青色，移根此地来。","不曾台上種，留向磧中栽。","脆葉欺门柳，狂花笑院梅。","不須愁歲晚，霜露豈能摧。"]', '诗', 'shi', '', NULL, '使院中新栽柏樹子呈李十五栖筠 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('897e5256-c002-441c-80de-af184c77a3bd', '詠郡齋壁畫片雲', '詠郡斋壁畫片云', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["雲片何人畫，塵侵粉色微。","未曾行雨去，不見逐風歸。","只怪偏凝壁，回看欲惹衣。","丹青忽借便，移向帝鄉飛。"]', '["云片何人畫，塵侵粉色微。","未曾行雨去，不见逐风归。","只怪偏凝壁，回看欲惹衣。","丹青忽借便，移向帝乡飞。"]', '诗', 'shi', '', NULL, '詠郡齋壁畫片雲 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d9dc1c0-b0af-4ff4-ba99-29168239d1f1', '臨洮龍興寺玄上人院同詠青木香叢', '臨洮龙兴寺玄上人院同詠青木香叢', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["移根自遠方，種得在僧房。","六月花新吐，三春葉已長。","抽莖高錫杖，引影到繩牀。","只爲能除疾，傾心向藥王。"]', '["移根自远方，種得在僧房。","六月花新吐，三春葉已长。","抽莖高錫杖，引影到繩牀。","只爲能除疾，傾心向藥王。"]', '诗', 'shi', '', NULL, '臨洮龍興寺玄上人院同詠青木香叢 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff6e3381-70ea-49e4-bffd-3529930e9eca', '成王挽歌', '成王挽歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["幽山悲舊桂，長坂愴餘蘭。","地底孤燈冷，泉中一鏡寒。","銘旌門客送，騎吹路人看。","漫作琉璃椀，淮王誤合丹。"]', '["幽山悲旧桂，长坂愴餘蘭。","地底孤灯冷，泉中一镜寒。","銘旌门客送，騎吹路人看。","漫作琉璃椀，淮王誤合丹。"]', '诗', 'shi', '', NULL, '成王挽歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07facfea-c701-45af-bc84-2f86c5bbbbb9', '苗侍中挽歌二首 一', '苗侍中挽歌二首 一', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["攝政朝章重，持衡國相尊。","筆端通造化，掌內運乾坤。","青史遺芳滿，黃樞故事存。","空悲渭橋路，誰對漢皇言。"]', '["攝政朝章重，持衡国相尊。","笔端通造化，掌內運乾坤。","青史遺芳满，黄樞故事存。","空悲渭橋路，誰对漢皇言。"]', '诗', 'shi', '', NULL, '苗侍中挽歌二首 一 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c9bc07f-1133-41c2-8654-e367b8b3af4f', '苗侍中挽歌二首 二', '苗侍中挽歌二首 二', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["天子悲元老，都人惜上公。","優賢几杖在，會葬市朝空。","丹旐飛斜日，清笳怨暮風。","平生門下客，繼美廟堂中。"]', '["天子悲元老，都人惜上公。","優賢几杖在，會葬市朝空。","丹旐飞斜日，清笳怨暮风。","平生门下客，繼美廟堂中。"]', '诗', 'shi', '', NULL, '苗侍中挽歌二首 二 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80968441-1503-4a6d-87be-31a5b7a6480b', '故僕射裴公挽歌三首 一', '故僕射裴公挽歌三首 一', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["盛德資邦傑，嘉謨作世程。","門瞻駟馬貴，時仰八龍名。","罷市秦人送，還鄉絳老迎。","莫埋丞相印，留着付玄成。"]', '["盛德資邦傑，嘉謨作世程。","门瞻駟马貴，时仰八龙名。","罷市秦人送，還乡絳老迎。","莫埋丞相印，留着付玄成。"]', '诗', 'shi', '', NULL, '故僕射裴公挽歌三首 一 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cc8ca36-fce5-425c-afda-bccb6fd979a1', '故僕射裴公挽歌三首 二', '故僕射裴公挽歌三首 二', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["五府瞻高位，三台喪大賢。","禮容還故絳，寵贈冠新田。","氣歇汾陰鼎，魂飛京兆阡。","先時劒已沒，隴樹久蒼然。"]', '["五府瞻高位，三台喪大賢。","禮容還故絳，寵贈冠新田。","氣歇汾陰鼎，魂飞京兆阡。","先时劒已沒，隴樹久蒼然。"]', '诗', 'shi', '', NULL, '故僕射裴公挽歌三首 二 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b743f03-a8c1-4949-af0f-c979c820fc39', '故僕射裴公挽歌三首 三', '故僕射裴公挽歌三首 三', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["富貴徒言久，鄉閭歿後歸。","錦衣都未着，丹旐忽先飛。","哀挽辭秦塞，悲笳出帝畿。","遙知九原上，漸覺弔人稀。"]', '["富貴徒言久，乡閭歿後归。","錦衣都未着，丹旐忽先飞。","哀挽辞秦塞，悲笳出帝畿。","遙知九原上，漸覺弔人稀。"]', '诗', 'shi', '', NULL, '故僕射裴公挽歌三首 三 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b626c58d-f3c4-437d-af00-d7827fac12b7', '河西太守杜公挽歌四首 一', '河西太守杜公挽歌四首 一', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["蒙叟悲藏壑，殷宗惜濟川。","長安非舊日，京兆是新阡。","黃霸官猶屈，蒼生望已愆。","唯餘卿月在，留向杜陵懸。"]', '["蒙叟悲藏壑，殷宗惜濟川。","长安非旧日，京兆是新阡。","黄霸官猶屈，蒼生望已愆。","唯餘卿月在，留向杜陵懸。"]', '诗', 'shi', '', NULL, '河西太守杜公挽歌四首 一 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd376965-fe7e-48ab-ab69-f88275a08101', '河西太守杜公挽歌四首 二', '河西太守杜公挽歌四首 二', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["鼓角城中出，墳塋郭外新。","雨隨思太守，雲從送夫人。","蒿里埋雙劒，松門閉萬春。","回瞻北堂上，金印已生塵。"]', '["鼓角城中出，墳塋郭外新。","雨隨思太守，云從送夫人。","蒿里埋雙劒，松门閉万春。","回瞻北堂上，金印已生塵。"]', '诗', 'shi', '', NULL, '河西太守杜公挽歌四首 二 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcd03ce6-61c8-4fcd-9f14-59f4856e28d5', '河西太守杜公挽歌四首 三', '河西太守杜公挽歌四首 三', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["憶昨明光殿，新承天子恩。","剖符移北地，授鉞領西門。","塞草迎軍幕，邊雲拂使軒。","至今聞隴外，戎虜尚亡魂。"]', '["憶昨明光殿，新承天子恩。","剖符移北地，授鉞領西门。","塞草迎軍幕，邊云拂使軒。","至今闻隴外，戎虜尚亡魂。"]', '诗', 'shi', '', NULL, '河西太守杜公挽歌四首 三 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ac4a3c1-ccb0-4d25-8a4e-c76b6a384b74', '河西太守杜公挽歌四首 四', '河西太守杜公挽歌四首 四', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["漫漫澄波闊，沈沈大廈深。","秉心常匪席，行義每揮金。","汲引窺蘭室，招攜入翰林。","多君有令子，猶注世人心。"]', '["漫漫澄波闊，沈沈大廈深。","秉心常匪席，行義每揮金。","汲引窺蘭室，招携入翰林。","多君有令子，猶注世人心。"]', '诗', 'shi', '', NULL, '河西太守杜公挽歌四首 四 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e7488b-3c97-4739-9e36-6c28452295d9', '故河南尹岐國公贈工部尚書蘇公挽歌二首 一', '故河南尹岐国公贈工部尚书蘇公挽歌二首 一', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["河尹恩榮舊，尚書寵贈新。","一門傳畫戟，幾世駕朱輪。","夜色何時曉，泉臺不復春。","唯餘朝服在，金印已生塵。"]', '["河尹恩榮旧，尚书寵贈新。","一门傳畫戟，幾世駕朱輪。","夜色何时晓，泉台不复春。","唯餘朝服在，金印已生塵。"]', '诗', 'shi', '', NULL, '故河南尹岐國公贈工部尚書蘇公挽歌二首 一 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61ac11ab-471c-4bcc-bac8-33ffb6f7ccdf', '故河南尹岐國公贈工部尚書蘇公挽歌二首 二', '故河南尹岐国公贈工部尚书蘇公挽歌二首 二', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["白日扃泉戶，青春掩夜臺。","舊堂階草長，空院砌花開。","山晚銘旌去，郊寒騎吹回。","三川難可見，應惜庾公才。"]', '["白日扃泉戶，青春掩夜台。","旧堂階草长，空院砌花开。","山晚銘旌去，郊寒騎吹回。","三川难可见，應惜庾公才。"]', '诗', 'shi', '', NULL, '故河南尹岐國公贈工部尚書蘇公挽歌二首 二 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a19de5f-182b-4dcc-865d-e73c67806460', '韓員外夫人清河縣君崔氏挽歌二首 一', '韓員外夫人清河縣君崔氏挽歌二首 一', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["令德當時重，高門舉世推。","從夫榮已絕，封邑寵難追。","陌上人皆惜，花間鳥亦悲。","仙郎看隴月，猶憶畫眉時。"]', '["令德當时重，高门舉世推。","從夫榮已絕，封邑寵难追。","陌上人皆惜，花间鸟亦悲。","仙郎看隴月，猶憶畫眉时。"]', '诗', 'shi', '', NULL, '韓員外夫人清河縣君崔氏挽歌二首 一 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11d10305-fe34-4447-9547-149db5c95acc', '韓員外夫人清河縣君崔氏挽歌二首 二', '韓員外夫人清河縣君崔氏挽歌二首 二', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["遽聞傷別劒，忽復歎藏舟。","燈冷泉中夜，衣寒地下秋。","青松弔客淚，丹旐路人愁。","徒有清河在，空悲逝水流。"]', '["遽闻傷別劒，忽复歎藏舟。","灯冷泉中夜，衣寒地下秋。","青松弔客泪，丹旐路人愁。","徒有清河在，空悲逝水流。"]', '诗', 'shi', '', NULL, '韓員外夫人清河縣君崔氏挽歌二首 二 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2b7e556-c319-4639-ae99-50a9f1957998', '西河郡太原守張夫人挽歌', '西河郡太原守張夫人挽歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["鵲印慶仍傳，魚軒寵莫先。","從夫元凱貴，訓子孟軻賢。","龍是雙歸日，鸞非獨舞年。","哀容今共盡，悽愴杜陵田。"]', '["鵲印慶仍傳，鱼軒寵莫先。","從夫元凱貴，訓子孟軻賢。","龙是雙归日，鸾非独舞年。","哀容今共尽，悽愴杜陵田。"]', '诗', 'shi', '', NULL, '西河郡太原守張夫人挽歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd39dd1e-3fad-4c0e-b3b1-dacc6e1c0ba7', '南溪別業', '南溪別業', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["結宇依青嶂，開軒對翠疇。","樹交花兩色，溪合水重流。","竹徑春來埽，蘭樽夜不收。","逍遙自得意，鼓腹醉中遊。"]', '["結宇依青嶂，开軒对翠疇。","樹交花兩色，溪合水重流。","竹徑春来埽，蘭樽夜不收。","逍遙自得意，鼓腹醉中游。"]', '诗', 'shi', '', NULL, '南溪別業 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8df8e94b-ffe4-4930-af4c-491d7cb04651', '奉和中書舍人賈至早朝大明宮', '奉和中书舍人賈至早朝大明宮', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["雞鳴紫陌曙光寒，鶯囀皇州春色闌。","金闕曉鐘開萬戶，玉階仙仗擁千官。","花迎劒珮星初落，柳拂旌旗露未乾。","獨有鳳皇池上客，陽春一曲和皆難。"]', '["雞鳴紫陌曙光寒，鶯囀皇州春色闌。","金闕晓鐘开万戶，玉階仙仗擁千官。","花迎劒珮星初落，柳拂旌旗露未乾。","独有鳳皇池上客，陽春一曲和皆难。"]', '诗', 'shi', '', NULL, '奉和中書舍人賈至早朝大明宮 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fd481a8-ef2b-4d69-9dd6-f1f25ebb3d3d', '和祠部王員外雪後早朝即事', '和祠部王員外雪後早朝即事', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["長安雪後似春歸，積素凝華連曙暉。","色借玉珂迷曉騎，光添銀燭晃朝衣。","西山落月臨天仗，北闕晴雲捧禁闈。","聞道仙郎歌白雪，由來此曲和人稀。"]', '["长安雪後似春归，積素凝华連曙暉。","色借玉珂迷晓騎，光添銀燭晃朝衣。","西山落月臨天仗，北闕晴云捧禁闈。","闻道仙郎歌白雪，由来此曲和人稀。"]', '诗', 'shi', '', NULL, '和祠部王員外雪後早朝即事 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33b81898-2637-46c9-a34f-b2c15de78aac', '奉和相公發益昌', '奉和相公發益昌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["相[國]臨戎別帝京，擁麾持節遠橫行。","朝登劒閣雲隨馬，夜渡巴江雨洗兵。","山花萬朵迎征蓋，川柳千條拂去旌。","暫到蜀城應計日，須知明主待持衡。"]', '["相[国]臨戎別帝京，擁麾持節远橫行。","朝登劒閣云隨马，夜渡巴江雨洗兵。","山花万朵迎征蓋，川柳千條拂去旌。","暫到蜀城應計日，須知明主待持衡。"]', '诗', 'shi', '', NULL, '奉和相公發益昌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fef49ff-5115-4129-88e1-e484fecf236e', '秋夕讀書幽興獻兵部李侍郎', '秋夕读书幽兴獻兵部李侍郎', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["年紀蹉跎四十強，自憐頭白始爲郎。","雨滋苔蘚侵堦綠，秋颯梧桐覆井黃。","驚蟬也解求高樹，旅雁還應厭後行。","覽卷試穿鄰舍壁，明燈何惜借餘光。"]', '["年紀蹉跎四十強，自怜头白始爲郎。","雨滋苔蘚侵堦綠，秋颯梧桐覆井黄。","驚蟬也解求高樹，旅雁還應厭後行。","覽卷試穿鄰舍壁，明灯何惜借餘光。"]', '诗', 'shi', '', NULL, '秋夕讀書幽興獻兵部李侍郎 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59a041cd-30cd-473c-a70e-9b0328ad56df', '使君席夜送嚴河南赴長水', '使君席夜送嚴河南赴长水', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["嬌歌急管雜青絲，銀燭金杯映翠眉。","使君地主能相送，河尹天明坐莫辭。","春城月出人皆醉，野戍花深馬去遲。","寄聲報爾山翁道，今日河南勝昔時。"]', '["嬌歌急管杂青絲，銀燭金杯映翠眉。","使君地主能相送，河尹天明坐莫辞。","春城月出人皆醉，野戍花深马去遲。","寄声報爾山翁道，今日河南勝昔时。"]', '诗', 'shi', '', NULL, '使君席夜送嚴河南赴長水 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5750096c-2a14-421b-ba44-a45fd3069ce9', '暮春虢州東亭送李司馬歸扶風別廬', '暮春虢州东亭送李司马归扶风別廬', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["柳嚲鶯嬌花復殷，紅亭綠酒送君還。","到來函谷愁中月，歸去磻谿夢裏山。","簾前春色應須惜，世上浮名好是閑。","西望鄉關腸欲斷，對君衫袖淚痕斑。"]', '["柳嚲鶯嬌花复殷，紅亭綠酒送君還。","到来函谷愁中月，归去磻谿梦裏山。","簾前春色應須惜，世上浮名好是闲。","西望乡关腸欲斷，对君衫袖泪痕斑。"]', '诗', 'shi', '', NULL, '暮春虢州東亭送李司馬歸扶風別廬 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66c7a0ea-52b7-4f2d-b60d-bf0fc5540b83', '九日使君席奉餞衛中丞赴長水', '九日使君席奉餞衛中丞赴长水', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["節使橫行西出師，鳴弓擐甲羽林兒。","臺上霜風凌草木，軍中殺氣傍旌旗。","預知漢將宣威日，正是胡塵欲滅時。","爲報使君多泛菊，更將絃管醉東籬。"]', '["節使橫行西出師，鳴弓擐甲羽林兒。","台上霜风凌草木，軍中殺氣傍旌旗。","預知漢將宣威日，正是胡塵欲滅时。","爲報使君多泛菊，更將絃管醉东籬。"]', '诗', 'shi', '', NULL, '九日使君席奉餞衛中丞赴長水 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed73287-c270-4b17-bab5-5f1208f81a41', '西掖省即事', '西掖省即事', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["西掖重雲開曙暉，北山疎雨點朝衣。","千門柳色連青瑣，三殿花香入紫微。","平明端笏陪鵷列，薄暮垂鞭信馬歸。","官拙自悲頭白盡，不如巖下偃荆扉。"]', '["西掖重云开曙暉，北山疎雨点朝衣。","千门柳色連青瑣，三殿花香入紫微。","平明端笏陪鵷列，薄暮垂鞭信马归。","官拙自悲头白尽，不如巖下偃荆扉。"]', '诗', 'shi', '', NULL, '西掖省即事 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ceccfa-e17f-4894-9173-eda8431da244', '首春渭西郊行呈藍田張二主簿', '首春渭西郊行呈藍田張二主簿', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["迥風度雨渭城西，細草新花踏作泥。","秦女峰頭雪未盡，胡公阪上日初低。","愁窺白髮羞微祿，悔別青山憶舊谿。","聞道輞川多勝事，玉壺春酒正堪攜。"]', '["迥风度雨渭城西，細草新花踏作泥。","秦女峰头雪未尽，胡公阪上日初低。","愁窺白髮羞微祿，悔別青山憶旧谿。","闻道輞川多勝事，玉壺春酒正堪携。"]', '诗', 'shi', '', NULL, '首春渭西郊行呈藍田張二主簿 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144d614b-8719-4abb-9912-a49938f9f478', '赴嘉州過城固縣尋永安超禪師房', '赴嘉州過城固縣尋永安超禪師房', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["滿寺枇杷冬着花，老僧相見具袈裟。","漢王城北雪初霽，韓信臺西日欲斜。","門外不須催五馬，林中且聽演三車。","豈料巴川多勝事，爲君書此報京華。"]', '["满寺枇杷冬着花，老僧相见具袈裟。","漢王城北雪初霽，韓信台西日欲斜。","门外不須催五马，林中且听演三车。","豈料巴川多勝事，爲君书此報京华。"]', '诗', 'shi', '', NULL, '赴嘉州過城固縣尋永安超禪師房 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6326e769-0ca2-40d1-99ca-5e390fc4f6d4', '酬暢當嵩山尋麻道士見寄', '酬暢當嵩山尋麻道士见寄', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["聞逐樵夫閑看棋，忽逢人世是秦時。","開雲種玉嫌山淺，渡海傳書怪鶴遲。","陰洞石幢微有字，古壇松樹半無枝。","煩君遠示青囊錄，願得相從一問師。"]', '["闻逐樵夫闲看棋，忽逢人世是秦时。","开云種玉嫌山淺，渡海傳书怪鹤遲。","陰洞石幢微有字，古壇松樹半無枝。","煩君远示青囊錄，願得相從一问師。"]', '诗', 'shi', '', NULL, '酬暢當嵩山尋麻道士見寄 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01655f93-334b-4946-a837-251f48544016', '和刑部成員外秋夜寓直寄臺省知己', '和刑部成員外秋夜寓直寄台省知己', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["列宿光三署，仙郎直五宵。","時衣天子賜，廚膳大官調。","長樂鐘應近，明光漏不遙。","黃門持被覆，侍女捧香燒。","筆爲題詩點，燈緣起草挑。","竹喧交砌葉，柳嚲拂牕條。","粉署榮新命，霜臺憶舊僚。","名香播蘭蕙，重價蘊瓊瑤。","擊水翻滄海，[摶]風透赤霄。","微才喜同舍，何幸忽聞韶。"]', '["列宿光三署，仙郎直五宵。","时衣天子賜，廚膳大官調。","长乐鐘應近，明光漏不遙。","黄门持被覆，侍女捧香燒。","笔爲題诗点，灯緣起草挑。","竹喧交砌葉，柳嚲拂牕條。","粉署榮新命，霜台憶旧僚。","名香播蘭蕙，重價蘊瓊瑤。","擊水翻滄海，[摶]风透赤霄。","微才喜同舍，何幸忽闻韶。"]', '诗', 'shi', '', NULL, '和刑部成員外秋夜寓直寄臺省知己 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9735cba2-2b9c-4adf-b091-6e780b070121', '送廬郎中除杭州赴任', '送廬郎中除杭州赴任', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["罷起郎官草，初分刺史符。","海雲迎過楚，江月引歸吳。","城低濤聲震，樓端蜃氣孤。","千家窺驛舫，五馬飲春湖。","柳色供詩用，鶯聲送酒須。","知君望鄉處，枉道上姑蘇。"]', '["罷起郎官草，初分刺史符。","海云迎過楚，江月引归吳。","城低濤声震，楼端蜃氣孤。","千家窺驛舫，五马饮春湖。","柳色供诗用，鶯声送酒須。","知君望乡处，枉道上姑蘇。"]', '诗', 'shi', '', NULL, '送廬郎中除杭州赴任 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1200b978-8036-48a0-8309-f7025e346885', '奉送李賓客荆南迎親', '奉送李賓客荆南迎親', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["迎親辭舊苑，恩詔下儲闈。","昨見雙魚去，今看駟馬歸。","驛帆湘水闊，客舍楚山稀。","手把黃香扇，身披萊子衣。","鵲隨金印喜，烏傍板輿飛。","勝作東征賦，還家滿路輝。"]', '["迎親辞旧苑，恩詔下儲闈。","昨见雙鱼去，今看駟马归。","驛帆湘水闊，客舍楚山稀。","手把黄香扇，身披萊子衣。","鵲隨金印喜，烏傍板輿飞。","勝作东征賦，還家满路輝。"]', '诗', 'shi', '', NULL, '奉送李賓客荆南迎親 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c708dbc3-03b5-4fe6-a1f6-329ffb39f227', '送嚴維下第還江東', '送嚴維下第還江东', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["勿歎今不第，似君殊未遲。","且歸滄洲去，相送青門時。","望鳥指鄉遠，問人愁路疑。","敝裘沾暮雪，歸櫂帶流澌。","嚴子灘復在，謝公文可追。","江臯如有信，莫不寄新詩。"]', '["勿歎今不第，似君殊未遲。","且归滄洲去，相送青门时。","望鸟指乡远，问人愁路疑。","敝裘沾暮雪，归櫂带流澌。","嚴子灘复在，謝公文可追。","江臯如有信，莫不寄新诗。"]', '诗', 'shi', '', NULL, '送嚴維下第還江東 岑參 shi');
